(window.GIM_TS=window.GIM_TS||{})["Yoma.1"]={"from":24,"a":[["שר' יהודה בא להחמיר ו\u0003לומר שאינו עובד כל היום,\u0004 אף שהדבר מותר לו מן התורה \u0003גזירה שמא\u0004 ישכח ו\u0003יאכל\u0004 מן הקדשים שאסורים לו באכילה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא: ומי\u0004 \u0005[והאם]\u0006 \u0003גזר ר' יהודה שמא יאכל? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ר' יהודה אומר: אף אשה אחרת מתקינין לו, שמא תמות אשתו. ואי מייתא\u0004 \u0005[ואם מתה]\u0006 \u0003אשתו\u0004 בכל זאת \u0003עביד\u0004 \u0005[עובד]\u0006 הוא את ה\u0003עבודה\u0004 במקדש, \u0003ולא גזר ר' יהודה שמא יאכל,\u0004 והרי זה בניגוד לפירוש שגזר ר' יהודה שאין כהן גדול עובד ביום אנינותו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במשנה \u0003כיון\u0004 ש\u0003יום הכפורים הוא, דכולי עלמא לא קא אכלי\u0004 \u0005[שהכל אינם אוכלים],\u0006 \u0003הוא נמי לא אתי למיכל\u0004 \u0005[הוא גם כן לא יבוא לאכול],\u0006 אבל \u0003הכא, דכולי עלמא אכלי\u0004 \u0005[כאן,\u0006 בשאר ימות השנה, \u0005שכל העולם אוכלים] —\u0006 \u0003הוא נמי אתי למיכל\u0004 \u0005[גם כן יבוא לאכול]\u0006 ולכן יש מקום לגזור.","מצד אחר שואלים על קושיה זו: \u0003וכי האי גוונא מי חיילא עליה\u0004 \u0005[ובאופן כזה האם חלה עליו\u0006 חובת\u0005]\u0006 \u0003אנינות? והא מיגרשא\u0004 \u0005[והרי\u0006 היא \u0005מגורשת]\u0006 שהרי הסברנו שלשיטת ר' יהודה צריך לגרש אותה על תנאי, ואם כן נמצא שאינה עוד אשתו. ואין כאן אנינות לפי הדין! ומשיבים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 שה\u0003אנינות לא חייל עליה\u0004 \u0005[אינה חלה עליו],\u0006 מכל מקום \u0003אטרודי מי לא מיטריד\u0004 \u0005[האם איננו טרוד]\u0006 ומצטער על מות אשתו? והיה מן הראוי לאסור עליו לעסוק בעבודה לדעת ר' יהודה.","\u0003כל שבעת הימים\u0004 שפורש הכהן הגדול לפני יום הכיפורים \u0003הוא זורק את הדם\u0004 של קרבנות התמיד, \u0003ומקטיר את הקטורת, ומיטיב\u0004 (מדשן) \u0003את\u0004 אפר \u0003הנרות\u0004 שבמנורה, \u0003ומקריב את הראש ואת הרגל\u0004 של קרבן התמיד, כדי להתרגל בכל סדרי העבודה שהוא צריך לעשותם ביום הכיפורים. \u0003ושאר כל הימים\u0004 בשנה \u0003אם רצה להקריב\u0004 כל קרבן שירצה — \u0003מקריב, שכהן גדול מקריב חלק בראש\u0004 כלומר ראשון הוא להקריב כל קרבן שירצה, וגם \u0003נוטל חלק בראש\u0004 שיכול ליטול מן הקרבנות כל מנה שירצה בה.","שואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 \u0003תנא\u0004 זה ששנה משנה זו? \u0003אמר רב חסדא\u0004 משנה זו היא ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא\u0004 היא. \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' עקיבא\u0004 היא\u0003, הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 ר' עקיבא: \u0003טהור שנפלה עליו הזאה\u0004 של מי חטאת (של פרה אדומה) \u0003טמאתו\u0004 הזאה זו, כפי הכלל, שמי חטאת כשם שמטהרים את הטמאים, כך מטמאים הם את הטהורים, ואם כן \u0003היכי עביד\u0004 \u0005[כיצד\u0006 יכול הוא \u0005לעשות]\u0006 \u0003עבודה\u0004 והרי כפי שאמרנו מזים עליו בכל יום מי חטאת, והזאה זו אינה לטהרו מטומאת ודאי אלא מספק, ויש לחשוש שמא טהור היה, וממילא הזאה זו היא שמטמאתו!","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"והזה הטהר על הטמא\"\u0004 (במדבר יט, יט) שיש בכך הדגשה יתירה, לומר: אם מזה הוא \u0003על הטמא\u0004 — הרי הוא \u0003טהור,\u0004 אך אם אינו מזה על טמא כי אם \u0003על הטהור\u0004 — הרי הוא \u0003טמא,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים: אין הדברים הללו\u0004 \"על הטמא\" \u0003אמורין\u0004 אלא ללמדנו שאין קרויה הזאה \u0003אלא בדברים המקבלים טומאה,\u0004 אבל אם היזה על דבר שאינו מקבל טומאה כלל — אינה קרויה הזאה.","ו\u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 המשמעות ההלכתית של הדבר — \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006: \u0003נתכוון להזות\u0004 מי חטאת \u0003על הבהמה,\u0004 והבהמה בחייה הרי איננה מקבלת טומאה, ונזדמן ש\u0003הזה על האדם\u0004 הטמא, \u0003אם יש באזוב\u0004 שאריות מהמים — \u0003ישנה\u0004 ויזה על האדם ויטהרנו, שמתוך שהזה בסופו של דבר על האדם שהוא דבר המקבל טומאה, הרי שבכך לא נפסלו המים כדין מים שנעשו בהם מלאכה ואלו שנותרו באזוב ראויים איפוא להזאה מחודשת. אולם אם \u0003נתכוון להזות על האדם והזה על הבהמה, אם יש באזוב\u0004 עוד — \u0003לא ישנה,\u0004 כיון שהזאה הראשונה לא היתה ראויה, שהרי היזה על דבר שאינו מקבל טומאה, ובשל כך נפסלו המים שבאזוב שהרי הם כאילו נעשתה בהם מלאכה ופסולים להזאה מחודשת.","ומעתה באים לברר את יסודות המחלוקת. \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' עקיבא?\u0004 ומסבירים: \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 במקום \"והזה הטהור על הטמא\" רק \u0003\"והזה הטהר עליו\"\u0004 שהרי טמא מוזכר קודם לכן, ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדגשת הכתוב באומרו \u0003\"על הטמא\" — שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאם מזה \u0003על הטמא\u0004 — הריהו \u0003טהור,\u0004 ואם מזה \u0003על הטהור —\u0004 הריהו \u0003טמא. ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים: \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003לדברים המקבלין טומאה הוא דאתא\u0004 \u0005[שבא]\u0006 כפי שפרשנו. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 במקרה שהוזו מי חטאת על הטהור, ברור שלא השתנה דינו בכך והריהו טהור, שכן \u0003קל וחומר הוא: אם על הטמא\u0004 נופלים הם והוא \u0003טהור,\u0004 אם נפלו \u0003על הטהור לא כל שכן\u0004 שלא טימאוהו!","ושואלים: \u0003ור' עקיבא\u0004 מה משיב הוא לקל וחומר זה? — \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003שלמה\u0004 המלך \u0003\"אמרתי אחכמה והיא רחוקה ממני\"\u0004 (קהלת ז, כג) וכוונת הדברים לפי המסורת, שנתכוין שלמה לומר שאף הוא בחכמתו לא הבין את טעם ההלכה שהזאת מי חטאת המטהרת את הטמאים היא אשר מטמאה את הטהורים. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מבינים הם את תמיהתו של שלמה? ומסבירים כי הם מפרשים תמיהה זו לגבי דין אחר, כי האיש ה\u0003מזה\u0004 את מי החטאת או זה ש\u0003מזין עליו — טהור,\u0004 אבל \u0003הנוגע בהן\u0004 בלא הזיה — \u0003טמא.\u0004","ושואלים: וכי ה\u0003מזה טהור? והכתיב\u0004 \u0005[והרי כתוב]\u0006 בתורה במפורש: \u0003\"ומזה מי הנדה יכבס בגדיו\u0004 והנוגע במי הנדה יטמא עד הערב\u0003\"\u0004 (במדבר יט, כא). ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מזה\"\u0004 בכתוב זה — \u0003נוגע.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי כתוב]\u0006 בפסוק לחוד \u0003\"מזה\", והא כתיב\u0004 \u0005[והרי כתוב]\u0006 בפסוק לחוד \u0003\"נוגע\", ו\u0004ברור אם כן שמזה אינו נוגע! \u0003ועוד, מזה בעי\u0004 \u0005[צריך]\u0006 \u0003כיבוס בגדים\u0004 שמשמע שטומאתו חמורה יותר, ואילו \u0003נוגע לא בעי\u0004 \u0005[צריך]\u0006 \u0003כיבוס בגדים\u0004 וכיצד אפשר לומר שהם אחד!","\u0003אלא\u0004 כך יש לפרש על פי שיטת חכמים: \u0003מאי\u0004 \u0005[מה\u0006 פירושו\u0005]\u0006 של \u0003\"מזה\"\u0004 \u0005—\u0006 \u0003נושא\u0004 מי הנדה. ושואלים: אם כן \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 בפירוש \u0003\"נושא\", מאי טעמא כתיב\u0004 \u0005[מה טעם כתוב]\u0006 \u0003\"מזה\"\u0004 ולא נושא? ומסבירים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 על ידי שינוי לשון זה \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהיה במים שהוא נושא כדי \u0003שיעור הזאה\u0004 ואם אין בהם כדי שיעור זה — אין הנושא אותם מיטמא.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003הזאה צריכה שיעור\u0004 מסויים של מים, ואם כן קיים מושג של \"שיעור הזאה\", \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003הזאה אין צריכה שיעור\u0004 מסויים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שלפי זה אין משמעות למושג \"שיעור הזאה\"! ומשיבים: \u0003אפילו למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאומר]\u0006 כי \u0003הזאה אין צריכה שיעור — הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 כשהיזו מי חטאת \u0003אגבא דגברא\u0004 \u0005[על גבו של האדם]\u0006 הטמא, שלהזאה זו אין צורך בשיעור מסויים, ובכל שיעור שהוא, הריהו נטהר \u0003אבל במנא\u0004 \u0005[בכלי]\u0006 עצמו שבו טובלים את האזוב להזאה — \u0003צריכה\u0004 שתהיה בו \u0003שיעור\u0004 מסויים לכל הדיעות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כמה יהא בהן\u0004 במי החטאת \u0003ויהא\u0004 בהן \u0003כדי הזאה — כדי שיטבול\u0004"],["\u0003ראשי גבעולין ויזה\u0004 משמע שיש שיעור מסויים כדי הזאה. \u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו כשיטת \u0003ר' עקיבא\u0004 היא, אפשר ליישבה באופן זה: \u0003דעביד\u0004 \u0005[שעושה]\u0006 הכהן הגדול \u0003עבודה כוליה יומא\u0004 \u0005[כל היום]\u0006 בשבעת הימים הללו, \u0003ולפניא מדו עליה\u0004 \u0005[ולפנות ערב מזים עליו]\u0006 את מי החטאת, ואף אם היה אכן טהור ובהזאה זו הוא נטמא, עדיין יכול הוא לטבול מיד \u0003ועביד\u0004 \u0005[ועושה]\u0006 \u0003הערב השמש,\u0004 וכשמגיע הלילה הרי הוא שוב טהור גמור, וראוי לעבודה למחר.","שנינו במשנה כי באותם שבעה ימים היה הכהן הגדול \u0003מקטיר את הקטורת ומטיב את הנרות.\u0004 ומעירים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003קטורת\u0004 מקטירים \u0003ברישא\u0004 \u0005[בראש,\u0006 תחילה\u0005]\u0006 \u0003והדר\u0004 \u0005[ו\u0006רק \u0005אחר כך]\u0006 מטיבים את \u0003הנרות. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 על כך ממקור אחר: ששנינו במסכת תמיד בסדר הזוכים בפייס לעבודות הבוקר במקדש, שבראשונה עסק ב\u0003מי שזכה בדישון מזבח הפנימי\u0004 לנקותו מן האפר, ולאחריו ב\u0003מי שזכה במנורה\u0004 להיטיב את נרותיה, ורק לאחר מכן עסק ב\u0003מי שזכה\u0004 בהקטרת ה\u0003קטורת.\u0004 ולפי סדר זה משמע שהטבת נרות המנורה קודמת להקטרת הקטורת!","\u0003אמר רב הונא: מאן תנא\u0004 \u0005[מיהו ששנה]\u0006 את מסכת \u0003תמיד — ר' שמעון איש המצפה הוא\u0004 ודעתו שונה מדעת החכם ששנה את משנתנו. על דברי רב הונא שמסכת תמיד היא לשיטת ר' שמעון איש המצפה מקשים: \u0003והא איפכא שמעינן ליה\u0004 \u0005[והרי היפך הדברים שמענו אותו]\u0006 אומר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת תמיד: שהכהן הזורק את דם התמיד \u0003בא לו לקרן\u0004 (פינה) \u0003מזרחית צפונית\u0004 של המזבח ו\u0003נותן\u0004 הזאה אחת \u0003מזרחה צפונה,\u0004 ומשם הולך לקרן \u0003מערבית דרומית\u0004 ו\u0003נותן\u0004 ומזה בשנית \u0003מערבה דרומה.\u0004","\u0003ותני עלה\u0004 \u0005[ושנויה\u0006 תוספתא \u0005עליה]\u0006 על משנה זו, האומרת: כי \u0003ר' שמעון איש המצפה משנה בתמיד,\u0004 שלדעתו בקרבן התמיד אין מזים כמו בשאר קרבן עולה אלא מתחילה בא לקרן \u0003מזרחית צפונית\u0004 ו\u0003נותן\u0004 הזאה אחת \u0003מזרחה צפונה,\u0004 ואילו בקרן \u0003מערבית דרומית\u0004 איננו מזה על הקרן הזאה אחת. אלא \u0003נותן\u0004 הזאה אחת של דם \u0003מערבה, ואחר כך נותן\u0004 הזאה אחרת \u0003דרומה.\u0004 ומתוך שר' שמעון איש המצפה חלוק בענין זה דווקא, ברור הדבר כי מסכת תמיד עצמה אינה כשיטתו!","\u0003אלא\u0004 את הסתירה בין משנתנו ומסכת תמיד יש ליישב אחרת; \u0003אמר ר' יוחנן: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה \u0003סדר יומא\u0004 \u0005[יום הכיפורים],\u0006 כלומר: את מסכת יומא — \u0003ר' שמעון איש המצפה הוא.\u0004 וחכמים החולקים עליו מפורשת דעתם במסכת תמיד.","ומעירים עוד: \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 ומראים סתירה\u0005]\u0006 מ\u0003סדר יומא\u0004 \u0005[יום הכיפורים]\u0006 במקום אחד ממקום אחר ב\u0003סדר יומא\u0004 \u0005[יום הכיפורים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת יומא: \u0003פייס השני\u0004 מבין הארבעה שהיו עושים הכהנים בבית המקדש בכל יום, היה כך: \u0003מי שוחט\u0004 את קרבן התמיד, \u0003מי זורק\u0004 את דמו, \u0003מי מדשן\u0004 את ה\u0003מזבח הפנימי, ומי מדשן את המנורה, ומי מעלה\u0004 את ה\u0003אברים\u0004 של הקרבנות \u0003לכבש\u0004 (השיפוע שבו עולים למזבח). לאחר שסיימו את תהליך הפייס השני נפרדו ולאחר מכן התכנסו בחזרה והפיסו \u0003פייס השלישי\u0004 של הכהנים, שבו היו מכריזים: \u0003חדשים לקטורת\u0004 כלומר כהנים שמימיהם לא הקטירו קטורת \u0003בואו והפיסו\u0004 (השתתפו בפייס) מי מכם יזכה במצות הקטרת הקטורת. ומכאן ברור כי דישון והטבת המנורה קודמים להקטרת הקטורת, ובניגוד לסדר האמור במשנתנו!","\u0003אמר אביי: לא קשיא\u0004 וכך יש ליישב; \u0003כאן\u0004 במשנתנו מדובר \u0003בהטבת שתי נרות\u0004 שאותה עושים אחר הקטורת, ו\u0003כאן\u0004 בענין סדר הפייס מדובר \u0003בהטבת חמש נרות,\u0004 שאותה עושים קודם הקטרת הקטורת. שכאשר יבואר להלן, יש להפסיק בין הטבת חמש הנרות הראשונות להטבת השתים האחרונות.","ומקשים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003בקטורת מפסיק להו\u0004 \u0005[מפסיק ביניהן],\u0006 בין הטבת חמש נרות להטבת שתי נרות? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי\u0004 היה \u0003מסדר\u0004 מונה, את סדר עבודות קרבנות ה\u0003מערכה משמיה דגמרא\u0004 \u0005[בשם המסורת],\u0006 ובאותה רשימה \u0003בדם התמיד מפסיק להו\u0004 \u0005[מפסיק ביניהם]\u0006 בין הטבת חמש הנרות להטבת שתי הנרות זריקת דם התמיד ולא הקטרת הקטורת! \u0003אמרי\u0004 \u0005[אומרים]\u0006 ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003ההיא,\u0004 אותה דרך של סידור העבודה שאמר אביי בשם המסורת היא כשיטת \u0003אבא שאול,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 שבסדר שלנו הוא \u0003לרבנן\u0004 \u0005[\u0006לשיטת \u0005חכמים].\u0006 \u0003דתניא\u0004 \u0005[כפי\u0006 שאכן \u0005שנינו\u0006 בברייתא\u0005]\u0006 במפורש מחלוקת זו: \u0003לא ייטיב את הנרות\u0004 תחילה \u0003ואחר כך יקטיר\u0004 את הקטורת, \u0003אלא יקטיר ואחר כך ייטיב. אבא שאול אומר: מטיב\u0004 את הנרות בתחילה \u0003ואחר כך מקטיר\u0004 קטורת. ועל פי מחלוקת זו נתבררו השינויים בין המקורות השונים.","לגופו של אותו ענין שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003אבא שאול?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"בבקר בבקר בהיטיבו את הנרת\u0004 יקטירנה\u0003\"\u0004 (שמות ל, ח) משמע: קודם מטיבים את הנרות \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"יקטירנה\"\u0004 את הקטורת. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מפרשים הם פסוק זה? לדעתם \u0003מאי קאמר רחמנא\u0004 \u0005[מה אמרה התורה]\u0006"],["\u0003בעידן\u0004 \u0005[בזמן]\u0006 \u0003הטבה תהא מקטר\u0004 (מקטיר) \u0003קטורת,\u0004 ולא לאחר מכן. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 ולא תפרש ש\"יקטירנה\" שבסוף המשפט אין פירושו איחור זמן, אם כן ההקטרה \u0003בין הערבים, דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"ובהעלת אהרן את הנרת בין הערבים יקטירנה\"\u0004 (שמות ל, ח) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דברישא\u0004 \u0005[שבתחילה]\u0006 \u0003מדליק\u0004 הוא \u0003נרות והדר\u0004 \u0005[ו\u0006רק \u0005אחר כך]\u0006 \u0003מקטיר קטורת של בין הערבים?! וכי תימא הכי נמי\u0004 \u0005[וכי תאמר כך\u0006 הוא \u0005גם כן]\u0006 ואכן גם בבין הערבים יהיה כן הדין, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בתורה: \"באהל מועד מחוץ לפרוכת אשר על העדות יערוך אותו אהרן ובניו \u0003מערב עד בקר\u0004 לפני ה' חוקת עולם\" (שמות כז, כא)","ופירשו: \u0003תן לה\u0004 למנורה שמן \u0003מדתה,\u0004 כדי \u0003שתהא דולקת והולכת כל הלילה מערב ועד בקר. דבר אחר: \"מערב עד בקר\" —\u0004 ללמד ש\u0003אין לך עבודה שכשרה מערב עד בקר אלא זו בלבד.\u0004 משמע שהדלקת המנורה היא העבודה האחרונה בסדר עבודות היום במקדש, ולכן על הקטורת להיות קודם לה. \u0003אלא מאי קאמר רחמנא\u0004 \u0005[מה אמרה התורה]\u0006 לענין \"בין הערבים יקטירנה\" — ללמד כי \u0003בעידן\u0004 \u0005[בזמן]\u0006 ה\u0003הדלקה תהא מקטר\u0004 (מקטיר) את ה\u0003קטורת,\u0004 אם כן \u0003הכא נמי\u0004 \u0005[כאן\u0006 בבוקר \u0005גם כן]\u0006 \u0003בעידן\u0004 \u0005[בזמן]\u0006 \u0003הטבה תהא מקטר קטורת.\u0004 זה הסבר שיטת חכמים.","\u0003ואבא שאול אמר\u0004 \u0005[\u0006יכול היה \u0005לומר\u0006] \u0003לך\u0004 וליישב את הדברים לשיטתו כך: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 כיון \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004יערוך \u0003אותו\"\u0004 (שמות כז, כא) ו\"אותו\" משמעו למעט: דווקא אותו ולא אחר, ולכן ההדלקה שבערב נעשית בסוף העבודה, לאחר הקטרת הקטורת, אבל בבוקר, שאין מיעוט זה בכתוב, נוהגים כפי הסדר האמור בפסוק.","\u0003רב פפא אמר\u0004 תירוץ אחר לסתירה שבין המשניות: \u0003לא קשיא\u0004 \u0005[קשה];\u0006 שכן שתי המשניות ביומא אינן לשיטה אחת, \u0003הא\u0004 \u0005[זו]\u0006 המשנה שבה משמע כי הקטורת קודמת — כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שבה מקדימים את הנרות — כדעת \u0003אבא שאול\u0004 היא. על רב פפא מקשים: \u0003במאי אוקימתא למתניתין דהכא\u0004 \u0005[במה,\u0006 כיצד, \u0005העמדת את משנתנו כאן]\u0006 \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 ואילו את סדר ה\u0003פייס\u0004 בפרק השני הסברת שהוא כשיטת \u0003אבא שאול,\u0004","\u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של משנה במסכת שלנו (להלן יומא לא, ב): \u0003הביאו לו\u0004 לכהן הגדול ביום הכיפורים \u0003את התמיד, קרצו\u0004 (שחט את רובם של שני הסימנים) \u0003ומרק\u0004 (גמר) כהן \u0003אחר\u0004 את ה\u0003שחיטה על ידו\u0004 בשבילו, כדי שיוכל הכהן הגדול למהר ולקבל את הדם, ואחר כך \u0003נכנס להקטיר את הקטורת ולהיטיב את הנרות.\u0004 אם כן \u0003אתאן\u0004 \u0005[באנו,\u0006 הגענו\u0005]\u0006 שוב לשיטת חכמים שהקטורת קודמת לנרות, ואם כן לשיטה זו מגיעים למסקנה תמוהה כי \u0003רישא וסיפא\u0004 \u0005[תחילתה וסופה]\u0006 של מסכת יומא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 ואילו \u0003מציעתא\u0004 \u0005[אמצעה]\u0006 כשיטת \u0003אבא שאול!\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב פפא:\u0004 אכן, \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 ו\u0003מציעתא\u0004 \u0005[ואמצעה]\u0006 כשיטת \u0003אבא שאול.\u0004 שכיון שאין המשניות ממש צמודות זו לזו, אף שאין צירוף כזה מצוי, הרי הוא אפשרי.","ושואלים עוד: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ומובן, כי \u0003אביי לא אמר\u0004 כדברי \u0003רב פפא\u0004 שנימוקו בידו, כי המשך המשניות מסייע לדעתו, ואילו לשיטה זו \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ומציעתא\u0004 \u0005[ואמצעה]\u0006 כשיטת \u0003אבא שאול לא מוקים לה\u0004 \u0005[איננו מעמיד אותה]\u0006 לפי שהיא סברה תמוהה. \u0003אלא רב פפא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כאביי\u0004 ודחק עצמו להסבר זה? \u0003אמר לך\u0004 \u0005[\u0006היה יכול \u0005לומר]\u0006 שאף לדעת אביי הסבר זה דחוק הוא, כי לדעתו: \u0003תנא ברישא\u0004 \u0005[שנה בתחילה]\u0006 דין \u0003הטבת שתי נרות\u0004 שהוא מאוחר יותר, \u0003והדר\u0004 \u0005[וחזר\u0006 ושנה\u0005]\u0006 במשנה המביאה סדר \u0003הטבת חמש נרות\u0004 שהוא מוקדם להטבת שתים? ולכן מוטב להסביר שהדבר כרוך במחלוקת, מלהעמיד בדרך זו.","\u0003ואביי\u0004 שאינו חושש לקושי זה אומר כי מה ששנינו במשנתנו מה היה הכהן הגדול עושה כל שבעה, \u0003אורויי בעלמא\u0004 \u0005[הוראה\u0006 כללית \u0005בלבד]\u0006 \u0003הוא דקא מורי\u0004 \u0005[שהוא מורה]\u0006 על הדברים שעשה, בלא למנותם כסדרם, \u0003וסדרא הא הדר תני ליה\u0004 \u0005[ואת הסדר הרי חזר ושנה אותו]\u0006 כראוי, ולא הקפיד על כך בתחילה.","אגב הדיון הוזכרה מחלוקת חכמים ור' שמעון איש המצפה בסדר הקרבת קרבן התמיד עתה באים לדון בהלכה זו ל\u0003גופא\u0004 ולפרטיה. וכך שנינו: \u0003בא לו\u0004 הכהן \u0003לקרן מזרחית צפונית\u0004 של המזבח — \u0003נותן\u0004 מן הדם בקרן \u0003מזרחית צפונית,\u0004 בא לו לקרן \u0003מערבית דרומית\u0004 — \u0003נותן\u0004 מן הדם בקרן \u0003מערבית דרומית. ותני עלה\u0004 \u0005[ושנויה עליה]\u0006 בברייתא: \u0003ר' שמעון איש המצפה משנה\u0004 את ההלכה \u0003בתמיד,\u0004 שלדעתו \u0003בא לו לקרן מזרחית צפונית — נותן\u0004 הזאה בקרן \u0003מזרחית צפונית,\u0004 בא לקרן \u0003מערבית דרומית — נותן\u0004 הזאה אחת \u0003מערבה ואחר כך נותן\u0004 הזאה \u0003דרומה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון איש המצפה\u0004 לשנות בתמיד משאר קרבנות העולה?","\u0003אמר ר' יוחנן משום חד דבי\u0004 \u0005[משמו של\u0006 חכם \u0005אחד מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושעיר עזים אחד לחטאת לה' על עלת התמיד יעשה ונסכו\"\u0004 (במדבר כח, טו) ומלשון הכתוב \"על עולת התמיד\" למד, כי קרבן התמיד \u0003עולה היא,\u0004 ומפני שסמך הכתוב סדר עשיית החטאת לקרבן התמיד, בכך \u0003אמר רחמנא\u0004 \u0005[הכתוב]:\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003בה\u0004 גם \u0003מעשה חטאת.\u0004","\u0003הא כיצד\u0004 אפשר לעשות שתהא עולת התמיד דומה למעשה חטאת? הריהו מחלק את המתנות באופן שחציין כעולה וחציין כחטאת בדרך זו: \u0003נותן\u0004 קודם מן הדם מתנה \u0003אחת שהיא שתים\u0004 שמזה מן הדם על קרן המזבח במקצוע שהדם מתחלק לשני הצדדים \u0003כמעשה\u0004 קרבן \u0003עולה\u0004 רגיל, ואחר כך \u0003נותן שתים שהן שתים כמעשה חטאת\u0004 שאת דם החטאת היו מזים ארבע מתנות נפרדות בארבעה קרנות. ומקשים: אם שיהא התמיד דומה לקרבן החטאת \u0003וליתן\u0004 \u0005[ושיתן]\u0006 שתי מתנות מלאות, ראשית \u0003שתים שהן ארבע כמעשה עולה\u0004 ואחר כך יתן \u0003ארבע שהן ארבע כמעשה חטאת!\u0004","ודוחים: \u0003לא מצינו דמים שמכפרין וחוזרין ומכפרין,\u0004 וכיון שכבר הזה את הדם וכבר סיים את מעשה הכפרה בהזאת עולה, שוב אינו יכול להתחיל בסדר אחר של כפרת חטאת. ומקשים: זה אינו נימוק, כי אם כן \u0003וכי מצינו דמים שהן חציין חטאת וחציין עולה? אלא על כרחן\u0004 יש לומר כי \u0003הקישן\u0004 (השווה אותם) \u0003הכתוב\u0004 ואמר שבמעשה התמיד יש לשנות מן הרגיל. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נוכל לומר: \u0003בעל כרחן הקישן הכתוב\u0004 לתת שתי מתנות מלאות, קודם מתנות עולה, ואחר כך של חטאת.","ומשיבים: אין הדברים דומים, כי \u0003התם\u0004 \u0005[שם]\u0006 בדברי ר' שמעון איש המצפה \u0003פסוק\u0004 (חילוק) \u0003מתנות בעלמא היא\u0004 \u0005[בלבד הוא],\u0006 שבעצם אין הבדל יסודי אם נותן אותה נתינה של דם בזריקה אחת והיא מתחלקת לשני הצדדים, או מחלק אותה מתחילה לשנים. ושואלים מצד אחר: הלא אפשר לעשות שתהא עולת התמיד דומה לחטאת באופן אחר: \u0003וניתיב\u0004 \u0005[וניתן]\u0006 \u0003אחת שהיא שתים למטה\u0004 מחוט הסיקרא, \u0003כמעשה עולה,\u0004 ויתן עוד \u0003שתים שהן שתים למעלה\u0004 מחוט הסיקרא, \u0003כמעשה חטאת!\u0004","ודוחים: \u0003לא מצינו דמים שחציין למעלה וחציין למטה,\u0004 ואין נתינת דם אלא או כולו בחציו התחתון של המזבח (כברוב הקרבנות) או כולו בחציו העליון (כמו בחטאת). ומקשים: \u0003ולא?\u0004 וכי לא מצאנו כעין זה?! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הזה ממנו\u0004 מדם הפר שמכניסים לבית קודש הקדשים הזאה \u0003אחת\u0004 מאמצע עובי הכפורת כלפי \u0003מעלה ושבע\u0004 הזאות נוספות מאמצע עובי הכפורת כלפי \u0003מטה.\u0004 הרי מצינו נתינה שחלקה למעלה וחלקה למטה!","ודוחים: אין זה דומה, כי שם לא היתה זו חלוקת הדם להזאה בחצי העליון וחצי התחתון של עובי הכפורת, אלא הכוונה שתהיה ההזאה \u0003כמצליף\u0004 שיהיו מתנות הדם לא זו על גבי זו, אלא זו מתחת לזו, וכולן היו אכן ניתנות רק בחלק אחד של הכפורת. ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש המילה\u0005]\u0006 \u0003\"כמצליף\" — מחוי\u0004 \u0005[\u0006היה \u0005מראה]\u0006 \u0003רב יהודה\u0004 בידו, \u0003כמנגדנא\u0004 \u0005[כמלקה\u0006 ברצועה\u0005]\u0006 שאינו מכה במקום אחד אלא אחת מתחת לחברתה.","ומקשים עוד: \u0003ולא?\u0004 וכי לא מצינו דם הניתן חציו למטה וחציו למעלה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 לענין מתנות הדם על גבי מזבח הקטורת: \u0003הזה ממנו על טהרו של מזבח שבע פעמים. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003אפלגיה\u0004 \u0005[על אמצע\u0006 גובה קירו\u0005]\u0006 של ה\u0003מזבח כדאמרי אנשי\u0004 \u0005[כדרך שאומרים אנשים]:\u0006 \u0003טהר טיהרא\u0004 \u0005[צהרו הצהריים]\u0006 ופירושו הוא \u0003פלגא דיומא\u0004 \u0005[חצי היום],\u0006 ולכן לשון \"טהרו של מזבח\" כוונתו להביע מחציתו של המזבח. ומכיון שחובה להזות על המזבח שבע פעמים, קיים קושי לדייק במקום ההזאה ונמצא שבמציאות היתה נתינה למעלה ולמטה!","ודוחים: \u0003אמר רבה בר שילא: לא\u0004 כך יש לפרש לשון \"טהרו של מזבח\","],["אלא \"טהרו\" פירושו — \u0003אגופיה\u0004 \u0005[על גופו של]\u0006 ה\u0003מזבח\u0004 ולא במקום שיש עליו אפר הקטורת, ועיקר משמעות זו נלמדת ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכעצם השמים לטהר\"\u0004 (שמות כד, י), הרי ש\"טוהר\" לשון נקיון הוא.","וחוזרים לבירור שיטת ר' שמעון איש המצפה: \u0003מאי שנא דיהיב\u0004 \u0005[במה שונה,\u0006 מה הטעם, \u0005שנותן]\u0006 את המתנות כדרך ה\u0003עולה ברישא\u0004 \u0005[בתחילה]\u0006 \u0003והדר יהיב\u0004 \u0005[ואחר כך נותן]\u0006 את המתנות כדרך ה\u0003חטאת? ניתיב ברישא\u0004 \u0005[שיתן בתחילה]\u0006 כעין \u0003חטאת, והדר ניתיב\u0004 \u0005[ואחר כך יתן]\u0006 את של ה\u0003עולה!\u0004 ומשיבים: \u0003כיון\u0004 שקרבן התמיד \u0003עולה היא,\u0004 לכן \u0003היא קדמה ברישא\u0004 \u0005[בראש]\u0006 ולאחר שיעשה כמעשה הראוי לעולה יחזור ויעשה כמעשה הראוי לחטאת.","ושואלים: \u0003ומאי שנא דיהיב\u0004 \u0005[ובמה שונה,\u0006 מה טעם, \u0005שנותן]\u0006 מן הדם בקרן \u0003מזרחית צפונית, ו\u0004בקרן \u0003מערבית דרומית,\u0004 ומדוע לא \u0003ניתיב\u0004 \u0005[יתן]\u0006 תחילה בקרן \u0003דרומית מזרחית, והדר\u0004 \u0005[ואחר כך]\u0006 בקרן \u0003צפונית מערבית! אמרי\u0004 \u0005[אומרים]\u0006 ומסבירים: משום שנתינת דם ה\u0003עולה טעונה\u0004 (צריכה שתהיה) בצד המזבח שיש לו \u0003יסוד,\u0004 שכן נאמר: \"על יסוד מזבח העולה\", \u0003וקרן דרומית מזרחית\u0004 הרי \u0003לא הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003יסוד,\u0004 לכן יש ליתן דווקא בקרן מזרחית צפונית שיש לה יסוד.","ומוסיפים לשאול: \u0003מאי שנא דיהיב ברישא\u0004 \u0005[מה שונה,\u0006 מה הטעם \u0005שהוא נותן תחילה]\u0006 בקרן \u0003מזרחית צפונית והדר\u0004 \u0005[ואחר כך]\u0006 בקרן \u0003מערבית דרומית? ניתיב ברישא\u0004 \u0005[שיתן בתחילה]\u0006 בקרן \u0003מערבית דרומית והדר\u0004 \u0005[ואחר כך]\u0006 יתן בקרן \u0003מזרחית צפונית!\u0004 ומשיבים: כיון ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל פינות\u0004 (פניות) \u0003שאתה פונה\u0004 כשהברירה בידך לפנות לימין או לשמאל — \u0003לא יהו אלא דרך ימין,\u0004 ובקרבנות מסויימים (כשעומד בקרן דרומית) פנה ל\u0003מזרח\u0004. וכיון שהשוחט את העולה עומד בצפון המזבח הרי ש\u0003ברישא\u0004 \u0005[בתחילה]\u0006 כשניגש להזות ופונה לימין \u0003בההוא פגע\u0004 \u0005[באותה\u0006 קרן, זו המערבית דרומית, \u0005הוא פוגש]\u0006 ועליה הוא מזה תחילה.","ועוד שואלים על ר' שמעון איש המצפה: \u0003וממאי\u0004 \u0005[וממה,\u0006 מדוע\u0005]\u0006 לומד אתה ש\u0003בעולה הוא דקאמר רחמנא\u0004 \u0005[שאמרה\u0006 בה \u0005התורה]\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003בה\u0004 כ\u0003מעשה חטאת, ודילמא\u0004 \u0005[ושמא]\u0006 יש להבין את הכתוב כך: \u0003בחטאת\u0004 ראש חודש \u0003הוא דקאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003בה\u0004 כ\u0003מעשה עולה!\u0004 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"על עלת התמיד יעשה ונסכו\"\u0004 (במדבר כח, טו), \u0003מאי קאמר רחמנא\u0004 \u0005[מה אמרה התורה],\u0006 מה המשמעות ההלכתית בפסוק זה, לומר לנו: \u0003מידי\u0004 \u0005[דבר,\u0006 הלכה\u0005]\u0006 שיש ב\u0003חטאת שדי\u0004 \u0005[זרוק,\u0006 הטל\u0005]\u0006 על ה\u0003עולה.\u0004","בסוגיה הקודמת נתבררו הדברים לפי יחוסם של מקורות שונים לתנאים שונים. ומשום כך מביאים כאן סוגיה שיש לה מבנה דומה. \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת תמיד, \u0003אמר להם הממונה\u0004 (הסגן) לכהנים: \u0003צאו והביאו טלה מלשכת בית הטלאים\u0004 (המקום בו היו הטלאים מבוקרים ממומים ומוכנים להקרבה), ומסביר להם: \u0003והלא\u0004 (והרי, והנה) \u0003לשכת הטלאים\u0004 זו \u0003היתה במקצוע\u0004 (פינה) \u0003צפונית מערבית\u0004 של אולם בית המוקד שהיה בעזרה. \u0003וארבע לשכות\u0004 (חדרים) \u0003היו שם\u0004 באותו אולם, \u0003אחת — לשכת הטלאים, ואחת — לשכת החותמות\u0004 ששם היו מניחים את החותמות שהיו משמשות כקבלה המאשרת כי האדם הנושא חותמת כזו ומוסרה לממונה, זכאי לקבל קרבן מסויים מן המקדש, \u0003ואחת — לשכת בית המוקד, ואחת — לשכה שעושין בה לחם הפנים.\u0004","\u0003ורמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממסכת מדות שבה נאמר: \u0003ארבע לשכות היו\u0004 פתוחות \u0003לבית המוקד, כקטוניות\u0004 (חדרים קטנים פתוחים למחצה) \u0003הפתוחות לטרקלין; שתים\u0004 מן הלשכות הללו היו \u0003בקודש\u0004 שנחשבו כחלק מתחום הקודש של העזרה, \u0003ושתים בחול\u0004 בתחום הר הבית, \u0003וראשי פספסין\u0004 (מחיצות עץ קטנות) \u0003מבדילין\u0004 בתוך בית המוקד \u0003בין\u0004 מקום \u0003הקודש\u0004 ובין מקום ה\u0003חול,\u0004 כדי שידעו כיצד לנהוג בכל מקום. \u0003ו\u0004ל\u0003מה היו משמשות\u0004 לשכות אלה? לשכה \u0003מערבית דרומית היא היתה לשכת טלי\u0004 (טלאים של) \u0003קרבן.\u0004"],["\u0003דרומית מזרחית\u0004 בבית המוקד \u0003היא לשכה שהיו עושין בה\u0004 את \u0003לחם הפנים.\u0004 לשכה \u0003מזרחית צפונית — בה גנזו בית חשמונאי\u0004 את \u0003אבני\u0004 ה\u0003מזבח ששקצום\u0004 (טמאום) \u0003מלכי יון\u0004 כשהקריבו על גביהן לעבודה זרה. לשכה \u0003צפונית מערבית — בה\u0004 היו הכהנים \u0003יורדין\u0004 דרך מחילות שהיו קיימות מתחת לעזרות \u0003לבית הטבילה.\u0004 ואם כן קיימת סתירה בדבר מקומה של לשכת הטלאים! \u0003אמר רב הונא: מאן תנא\u0004 \u0005[מיהו]\u0006 זה ששנה את מסכת \u0003מדות — ר' אליעזר בן יעקב\u0004 הוא, ולו שיטה אחרת בדבר.","וההוכחה לכך שמסכת מדות שנאה ר' אליעזר בן יעקב, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת מדות: \u0003עזרת נשים היתה אורך מאה ושלשים וחמש\u0004 אמות \u0003על רוחב מאה ושלשים וחמש\u0004 אמות \u0003וארבע לשכות היו בארבע מקצועותיה\u0004 (פינותיה), \u0003ו\u0004ל\u0003מה היו משמשות\u0004 לשכות אלה? לשכה \u0003דרומית מזרחית — היא היתה לשכת הנזירים, ששם\u0004 היו ה\u0003נזירים מבשלים את\u0004 קרבנות \u0003שלמיהן ומגלחין שערן ומשלחין\u0004 שערות אלו מ\u0003תחת הדוד\u0004 כדי לשורפן, כאמור במקרא (במדבר ו, יח). לשכה \u0003מזרחית צפונית — היא היתה לשכת דיר העצים, ששם\u0004 היו ה\u0003כהנים בעלי\u0004 ה\u0003מומין\u0004 הפסולים לעבודה אחרת \u0003עומדין ומתליעין\u0004 (בודקים אם יש תולעים) \u0003בעצים\u0004 שנועדו למזבח, \u0003שכל עץ שיש בו תולעת — פסול לגבי מזבח.\u0004","לשכה \u0003צפונית מערבית — היא היתה לשכת המצורעין\u0004 ששם היו טובלים לטהרתם. לשכה \u0003מערבית דרומית, אמר ר' אליעזר בן יעקב: שכחתי\u0004 ל\u0003מה היתה משמשת. אבא שאול אומר: בה היו נותנין יין ושמן\u0004 לצורך המנחות והנסכים, \u0003והיא היתה נקראת \"לשכת בית שמניא\".\u0004 ומלשונה של משנה זו נראה בבירור כי התנא ששנה את המסכת הוא ר' אליעזר בן יעקב, שלכן מזכירים שאמר ששכח מה היתה אותה לשכה משמשת.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שמסכת מדות שיטת \u0003ר' אליעזר בן יעקב היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת מדות: \u0003כל הכתלים שהיו שם\u0004 מסביב להר הבית \u0003היו גבוהין, חוץ מכותל מזרחי\u0004 של ההר, משום \u0003שהכהן השורף את הפרה\u0004 האדומה \u0003עומד בהר המשחה\u0004 (בהר הזיתים) ששם היה מקום שחיטת ושריפת הפרה \u0003ומכוון\u0004 מעל גובה הכותל ורואה \u0003כנגד פתחו של היכל בשעת הזאת הדם.\u0004","ומעתה נברר לפי איזו שיטה היה הדבר אפשרי; \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הפתחים שהיו שם\u0004 בבית המקדש היה \u0003גובהן עשרים אמה ורוחבן עשר אמות. ותנן\u0004 \u0005[וכן שנינו\u0006 במשנה אחרת\u0005]\u0006 לענין מבנה המקדש: \u0003לפנים ממנו\u0004 מכותל המזרח של הר הבית היה \u0003סורג\u0004 (מחיצה העשויה כעין סבכה). \u0003ותנן\u0004 \u0005[וכן שנינו עוד\u0006 במשנה\u0005]:\u0006 ש\u0003לפנים ממנו\u0004 מן הסורג נמצא \u0003החיל\u0004 שהוא שטח מוגבה שהיה רוחבו \u0003עשר אמות, ושתים עשרה מעלות\u0004 (מדרגות) \u0003היו שם\u0004 באותו שטח, כש\u0003רום\u0004 (גובה) כל \u0003מעלה חצי אמה ושילחה\u0004 (רחבה) \u0003חצי אמה,\u0004 הרי לנו, אם כן, עליה של שש אמות.","ועוד נאמר כי היו \u0003חמש עשרה מעלות עולות מתוכה\u0004 מעזרת נשים, אותן המעלות \u0003היורדות מעזרת ישראל לעזרת נשים,\u0004 כש\u0003רום\u0004 (גובה) כל \u0003מעלה חצי אמה ושילחה\u0004 (ורוחבה) \u0003חצי אמה,\u0004 הרי נוספו לגובה שבע וחצי אמות נוספות, וביחד הן שלוש עשרה וחצי אמות. \u0003ותנן\u0004 \u0005[ושנינו עוד\u0006 במשנה\u0005]:\u0006 כי \u0003בין האולם ולמזבח\u0004 היה שטח שרוחבו \u0003עשרים ושתים אמות, ושתים עשרה מעלות היו שם\u0004 בשטח זה, \u0003רום\u0004 (גובה) כל \u0003מעלה חצי אמה ושילחה\u0004 (ורוחבה) \u0003חצי אמה,\u0004 הרי נוספו לגובה שש אמות נוספות כשבחשבון כולל הריהן כבר תשע עשרה וחצי אמות.","\u0003ותנן\u0004 \u0005[ושנינו עוד\u0006 במשנה\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר: מעלה\u0004 (מדריגה) נוספת \u0003היתה שם\u0004 שמבדילה בין עזרת ישראל לעזרת כהנים \u0003וגבוה אמה, ודוכן\u0004 שעליו היו הלויים עומדים \u0003נתון עליה, ובו\u0004 היו \u0003שלש מעלות של חצי חצי אמה\u0004 ברוחב ובגובה, הרי בסך הכל עשרים ושתים אמות.","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמשנתנו כשיטת \u0003ר' אליעזר בן יעקב — היינו דאיכסי ליה פיתחא\u0004 \u0005[זהו\u0006 ההסבר מפני מה \u0005נתכסה הפתח]\u0006 כי פתח ההיכל היה גבוה מתחתית הר הבית המזרחי יותר מעשרים אמה, ולכן אין לראות את פתח ההיכל דרך פתח הר הבית, ומתוך כך צריך היה להנמיך את הכותל המזרחי, כדי שיוכל לראות את פתח ההיכל מלמעלה.","\u0003אלא אי אמרת רבנן\u0004 \u0005[אם אומר אתה\u0006 כשיטת \u0005חכמים]\u0006 שאין הוסיף גובה של שתים וחצי אמות של אותה מעלה והדוכן שעליה, שהוזכרו בדברי ר' אליעזר בן יעקב, ולדבריהם אין הגובה המירבי אלא תשע עשרה וחצי אמות בלבד, אם כן \u0003האיכא\u0004 \u0005[הרי יש]\u0006 עדיין את אותה \u0003פלגא דאמתא\u0004 \u0005[חצי אמה]\u0006 \u0003דמתחזי ליה פתחא בגוויה\u0004 \u0005[שנראה לו הפתח בתוכו]\u0006 שיכול הכהן לראות דרך הפתח המזרחי של הר הבית את קצהו התחתון של פתח ההיכל, שהרי הבדל הגובה ביניהם אינו אלא תשע עשרה וחצי אמות!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 והוכח כי מסכת מדות כשיטת \u0003ר' אליעזר בן יעקב היא,\u0004 והלכות האמורות בה, הן לפי שיטתו. \u0003רב אדא בר אהבה אמר:\u0004 כי אין זו ראיה מוכרחת, ועדיין ניתן להסביר הלכות אלו בדרך אחרת. \u0003אלא הא\u0004 \u0005[\u0006משנה \u0005זו]\u0006 האומרת שכותל מזרחי של הר הבית היה נמוך \u0003מני\u0004 \u0005[של מי היא]\u0006 — כשיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר: המזבח ממוצע ועומד באמצע\u0004 ה\u0003עזרה\u0004 בדיוק מול פתחי העזרות וההיכל, \u0003ושלשים ושתים אמות היו לו\u0004 באורכו וברוחבו,"],["\u0003עשר אמות\u0004 מהן מכוונות בדיוק \u0003כנגד פתחו של\u0004 ה\u0003היכל,\u0004 ו\u0003אחת עשרה אמה לצפון ואחת עשרה אמה לדרום, נמצא\u0004 שהיה ה\u0003מזבח מכוון\u0004 בדיוק \u0003כנגד\u0004 ה\u0003היכל וכותליו.\u0004 ולפי שיטה זו, מאחר והיה המזבח מכוון בדיוק כנגד פתח ההיכל, נמצא שגובהו היה סותם את הפתח, שהרי גובה עזרת ישראל היה שלוש עשרה אמה ומחצה, כאמור והוסף לכך עוד תשע אמות של גובה המזבח עצמו, הרי לך בחשבון כולל עשרים ושתים אמות ולכך לא היה כל אפשרות לראות את פתח ההיכל דרך פתח הכותל המזרחי של הר הבית. ולכן היה צורך להנמיך את הכותל המזרחי, כדי שאפשר יהיה לראות מהר הזיתים את פתח ההיכל מעל למזבח.","לשיטה זו של ר' אדא שלדעתו שיטת מסכת מדות כר' יהודה מקשים: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שמסכת \u0003מדות\u0004 כשיטת \u0003ר' יהודה היא,\u0004 אם כן, שיהא ה\u0003מזבח באמצע\u0004 ה\u0003עזרה מי משכחת ליה\u0004 \u0005[האם מוצא אתה]\u0006 כן לשיטת מסכת מדות? \u0003והתנן\u0004 \u0005[והרי\u0006 \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל העזרה כולה היתה אורך מאה ושמונים ושבע\u0004 אמות \u0003על רוחב מאה ושלשים וחמש\u0004 אמות. ומפרטים: \u0003מן המזרח למערב\u0004 שהוא אורך המקדש — \u0003מאה ושמונים ושבע\u0004 אמות, כך הן מתחלקות: \u0003מקום דריסת רגלי ישראל\u0004 שהוא המקום הקרוי \"עזרת ישראל\" — אורכו \u0003אחת עשרה אמה, מקום דריסת רגלי הכהנים —\u0004 אורכו \u0003אחת עשרה אמה,\u0004 ה\u0003מזבח\u0004 עצמו — אורכו \u0003שלשים ושתים\u0004 אמה, \u0003בין האולם ולמזבח — עשרים ושתים, וההיכל — מאה אמה, ואחת עשרה אמה\u0004 נוספות של שטח פנוי \u0003מאחורי בית הכפורת\u0004 (בית קודש הקדשים).","ולרוחב המקדש \u0003מן הדרום לצפון\u0004 היו \u0003מאה ושלשים וחמש\u0004 אמות, וכך היו מחולקות: מדת \u0003הכבש והמזבח\u0004 כאחת — \u0003ששים ושתים\u0004 אמות, כשאורך כל אחד מהם שלושים ושתים אמות ושתי אמות היו נבלעות במה שחלקו העליון של המזבח נכנס פנימה ביסוד וסובב. \u0003מן המזבח ולטבעות\u0004 שהיו בצפונו של המזבח ובהן היו מכניסים את צוואר בהמות הקרבן לצורך שחיטה — \u0003שמונה אמות\u0004 רווח, \u0003מקום הטבעות\u0004 עצמן היה \u0003עשרים וארבע\u0004 אמות, \u0003מן הטבעות\u0004 ועד \u0003לשלחנות\u0004 שעליהן היו מדיחים את קרבי הקדשים היו עוד \u0003ארבע\u0004 אמות, \u0003מן השלחנות לננסין\u0004 (עמודים נמוכים שהיו שם ומיועדים לתליית הקרבנות כדי להקל על הפשטת העור, היו עוד \u0003ארבע\u0004 אמות, \u0003מן הננסין\u0004 עד \u0003לכותל\u0004 ה\u0003עזרה\u0004 היו עוד \u0003שמונה אמות.\u0004 הרי לך בינתיים לחשבון זה מאה ועשר אמות \u0003והמותר\u0004 ממדות אלה, שהוא כעשרים וחמש אמות, הוא מה שנמצא \u0003בין הכבש ולכותל\u0004 של צד דרום, וכן \u0003מקום הננסין\u0004 (המקום שתפסו אותם העמודים) שאותו לא חשבנו, הרי לך בחשבון כולל מאה שלושים וחמש אמות.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי מסכת \u0003מדות\u0004 כשיטת \u0003ר' יהודה היא\u0004 אם כן \u0003מזבח באמצע\u0004 ה\u0003עזרה מי משכחת ליה\u0004 \u0005[האם מוצא אתה אותו]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רובא\u0004 \u0005[רובו]\u0006 של ה\u0003מזבח בדרום\u0004 העזרה \u0003קאי\u0004 \u0005[הוא עומד]!\u0006"],["\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כפי שהסברנו בראשונה, כי מסכת מדות כשיטת \u0003ר' אליעזר בן יעקב היא,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003רב אדא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יצחק אמר\u0004 תירוץ אחר לסתירה בדבר מקומה של לשכת הטלאים: \u0003האי לשכה אקצויי מקציא\u0004 \u0005[לשכה זו מובדלת היתה]\u0006 מן הפינה, שלא עמדה ממש בקרן בית המוקד אלא באמצעה לצד מערב, ומשום כך \u0003דאתי\u0004 \u0005[מי שבא]\u0006 מצד \u0003צפון מתחזיא ליה\u0004 \u0005[נראית לו]\u0006 לשכה זו סמוכה לצד \u0003דרום\u0004 ואילו \u0003דאתי\u0004 \u0005[מי שבא]\u0006 מצד \u0003דרום מתחזיא ליה\u0004 \u0005[נראית לו]\u0006 בצד \u0003צפון.\u0004","ומעירים: על כל פנים \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי לשכה זו סמוכה יותר לצד \u0003מערבית דרומית הואי\u0004 \u0005[היתה].\u0006 \u0003ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 לומדים אנו את זו — \u0003מדרמינן\u0004 \u0005[ממה שאנו משליכים,\u0006 מראים סתירה\u0005]\u0006 ממשנה אחת במסכת תמיד בה נאמר כי לשכת \u0003לחם הפנים\u0004 היתה בקרן מזרחית צפונית על משנה אחרת במסכת מדות, בה נאמר כי לשכת \u0003לחם הפנים\u0004 היתה דרומית מזרחית,","\u0003ומשנינן\u0004 \u0005[ומתרצים אנו]\u0006 ממה ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 כדי לישב את הסתירה: \u0003מר\u0004 \u0005[חכם זה]\u0006 של מסכת מדות \u0003קא חשיב\u0004 \u0005[חושב]\u0006 \u0003דרך ימין,\u0004 והריהו פונה איפוא מדרום למזרח ומשם לצפון ומשם למערב, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 של מסכת תמיד \u0003קא חשיב\u0004 \u0005[חשב]\u0006 ומנה את הלשכות לכיון ההפוך \u0003דרך שמאל,\u0004 מדרום למערב ומשם לצפון ולמזרח. ולכן, ודאי לדברי הכל לשכת לחם הפנים אכן מצויה באותו מקום ואין כאן איפוא חילוקי דעות."],["\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי באמת לשכת הטלאים בקרן \u0003מערבית דרומית הואי\u0004 \u0005[היתה],\u0006 אם כן \u0003היינו דמתרץ\u0004 \u0005[זה\u0006 הטעם המסביר כיצד \u0005מתרץ]\u0006 את הסתירה של מ\u0003לחם הפנים\u0004 על \u0003לחם הפנים. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שלשכה זו בקרן \u0003צפונית מערבית הואי\u0004 \u0005[היתה],\u0006 \u0003סוף סוף, מאי תירוצא\u0004 \u0005[מהו התירוץ]\u0006 איפוא של \u0003לחם הפנים,\u0004 שהרי גם אם אתה חושב מכיוון אחר, עדיין נמצאת לשכת החותמות חוצצת בין לשכת הטלאים ולשכת הלחם! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי אכן \u0003במערבית דרומית הואי\u0004 \u0005[היתה]\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","על תירוץ זה שתנא אחד מונה דרך שמאל מקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003כל פינות שאתה פונה לא יהיו אלא דרך ימין, למזרח\u0004 וכאן מנה דרך שמאל? ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 בשעת מעשה ה\u0003עבודה,\u0004 שכך יש לפנות. \u0003אבל הכא\u0004 \u0005[כאן] —\u0006 \u0003חושבנא בעלמא הוא\u0004 \u0005[חשבון בלבד הוא],\u0006 שלא הלך בפועל לצד זה, אלא רק חשב דברים בכוון זה.","שנינו במשנה: \u0003שכהן גדול מקריב חלק בראש ונוטל חלק בראש. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כיצד מקריב חלק בראש? אומר\u0004 הכהן הגדול: \u0003עולה זו אני מקריב, מנחה זו אני מקריב,\u0004 ודי בכך ואינו נזקק לפייס או לחלוקה אחרת.","\u0003כיצד נוטל חלק בראש? אומר\u0004 הכהן הגדול: \u0003חטאת זו אני אוכל, אשם זה אני אוכל. ונוטל\u0004 אפילו \u0003חלה\u0004 אחת \u0003משתי חלות\u0004 שמביאים בחג השבועות וכן \u0003ארבע או חמש\u0004 חלות משתים עשרה החלות של \u0003מעשה לחם הפנים\u0004 שמחלקים בין הכהנים בכל שבת. \u0003רבי אומר: לעולם\u0004 נוטל הכהן הגדול \u0003חמש\u0004 חלות מתוך שתים עשרה החלות של לחם הפנים, לפי \u0003שנאמר\u0004 בלחם הפנים: \u0003\"והיתה לאהרן ולבניו\u0004 ואכלוהו במקום קדוש\" (ויקרא כד, ט), ונלמד ממה שהזכיר את אהרן לחוד מבניו: ש\u0003מחצה\u0004 מהחלות ניתן \u0003לאהרן\u0004 או לכהן הגדול הבא במקומו \u0003ומחצה לבניו.\u0004 ומתוך שכפי שיבואר להלן לא היו מתחלקות אלא עשר חלות בלבד, הרי שחלקו של הכהן הגדול חמש חלות.","על ברייתא זו מקשים: \u0003הא גופא קשיא\u0004 \u0005[הרי היא עצמה קשה]\u0006 ויש בה סתירה: \u0003אמרת נוטל חלה אחת משתי חלות, מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 דעה זו — כשיטת \u0003רבי היא,\u0004 ש\u0003אמר:\u0004 כי הכהן הגדול \u0003פלגא שקיל\u0004 \u0005[מחצה הוא נוטל].\u0006 \u0003אימא מציעתא\u0004 \u0005[אמור את האמצע]\u0006 של אותה הברייתא: \u0003ארבע או חמש ממעשה לחם הפנים,\u0004 הרי \u0003אתאן לרבנן\u0004 \u0005[הגענו\u0006 לשיטת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שהם אומרים]:\u0006 \u0003לא שקיל פלגא\u0004 \u0005[איננו לוקח חצי]\u0006 אלא פחות. \u0003אימא — סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה \u0003רבי אומר: לעולם חמש.\u0004 ואם כן מגיעים להסבר תמוה כאשר \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 של המשנה הוא כשיטת \u0003רבי, ומציעתא רבנן\u0004 \u0005[ואמצעה\u0006 הוא כשיטת \u0005חכמים],\u0006 וכיצד יתכן לומר דבר זה?","\u0003אמר אביי:\u0004 כך צריך לפרש: \u0003רישא ומציעתא רבנן\u0004 \u0005[ראשה ואמצעה\u0006 כשיטת \u0005חכמים]\u0006 ולענין הקושיה בענין שתי הלחם — \u0003מודו רבנן\u0004 \u0005[מודים חכמים]\u0006 \u0003בפרוסה\u0004 ש\u0003לאו אורח ארעא למיתבה\u0004 \u0005[שאין זה דרך ארץ לתת אותה]\u0006 \u0003לכהן גדול\u0004 שלשיטת חכמים מגיע לכהן גדול פחות מחלה אחת, אלא כיון שאין זה דרך ארץ לתת לו חלה פרוסה, נותנים לו חלה שלימה,"],["\u0003ומאי ארבע או חמש,\u0004 כלומר מתי ארבע ומתי חמש? \u0003לרבנן\u0004 \u0005[\u0006לשיטת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[האומרים]\u0006 משמר ה\u0003נכנס\u0004 באותה שבת \u0003נוטל שש\u0004 מן החלות, והמשמר ה\u0003יוצא נוטל שש, ושכר הגפת דלתות לא\u0004 נוטל משמר הנכנס, על כן \u0003משתים עשרה בעי מיפלג\u0004 \u0005[משתים עשרה צריך הוא לחלוק]\u0006 \u0003בציר חדא מפלגא\u0004 \u0005[אחת פחות מחצי],\u0006 שהרי אינו נוטל לשיטה זו אלא פחות מחצי ונטילת פרוסה הרי גנאי הוא לו, לכן יש לפחות חלה אחת שלימה, הרי לחשבון זה \u0003חמש שקיל\u0004 \u0005[חמש\u0006 חלות \u0005הוא נוטל].\u0006","ו\u0003לר' יהודה\u0004 ש\u0003אמר:\u0004 משמר \u0003הנכנס נוטל שבע\u0004 מן החלות, כשמתוכן \u0003שתים\u0004 הן \u0003בשכר הגפת דלתות,\u0004 ומשמר ה\u0003יוצא נוטל חמש\u0004 חלות, אם כן יוצא ששתים מן החלות הם מתנה מיוחדת ואינן במנין, ואם כן \u0003מעשר בעי מיפלג\u0004 \u0005[צריך הוא לחלוק]\u0006 ו\u0003בציר חדא מפלגא\u0004 \u0005[ותוריד אחת\u0006 שלימה \u0005מן החצי]\u0006 לפי שאינו נוטל פרוסה, הרי לחשבון זה \u0003שקיל\u0004 \u0005[נוטל]\u0006 \u0003ארבע.\u0004","\u0003רבא אמר\u0004 שיש ליישב את הברייתא באופן אחר: ברייתה זו \u0003כולה\u0004 כשיטת \u0003רבי היא וסבר לה\u0004 \u0005[וסובר הוא]\u0006 כשיטת \u0003ר' יהודה\u0004 שאין מתחלקות אלא עשר חלות בלבד \u0003ואלא מאי\u0004 \u0005[מה]\u0006 ענין \u0003ארבע? הא\u0004 \u0005[הרי]\u0006 \u0003חמש\u0004 חלות \u0003בעי למשקל\u0004 \u0005[היה צריך ליטול]!\u0006","יש לומר כי \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא דאיכא\u0004 \u0005[כאן\u0006 מדובר \u0005שיש]\u0006 \u0003משמר המתעכב,\u0004 שלפעמים כשחל חלקו הראשון של החג בסופו של השבוע הקבוע למשמר מסויים וחלקו האחרון בשבוע הקבוע למשמר שאחריו, היה נשאר אותו משמר בירושלים אף שכבר סיים את שבוע עבודתו ומשמר אחר החל בעבודה, עד סופו של החג, מפני כבוד החג. וכמו כן המשמר שרק חלקו האחרון של החג נפל להיות במהלך שבוע העבודה שלו, היה מקדים לבוא כבר מתחילת החג אף שאינו מתחיל בעבודה אלא בסופו של החג. ולפי הדין, בשעת הרגל, כל משמר השוהה בירושלים אף שלא בשעת עבודתו, הריהו נוטל חלק כחלק בלחם הפנים כמו המשמר שעובד, \u0003הא דליכא\u0004 \u0005[כאן\u0006 מדובר \u0005שאין]\u0006 \u0003משמר המתעכב\u0004 ואין לחם הפנים צריך להתחלק אלא למשמר אחד בלבד.","\u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003משמר המתעכב —\u0004 נוטל המתעכב שתים, והיוצא שתים, ואם כן \u0003משמנה\u0004 חלות בלבד \u0003בעי למפלג\u0004 \u0005[צריך לחלוק]\u0006 והוא, הכהן הגדול \u0003שקיל\u0004 \u0005[נוטל]\u0006 \u0003ארבע\u0004 מהן, ו\u0003אי ליכא\u0004 \u0005[ואם אין]\u0006 \u0003משמר המתעכב — מעשר\u0004 חלות \u0003בעי למפלג\u0004 \u0005[צריך הוא לחלוק]\u0006 \u0003ושקיל\u0004 \u0005[ונוטל]\u0006 \u0003חמש.\u0004","על הסברו של רבא מקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאף את אמצעה של הברייתא יכול אתה להעמיד כשיטת רבי ובמשמר המתעכב, אם כן \u0003מאי\u0004 \u0005[מה פירוש]\u0006 הדבר ש\u0003רבי אומר: לעולם חמש?\u0004 שמלשון זה משמע שהוא חולק על עיקר הדין, והרי לפי הסבר זה, מודה הוא שלפעמים מקבל הכהן הגדול רק ארבע! ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה],\u0006 ליישב את לשון הברייתא כדברי רבא.","\u0003מסרו לו\u0004 לכהן הגדול \u0003זקנים מזקני בית דין, וקורין לפניו בסדר היום\u0004 אותו יצטרך הכהן הגדול לקרוא למחר, \u0003ואומרים לו: אישי\u0004 (אדוני) \u0003כהן גדול! קרא אתה\u0004 עצמך \u0003בפיך, שמא שכחת\u0004 קריאה זו \u0003או שמא לא למדת\u0004 לקרוא. \u0003ערב יום\u0004 ה\u0003כפורים\u0004 ב\u0003שחרית\u0004 היו \u0003מעמידין אותו בשער\u0004 ה\u0003מזרח\u0004 של העזרה, \u0003ומעבירין לפניו פרים ואלים וכבשים כדי שיהא מכיר ורגיל בעבודה\u0004 שהרי בעבודת יום הכיפורים מקריב מכל אחד ממינים אלה. \u0003כל שבעת הימים\u0004 שהיה בלשכת פרהדרין \u0003לא היו מונעין ממנו מאכל ומשתה\u0004 כרצונו, אולם \u0003ערב יום הכפורים עם חשיכה לא היו מניחין אותו לאכול הרבה, מפני שהמאכל מביא את השינה\u0004 וכפי שיבואר להלן לא היו מניחין לו לישון.","על מה שאמרו שהיו הזקנים מלמדין את הכהן הגדול לקרוא, שמא שכח או לא למד, תוהים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שמא שכח — לחיי\u0004 \u0005[מוטב]\u0006 שיתכן שכהן זה אינו רגיל לקרוא הרבה, ושכח קריאה זו. \u0003אלא שמא לא למד\u0004 כיצד יתכן הדבר? \u0003מי מוקמינן כי האי גוונא\u0004 \u0005[האם מעמידין אנו\u0006 כהן גדול \u0005כגון זה]\u0006 שלא למד מקרא?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"והכהן הגדול מאחיו\"\u0004 (ויקרא כא, י) ללמדנו: \u0003שיהא גדול מאחיו בכח, בנוי, בחכמה, ובעושר. אחרים אומרים:\u0004 עושר אינו מעכב לכתחילה, ו\u0003מנין שאם אין לו\u0004 רכוש משלו \u0003שאחיו הכהנים מגדלין אותו\u0004 מרכושם — \u0003תלמוד לומר: \"והכהן הגדול מאחיו\"\u0004 והוא מפרשו: \u0003גדלהו\u0004 ברכוש \u0003משל אחיו.\u0004 על כל פנים מוסכם שהוא צריך להיות גדול בחכמה!","\u0003אמר רב יוסף: לא קשיא,\u0004 \u0005[אינו קשה];\u0006 \u0003כאן במקדש ראשון\u0004 שהיו נוהגים בו כהלכה, היה באמת הכהן הגדול מושלם בכל המידות \u0003כאן במקדש שני\u0004 שנעשו בו דברים שלא כדין, היה יכול להיות מצב שלא היה הכהן הגדול בן מקרא. ש\u0003אמר רב אסי: תרקבא דדינרי עיילא ליה\u0004 \u0005[\u0006כלי בן \u0005שני קבים מלא דינרי\u0006 זהב \u0005הכניסה לו]\u0006 \u0003מרתא בת בייתוס\u0004 שהיתה עשירה \u0003לינאי מלכא\u0004 \u0005[המלך]\u0006 \u0003על דאוקמיה\u0004 \u0005[שהעמיד,\u0006 מינה\u0005]\u0006 את \u0003יהושע בן גמלא בכהני רברבי\u0004 \u0005[ככהן גדול]\u0006 והרי זו דוגמה כיצד היו כהנים הגדולים מתמנים על ידי שוחד ומתנות, ולכן יתכן שהיו ביניהם גם בורים גמורים.","שנינו במשנה ש\u0003ערב יום הכפורים שחרית\u0004 העבירו לפניו בהמות שונות. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003אף השעירים\u0004 היו מביאים לפניו. ושואלים: \u0003ותנא דידן, מאי טעמא לא תנא\u0004 \u0005[והתנא שלנו\u0006 במשנתנו \u0005מה טעם לא שנה]\u0006 \u0003שעירים\u0004 עמהם? ומשיבים: \u0003כיון\u0004 ששעירים אלה ש\u0003על חטא קאתו\u0004 \u0005[הם באים] —\u0006 \u0003חלשה דעתיה\u0004 \u0005[נחלשת דעתו]\u0006 שמזכירים לו חטאים ויש בכך מעין עלבון לו, ולכן אין מראין לו אותם.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחוששין לכך, \u0003פר נמי\u0004 \u0005[גם כן]\u0006 ש\u0003על חטא הוא דאתי\u0004 \u0005[שבא]\u0006 גם כן לא יעבירו לפניו! ומשיבים: \u0003פר כיון\u0004 ש\u0003עליו ועל אחיו הכהנים הוא דאתי\u0004 \u0005[שבא]\u0006 ולא על חטאות כל ישראל, הרי \u0003באחיו הכהנים, אי איכא איניש דאית ביה מילתא מידע ידע ליה ומהדר ליה\u0004 \u0005[אם יש אדם שיש בו דבר\u0006 של עבירה \u0005יודע אותו\u0006 הכהן הגדול \u0005ומחזיר אותו]\u0006 \u0003בתשובה,\u0004 לכך אין כן רע בכך שמראים לו את הפר כי דבר זה מזכיר לו את התחייבותו. אולם \u0003בכולהו\u0004 \u0005[בכל]\u0006 \u0003ישראל לא ידע\u0004 \u0005[אינו יודע]\u0006 ואינו יכול לתקן, ואם יעבירו לפניו את השעיר — יזכר שמרובים העוונות ואין בידו לתקנם ויבוא לידי חלישות הדעת.","כיון שאמרנו כי הכהן הגדול יודע בפגמים של כל אחיו הכהנים, מעירים: \u0003אמר רבינא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם]\u0006 בפתגם עממי: \u0003\"אי בר אחתיך דיילא הוי\u0004 \u0005[אם בן אחותך\u0006 האהוב מאד עליך \u0005נעשה שוטר]\u0006 \u0003חזי, בשוקא קמיה לא תחליף\u0004 \u0005[ראה שבשוק לפניו אל תעבור]\u0006.","שנינו במשנה: \u0003כל שבעת הימים\u0004 שהיה הכהן הגדול פורש מביתו לפני יום הכיפורים \u0003לא היו מונעין ממנו מאכל. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה בן נקוסא אומר: מאכילין אותו\u0004 בערב יום הכיפורים \u0003סלתות וביצים כדי למסמסו\u0004 (להביאו לידי שלשול קל) שלא יצטרך לנקביו ביום הכיפורים. \u0003אמרו לו: כל שכן, שאתה מביאו לידי חימום.\u0004 כי מאכלים אלה עשויים לגרום שיראה קרי, והרי זה סותר את כל המאמץ שהושקע כדי שיהא טהור.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003סומכוס אמר משום ר' מאיר: אין מאכילין אותו לא\u0004 דברים הרמוזים בראשי התיבות \u0003\"אב\"י\" ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003לא\u0004 דברים הרמוזים בראשי התיבות \u0003\"אבב\"י\", ויש אומרים: אף לא יין לבן.\u0004 ומפרשים: \u0003לא \"אב\"י\" — לא א תרוג, ולא ביצים, ולא י ין ישן, ואמרי לה לא \"אבב\"י\" — לא אתרוג, ולא ביצים, ולא בשר שמן, ולא יין ישן, ויש אומרים אף לא יין לבן, מפני שהיין לבן מביא את האדם לידי טומאה\u0004 של קרי.","כיוצא בו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003זב\u0004 שראה זיבה \u0003תולין\u0004 לו שמא לא זיבה ממש היתה זו אלא נגרם הדבר מפני סיבה אחרת, כגון \u0003במאכל, וכל מיני מאכל\u0004 שמא אכל יותר מדי ובא לידי קרי. \u0003אלעזר בן פנחס אומר משום ר' יהודה בן בתירא: אין מאכילין אותו\u0004 את הזב בימים שהוא נבדק לטהרתו \u0003לא\u0004 דברים הרמוזים בראשי התיבות \u0003\"חגב\"י\" ולא\u0004 דברים הרמוזים בראשי התיבות \u0003\"גב\"ם\", ולא כל דברים המביאין לידי טומאה\u0004 של קרי. ומפרשים מיד: \u0003לא \"חגב\"י\" — לא חלב, ולא גבינה, ולא ביצה, ולא יין. ולא \"גב\"ם\" — מי גריסין של פול, ובשר שמן, ומרייס\u0004 (דגים קטנים בציר מלוח).","ושואלים: במה שאמר \u0003\"ולא כל דברים המביאין לידי טומאה\",\u0004 נתכוון \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי הא\u0004 \u0005[להביא,\u0006 לרבות דבר \u0005זה]\u0006 הנוסף \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003חמשה דברים מביאים את האדם לידי טומאה\u0004 בקרי, \u0003ואלו הן: השום\u0004"],["\u0003והשחלים וחלגלוגות והביצים והגרגיר.\u0004 כיון שהוזכר הגרגיר מביאים את הכתוב: \u0003\"ויצא אחד אל השדה ללקט ארת\"\u0004 (מלכים ב' ד, לט) \u0003תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' מאיר:\u0004 \"אורות\" אלה \u0003זה\u0004 הצמח הקרוי \u0003\"גרגיר\". אמר ר' יוחנן: למה נקרא שמן \"אורות\" —\u0004 לפי \u0003שמאירות את העינים\u0004 שמועילות לבריאות העין. \u0003אמר רב הונא: המוצא גרגיר, אם יכול לאכלו — אוכלו, ואם לאו\u0004 שאינו יכול לאכלו, לפחות — \u0003מעבירו על גבי עיניו\u0004 ואף זה מועיל לו. \u0003אמר רב פפא:\u0004 דברים אלה אמורים דווקא \u0003בגרגירא מצרנאה\u0004 \u0005[בגרגיר הגדל על המיצר]\u0006 הגבול שבין השדות, שמקום זה פנוי מזרעים אחרים ולכך גדל הוא שם ברוב כוח, ומשובח ביותר.","כעין זה \u0003אמר רב גידל אמר רב: אכסנאי\u0004 (אורח בבית) \u0003לא יאכל ביצים\u0004 שהם מביאים לידי קרי \u0003ולא יישן בטליתו של בעל הבית\u0004 שמא יראה קרי וימצא על הטלית, ונמצא מתגנה בעיני מארחו. בהמשך לדברים האמורים כאן בהנהגת האורחים מסופר: \u0003רב כי מקלע\u0004 \u0005[כאשר היה מזדמן]\u0006 למקום \u0003דרשיש\u0004 היה \u0003מכריז: מאן הויא ליומא\u0004 \u0005[מי תהיה ליום\u0006 אחד\u0005],\u0006 כלומר: מי מוכנה להנשא לי ליום אחד, כדי שלא יהא בלא אשה במקום, ולאחר כך יגרשנה. וכיוצא בזה, \u0003רב נחמן כד מקלע\u0004 \u0005[כאשר היה מזדמן]\u0006 לעיר \u0003שכנציב\u0004 היה \u0003מכריז: מאן הויא ליומא\u0004 \u0005[מי תהיה ליום]\u0006 להנשא לי בו.","ומקשים; \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אליעזר בן יעקב אומר: לא ישא אדם אשה במדינה זו, וילך וישא אשה במדינה אחרת, שמא יזדווגו\u0004 הצאצאים \u0003זה אצל זה\u0004 בלא לדעת את קרבתם המשפחתית \u0003ונמצא\u0004 לעתים \u0003אח נושא\u0004 את \u0003אחותו\u0004 או \u0003אב נושא\u0004 את \u0003בתו,\u0004 ונמצא \u0003ממלא כל העולם כולו ממזרות, ועל זה נאמר: \"ומלאה הארץ זמה\"\u0004 (ויקרא, יט, ל). \u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה: \u0003רבנן\u0004 \u0005[לחכמים] —\u0006 \u0003קלא אית להו\u0004 \u0005[קול יש להם],\u0006 שכיון שאנשים מפורסמים הם, ללא ספק יתייחסו צאצאיהם אחריהם ולא יבואו לטעות בהם ולהחליפם באחרים.","ומקשים מצד אחר, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 אשה ש\u0003תבעוה\u0004 (הציעו לה) \u0003להנשא, ונתפיסה\u0004 (הסכימה) — \u0003צריכה לישב שבעה נקיים\u0004 שמא מתוך חימוד ראתה דם ולא שמה לב, והריהי טמאה טומאת נדה. ואיך אם כן יכלו אותם חכמים לשאת אשה בו ביום? ומשיבים: \u0003רבנן אודועי הוו מודעו להו, מקדם הוו קדמי ומשדרי שלוחא\u0004 \u0005[חכמים היו מודיעים להם, היו מקדימים ושולחים שליח]\u0006 והוא היה מכריז בשם החכם שרצונו לשאת אשה במקום זה והיתה האשה שהסכימה להנשא להם ממתינה שבעה נקיים.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לא נישואין ממש היו מציעים להן \u0003אלא יחודי הוו מיחדי להו\u0004 \u0005[רק\u0006 ל\u0005יחוד בלבד היו מתיחדים אתן]\u0006 בלא נישואין ובלא ביאה וידעו הנשים שאין כאן נישואין ממש, ולא היו מחמדות (תוספות) \u0003לפי שאינו דומה מי שיש לו פת בסלו למי שאין לו פת בסלו,\u0004 שמי שאין לו פת מרגיש יותר את הרעב, כך אותו אדם שאין לו אשה משתוקק ביותר, וכדי להמנע מכך דאגו שיהו נשים מיוחדות להם.","\u0003מסרוהו זקני בית דין\u0004 שקראו לפניו בסדר היום קודם לכן \u0003לזקני כהונה\u0004 והם \u0003העלוהו לבית אבטינס,\u0004 ולאחר מכן \u0003השביעוהו, ונפטרו\u0004 ממנו \u0003והלכו להם. ואמרו לו\u0004 בשעה שמשביעים אותו; \u0003אישי\u0004 (אדוני) \u0003כהן גדול! אנו שלוחי בית דין, ואתה שלוחנו ושליח בית דין. משביעין אנו עליך במי ששכן שמו בבית הזה שלא תשנה דבר מכל מה שאמרנו לך\u0004 בסדר הקטרת הקטורת ושאר דברים שאתה עתיד לעשות ביום הכיפורים כשאתה לבד. ומספרים: לאחר שבועה זו \u0003הוא פורש ובוכה, והן פורשין ובוכין\u0004 מחמת צער שהוזקקו לכך.","בלילה, היו מעסיקים אותו שלא יישן, \u0003אם היה חכם — דורש\u0004 הוא לפני הרבים בתורה, \u0003ואם לאו — תלמידי חכמים דורשים לפניו. ואם\u0004 היה \u0003רגיל לקרות\u0004 בעצמו במקרא — \u0003קורא, ואם לאו — קורין לפניו. ובמה קורין לפניו\u0004 בספרים שיש בהם ענין, לסייע שלא ירדם: \u0003באיוב ובעזרא ובדברי הימים. זכריה בן קבוטל אומר: פעמים הרבה קריתי לפניו\u0004 בספר \u0003דניאל\u0004 שאף הוא מרובה ענין."],["\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 מוליכים אותו לבית אבטינס, כדי \u0003ללמדו חפינה\u0004 של קטורת שהיא מלאכה מורכבת וקשה, שבלשכת בית אבטינס היה מקום הכנת הקטורת. \u0003אמר רב פפא: שתי לשכות היו לו לכהן גדול, אחת לשכת פרהדרין ואחת לשכת בית אבטינס. אחת\u0004 מהן היתה \u0003בצפון\u0004 של העזרה \u0003ואחת בדרום.\u0004 ומסבירים: \u0003אחת בצפון, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שש לשכות היו בעזרה שלש בצפון ושלש בדרום,\u0004 ואלו הן הלשכות","\u0003שבדרום: לשכת המלח, לשכת הפרוה, לשכת המדיחין.\u0004 ומפרטים את תפקידה של כל לשכה: \u0003לשכת המלח — ששם היו נותנין\u0004 (מאחסנים) \u0003מלח לקרבן, לשכת הפרוה — ששם היו מולחין\u0004 את \u0003עורות\u0004 ה\u0003קדשים\u0004 השייכים לכהנים, כדי שלא יקקלקלו. \u0003ועל גגה\u0004 של אותה לשכה \u0003היתה בית טבילה לכהן גדול ביום הכפורים. לשכת המדיחין — שם היו מדיחין\u0004 (רוחצים) את \u0003קרבי הקדשים,\u0004 שאין מעלין את הקרבנות כשיש בתוך מעיהם לכלוך ומזון לא מעוכל. \u0003ומשם מסיבה\u0004 (מערכת מדרגות עגולה) שהיתה \u0003עולה לגג בית הפרוה.\u0004","ו\u0003שלש\u0004 לשכות \u0003שבצפון\u0004 העזרה היו: \u0003לשכת העץ, לשכת הגולה, לשכת הגזית. לשכת העץ — אמר ר' אליעזר בן יעקב\u0004 שהוא מחברה של מסכת מדות שבה מצויה משנה זו: \u0003שכחתי\u0004 ל\u0003מה היתה\u0004 לשכה זו \u0003משמשת. אבא שאול אומר: לשכת כהן גדול היתה אחורי שתיהן\u0004 אחורי לשכת הגולה ולשכת הגזית \u0003וגג שלשתן שוה,\u0004 ששלוש אלה היו צמודות זו לזו, וגג אחד לכולן.","\u0003לשכת הגולה — שם היה בור הגולה\u0004 ומכאן נגזר שמה, \u0003והגלגל\u0004 היה \u0003נתון עליו\u0004 שבעזרתו היו שואבים, \u0003ומשם מספיקין מים לכל העזרה\u0004 לרחיצה ולשטיפה. \u0003לשכת הגזית שם היה\u0004 המקום שבו \u0003סנהדרין\u0004 גדולה \u0003של ישראל יושבת,\u0004 ועיסוקה הקבוע של סנהדרין זו שהיא \u0003דנה את הכהנים\u0004 אם ראויים הם לעבודה \u0003ומי שנמצא בו פסול\u0004 משום מום או משום יחוס \u0003היה לובש שחורים ומתעטף שחורים\u0004 לאות צער ואבל \u0003ויצא והלך לו,\u0004 לפי שאינו ראוי לכהן. \u0003ושלא נמצא בו פסול — היה לובש לבנים ומתעטף לבנים\u0004 כביטוי של שמחה \u0003ונכנס ומשמש עם אחיו הכהנים.\u0004 נמצאנו למדים איפוא כי לשכתו של הכהן הגדול היתה בצפון העזרה.","וההוכחה לכך כי גם לשכה \u0003אחת בדרום\u0004 היתה לו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שבעה שערים היו בעזרה, שלשה בצפון ושלשה בדרום ואחד במזרח.\u0004 שערים \u0003שבדרום:\u0004 הראשון — הוא \u0003שער הדלקה, שני לו — שער הקרבן, שלישי לו — שער המים.\u0004 השער \u0003שבמזרח\u0004 היה קרוי \u0003שער נקנור, ושתי לשכות היו שם\u0004 ליד שער נקנור \u0003אחת בימינו ואחת בשמאלו, אחת\u0004 היתה \u0003לשכת פנחס המלבש\u0004 ששם היו מאוכסנים בגדי הכהונה, \u0003ואחת\u0004 היתה \u0003לשכת עושי חביתין,\u0004 ששם הכינו את מנחת המחבת עבור הכהן הגדול.","שערים \u0003שבצפון —\u0004 הראשון הוא \u0003שער ניצוץ,\u0004 ואותו שער \u0003בנין אכסדרה היה\u0004 שלא היה סגור לגמרי מכל צד, אלא מקורה היה ופתוח למחצה, \u0003ועלייה בנויה לו על גביו\u0004 ו\u0003שם\u0004 הוא אחד המקומות בהם היו עומדים שומרי המקדש לכבוד, והיו ה\u0003כהנים שומרים\u0004 שם \u0003מלמעלה\u0004 בעליה, וה\u0003לוים מלמטה. ושלפנים הימנו\u0004 לשער זה היה \u0003החיל\u0004 ופתח היה יוצא משם לחיל. \u0003שני לו\u0004 לשער זה \u0003— שער הקרבן, שלישי לו — שער בית המוקד.\u0004","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמש טבילות ועשרה קדושין\u0004 (רחיצות ידים ורגלים) היה \u0003טובל כהן גדול ומקדש בו ביום,\u0004 ואת \u0003כולן\u0004 היה עושה \u0003בקדש, על גג בית הפרוה. חוץ מזו\u0004 מטבילה ראשונה \u0003שהיתה בחול\u0004 כיון שלא היתה מיוחדת לעבודת יום הכיפורים דווקא, אלא לצורך כניסה לבית המקדש, כדרך שיהו עושים הכהנים בכל יום, ואותה היה עושה \u0003על גב שער המים, ובצד לשכתו היתה\u0004 טבילה זו. ומכאן שהיתה לכהן הגדול לשכה בצד שער המים, שהוא, כפי שאמרנו, בדרומה של העזרה.","מצאנו איפוא כי היו לכהן הגדול שתי לשכות לשמושו, אולם \u0003ולא ידענא\u0004 \u0005[ואין אנו יודעים]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לשכת פרהדרין בצפון ולשכת בית אבטינס בדרום, או\u0004 להיפך — \u0003לשכת בית אבטינס בצפון ולשכת פרהדרין בדרום.\u0004 ומעירים: \u0003ומסתברא\u0004 \u0005[ומסתבר\u0006 לומר\u0005]\u0006 ש\u0003לשכת פרהדרין בדרום הואי\u0004 \u0005[היתה]\u0006 ושם היה המקום בו היה הכהן הגדול לן.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 סברה זו? כי באופן זה \u0003מקדים\u0004 הכהן בכל בוקר \u0003קאי\u0004 \u0005[\u0006ו\u0005עומד]\u0006 \u0003ומיסך את רגליו\u0004 (עושה צרכיו) \u0003וטביל\u0004 \u0005[וטובל]\u0006 בצד לשכתו שהיתה בדרום, \u0003ואזיל\u0004 \u0005[והולך]\u0006 ל\u0003צפון\u0004 העזרה ללשכה השניה היא לשכת בית אבטינס \u0003וגמר\u0004 \u0005[ולומד]\u0006 שם את מלאכת ה\u0003חפינה ואתי\u0004 \u0005[ובא]\u0006 \u0003לבית המקדש ועביד\u0004 \u0005[ועושה]\u0006 \u0003עבודה כולי יומא\u0004 \u0005[כל היום].\u0006 \u0003לבהדי פניא מדו עליה\u0004 \u0005[סמוך לערב מזים עליו]\u0006 מי חטאת, כפי שכבר נאמר, \u0003והדר אזיל לדרום\u0004 \u0005[והוא הולך,\u0006 חוזר\u0005]\u0006 ובא \u0003וטביל\u0004 \u0005[וטובל]\u0006 שוב בצד לשכתו \u0003ונייח\u0004 \u0005[ונח]\u0006 בלשכתו.","\u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 כי \u0003לשכת פרהדרין\u0004 היתה \u0003בצפון\u0004 נמצא שצריך הכהן הגדול לטרוח וללכת הרבה. שלפי זה \u0003מקדים קאי\u0004 \u0005[\u0006ו\u0005עומד]\u0006 \u0003ומיסך רגליו\u0004 (ועושה צרכיו), אולם מקום טבילתו היה, כמו שנאמר בברייתא, בדרום, אם כך \u0003אזיל\u0004 \u0005[הולך]\u0006 \u0003לדרום וטביל\u0004 \u0005[וטובל]\u0006 \u0003וגמר\u0004 \u0005[ולומד]\u0006 \u0003חפינה ואתי\u0004 \u0005[ובא]\u0006 \u0003לבית המקדש ועביד\u0004 \u0005[ועושה]\u0006 \u0003עבודה כוליה יומא\u0004 \u0005[כל היום],\u0006 \u0003להדי פניא מדו עליה\u0004 \u0005[סמוך לערב מזים עליו],\u0006 \u0003והדר אזיל\u0004 \u0005[וחוזר והולך]\u0006 ובא \u0003לדרום וטביל\u0004 \u0005[וטובל]\u0006 \u0003ובעי מהדר ומיזל\u0004 \u0005[וצריך לחזור וללכת]\u0006 ולבוא \u0003לצפון ומינח\u0004 \u0005[ולנוח]\u0006 \u0003ומי טרח מטרחינן ליה כולי האי\u0004 \u0005[והאם מטריחים אנו אותו עד כדי כך]?\u0006 אלא מסתבר לומר, שלשכת פרהדרין — לשכתו הפרטית של הכהן הגדול היתה בדרום, שאינו צריך לטרוח כל כך בהליכה.","את הראיה הזו דוחים: \u0003אלמה\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 \u0003לא\u0004 נטריח אותו? אדרבה, \u0003מטרחינן ליה טפי\u0004 \u0005[מטריחים אנו אותו יותר]\u0006 ויש טעם בדבר, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003צדוקי הוא ליפרוש\u0004 \u0005[שיפרוש],\u0006 שהרי אינו ירא שמים ומתוך שלא ירצה בטירחה יתרה יפרוש מן התפקיד, ונמצאנו נשכרים בכך שאין צדוקי משמש בכהונה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפילו אם אדם כשר הוא, מטעם אחר יש להטריחו — כדי \u0003שלא תזוח דעתו עליו\u0004 שלא יתגאה בתפקידו הרם. שמתוך הטירחה אין ליבו פנוי לחשוב בגדולת עצמו. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שאנו מטריחים אותו בכוונה, אם כן \u0003נעבדינהו לתרוייהו בהדי הדדי\u0004 \u0005[שנעשה את שתיהן,\u0006 את שתי הלשכות של הכהן, \u0005זו ליד זו]\u0006 \u0003אי נמי תסגי ליה בחדא\u0004 \u0005[או גם תספיק לו\u0006 לשכה \u0005אחת].\u0006 ומתוך שלא עשו כן — הרי זו ראיה שבכוונה מטריחים את הכהן הגדול, ואם כן אין להוכיח דבר לענין מקומן של הלשכות השונות.","שנינו במשנה כי \u0003אמרו לו לכהן הגדול: אישי\u0004 (אדוני) \u0003כהן גדול\u0004 אתה שלוחנו ושליח בית דין. ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 \u0003תהוי\u0004 \u0005[תהא זו]\u0006 \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הני כהני שלוחי דרחמנא נינהו\u0004 \u0005[אותם הכהנים\u0006 בעבודת הקרבנות \u0005שלוחים של הקדוש ברוך הוא הם],\u0006 שאין לראות בעבודתם את קיום שליחות עם ישראל, אלא את קיום שליחותו של הקדוש ברוך הוא שצווה אותם לכך. וההוכחה לדעה זו: \u0003דאי אמרת שלוחי דידן נינהו\u0004 \u0005[שאם אומר אתה\u0006 שהכהנים \u0005שליחים שלנו הם]\u0006"],["\u0003מי איכא מידי דאנן לא מצינן למעבד ושלוחי דידן מצו עבדי\u0004 \u0005[האם יש דבר שאנו\u0006 עצמנו \u0005איננו יכולים לעשות, ואילו השלוחים שלנו יכולים לעשות]?\u0006 שהרי תפקיד השליח הוא למלאות את מקום המשלח, וכיון שאנו, הישראלים, אסורים בכניסה לקודש ובעשיית עבודה, לכן אין לומר שהכהנים נחשבים כשלוחים שלנו. ולשון המשנה שזקני בית דין אומרים לכהן הגדול שהוא שלוחם, סותרת לכאורה שיטה זו! ומתרצים: \u0003הכי קאמרי ליה\u0004 \u0005[כך אומרים לו],\u0006 כלומר, זו היא כוונת הדברים: \u0003משביעין אנו עליך על דעתנו ועל דעת בית דין\u0004 לומר לו שלא יעבור על השבועה באומרו שנתכוון בלבו לדבר אחר, אלא הוא נשבע לפי הבנת הדברים על ידי בית הדין. ואין מכאן ראיה איפוא לענין שליחותו של הכהן.","אמרנו ש\u0003הוא\u0004 הכהן הגדול \u0003פורש ובוכה והן\u0004 בית הדין \u0003פורשין ובוכין.\u0004 ומסבירים: \u0003הוא פורש ובוכה\u0004 משום העלבון \u0003שחשדוהו\u0004 שהוא \u0003צדוקי, והם פורשין ובוכין\u0004 — שכן \u0003אמר ר' יהושע בן לוי: כל החושד בכשרים לוקה בגופו,\u0004 ושמא הכהן הגדול כשר היה וחשדו בו לחינם.","ושואלים: \u0003וכל כך למה\u0004 מקפידים עליו להשביעו? ומסבירים: כדי \u0003שלא יתקן\u0004 את הקטורת וידליקנה \u0003מבחוץ\u0004 בהיכל לפני הכניסה לקודש הקדשים \u0003ויכניס\u0004 את המחתה כאשר הקטורת בוערת אל קודש הקדשים, \u0003כדרך\u0004 שהיו ה\u0003צדוקין עושין.\u0004 וכיון שהכהן הגדול נמצא שם לבדו ואי אפשר לבדוק זאת — יש צורך להשביעו על כך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מעשה בצדוקי אחד\u0004 שנתמנה לכהונה גדולה \u0003שהתקין\u0004 את הקטורת \u0003מבחוץ\u0004 ורק אחר כך \u0003הכניס\u0004 לבית קודש הקדשים\u0003. ביציאתו היה שמח שמחה גדולה\u0004 שהצליח בכך. \u0003פגע\u0004 (פגש) \u0003בו\u0004 באותו צדוקי \u0003אביו\u0004 ו\u0003אמר לו: בני, אף על פי שצדוקין אנו\u0004 ולדעתנו כך צריכים לעשות, \u0003מתיראין אנו מן הפרושים\u0004 ואיננו נוהגים הלכה למעשה כשיטתנו. \u0003אמר לו\u0004 הבן: \u0003כל ימי הייתי מצטער על המקרא הזה: \"כי בענן אראה על הכפרת\"\u0004 (ויקרא טז, ב) שהצדוקים מבינים שלאחר שכבר קיים ענן הקטורת אז \"אראה על הכפורת\", — אכנס לבית קודש הקדשים, \u0003אמרתי: \"מתי יבוא לידי\u0004 לקיים פסוק זה כפי שיטתנו \u0003ואקיימנו, עכשיו שבא לידי — לא אקיימנו\"?\u0004","\u0003אמרו: לא היו ימים מועטין\u0004 שעברו \u0003עד שמת\u0004 אותו צדוקי \u0003והוטל באשפה, והיו תולעין יוצאין מחוטמו\u0004 כעונש על מה שעשה. \u0003ויש אומרים:\u0004 כבר \u0003ביציאתו\u0004 מן הקודש \u0003ניגף,\u0004 שכן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: כמין קול נשמע בעזרה\u0004 משום \u0003שבא מלאך וחבטו על פניו. ונכנסו אחיו הכהנים\u0004 להוציאו משם \u0003ומצאו\u0004 סימן \u0003ככף רגל עגל בין כתפיו,\u0004 והוא סימן למכת המלאך, שהרי \u0003נאמר\u0004 במלאכים: \u0003\"ורגליהם רגל ישרה וכף רגליהם ככף רגל עגל\"\u0004 (יחזקאל א, ז).","במשנה נזכר ש\u0003אמר ר' זכריה בן קבוטל\u0004 שהוא עצמו היה קורא לפני הכהן הגדול בספר דניאל. \u0003מתני ליה\u0004 \u0005[משנה,\u0006 מלמד \u0005היה לו],\u0006 \u0003רב חנן בר רבא לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 בלשון זו: \u0003אמר ר' זכריה בן קפוטל, ומחוי ליה רב בידיה\u0004 \u0005[והיה רב מראה לו בידו]\u0006 שלא כך צריך לגרוס אלא \u0003קבוטל\u0004 בב'. ושואלים: מדוע הראה לו כן? \u0003ונימא ליה מימר\u0004 \u0005[שיאמר לו אמירה\u0006 מפורשת\u0005]!\u0006 ומשיבים: \u0003קריאת שמע הוה קרי\u0004 \u0005[היה קורא]\u0006 רב באותה שעה, ולכן לא יכול היה להפסיק בדיבור.","ושואלים: \u0003וכי האי גוונא מי שרי\u0004 \u0005[ובכגון זה האם מותר]\u0006 להפסיק ולרמוז בתוך הקריאה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק בר שמואל בר מרתא: הקורא את שמע לא ירמוז בעיניו\u0004 באותה שעה, \u0003ולא יקרוץ\u0004 (יסגור, ויפתח לרמז) \u0003בשפתותיו, ולא יורה באצבעותיו.\u0004 וכיוצא בו \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אלעזר חסמא אומר: הקורא את שמע ומרמז בעיניו ומקרץ בשפתותיו ומראה באצבעו — עליו הכתוב אומר: \"ולא אתי קראת יעקב\"\u0004 (ישעיה מג, כב), שמראה שאין לפניו כבוד שמים, וכביכול אינו קורא לפני הקדוש ברוך הוא. ואם כן כיצד רמז רב בקריאת שמע?","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאסור להפסיק אפילו ברמיזה בלבד הוא \u0003בפרק ראשון\u0004 של קריאת שמע שחמור ועיקרי יותר, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שרימז רב בידו בשעת קריאת שמע היה זה \u0003בפרק שני\u0004 ובו מותר להפסיק באופן זה לצורך דבר חשוב.","כיון שהזכרנו את הענין מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: נאמר \u0003\"\u0004והיו הדברים האלה אשר אנוכי מצוך היום על לבבך ושננתם לבניך \u0003ודברת בם\"\u0004 (דברים ו, ו-ז) משמע: \"ודברת\" — הותר לך לצרכים מסויימים לדבר \u0003בם\u0004 — בתוך דברי תורה וקריאת שמע, מותר להפסיק ולדבר בהם לעת צורך חשוב, אבל \u0003לא בתפלה,\u0004 שבה אסור להפסיק בדיבור לכל צורך שהוא. ופירוש אחר: \u0003\"ודברת בם\"\u0004 הכוונה להדגיש: \u0003בם\u0004 בדברי תורה דווקא \u0003יש לך רשות לדבר\u0004 אבל \u0003לא בדברים אחרים,\u0004 כגון בדברים המביאים לידי קלות ראש.","\u0003ר' אחא אומר: \"ודברת בם\"\u0004 כוונתו: \u0003עשה אותן\u0004 את דברי התורה \u0003קבע ואל תעשם ארעי. אמר רבא: השח שיחת חולין\u0004 שאין בה מדברי תורה ואין בה צורך מיוחד \u0003עובר\u0004 על מצות \u0003עשה, שנאמר: \"ודברת בם\"\u0004 וכוונתו: \u0003בם — ולא בדברים אחרים. רב אחא בר יעקב אמר:\u0004 יתר על כן, \u0003עובר\u0004 אף \u0003בלאו, שנאמר: \"כל הדברים יגעים לא יוכל איש לדבר\"\u0004 (קהלת א, ח), לומר שהמדבר דברים בטלים — עובר על לאו זה, ש\"לא יוכל\" משמעו — אינו רשאי.","אם \u0003בקש\u0004 הכהן הגדול \u0003להתנמנם\u0004 בלילה, \u0003פרחי\u0004 (צעירי) \u0003כהונה\u0004 היו \u0003מכין לפניו באצבע צרדא\u0004 ומשמיעים רעש, \u0003ואומרים לו\u0004 מפעם לפעם: \u0003אישי\u0004 (אדוני) \u0003כהן גדול! עמוד\u0004 ממטתך \u0003והפג\u0004 (צנן) את עצמך פעם \u0003אחת על הרצפה,\u0004 ותסיר ממך את השינה. \u0003ומעסיקין אותו\u0004 בדרכים שונות \u0003עד\u0004 שיאיר המזרח ו\u0003יגיע זמן השחיטה\u0004 של התמיד של שחר.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 אצבע \u0003צרדא\u0004 שהוזכרה במשנה? \u0003אמר רב יהודה: צרתה דדא\u0004 \u0005[של\u0006 האצבע \u0005הזאת],\u0006 \u0003מאי\u0004 \u0005[ומה]\u0006 \u0003היא\u0004 האצבע הזאת — \u0003גודל,\u0004 וצרדא — צרתה, היא האצבע האמצעית ביד. שהיו מצמידים את האצבע לאגודל בעוצמה, ומשהפרידום היתה האצבע מכה על כף היד והיתה משמיעה קול. וכדי להוכיח מאי עוצמת הקול הנוצרת מהכאה באצבע צרדה, \u0003מחוי\u0004 \u0005[היה מראה]\u0006 \u0003רב הונא\u0004 כיצד מכים כך באצבע צרדא \u0003ואזל קלא בכולי בי\u0004 \u0005[והלך\u0006 ונשמע \u0005הקול בכל בית\u0006 המדרש\u0005]\u0006 של \u0003רב.\u0004 ויש איפוא בקול כזה כדי לגרום לכהן הגדול להתעורר מתרדמתו.","שנינו במשנה כי היו \u0003אומרים לו אישי\u0004 (אדוני) \u0003כהן גדול הפג\u0004 (צנן) את עצמך פעם \u0003אחת על הרצפה\u0004 והתעורר. \u0003אמר רב יצחק: על חדת\u0004 \u0005[הבא,\u0006 הכנס משהו \u0005חדש].\u0006 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 דבר זה של חידוש שביקשו ממנו? \u0003אמרי ליה\u0004 \u0005[היו אומרים לו]:\u0006 \u0003אחוי\u0004 \u0005[הראה לנו\u0006 כיצד עושה אתה\u0005]\u0006 \u0003קידה,\u0004 שזהו דרך השתחוויה מיוחד שהיה הכהן הגדול בקי בו, וקשה מאוד לעשותו, ועל ידי מאמץ זה היה מתעורר.","נאמר במשנה כי היו \u0003מעסיקין אותו עד שיגיע זמן שחיטה. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לא היו מעסיקין אותו לא בנבל ולא בכנור\u0004 שאסור לנגן בהם בחג, \u0003אלא בפה\u0004 היו שרים, \u0003ומה היו אומרין\u0004 — פסוק זה: \u0003\"אם ה' לא יבנה בית שוא עמלו בוניו בו\u0004 אם ה' לא ישמר עיר שוא שקד שומר\u0003\"\u0004 (תהלים קכז, א), לרמז שצריך הכהן להזהר בעבודתו שתהא לשם שמים, כדי שתעלה לרצון, שאם לא יעשה כן — תהא כל טרחתו לשוא.","ומספרים: \u0003מיקירי\u0004 (חשובי) \u0003ירושלים לא היו ישנין כל הלילה\u0004 ועוסקים בתורה \u0003כדי שישמע כהן גדול קול הברה\u0004 (רעש) מן העיר \u0003ולא תהא שינה חוטפתו\u0004 מחמת השקט, כשכל העיר כולה רדומה. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אבא שאול אומר: אף בגבולין\u0004 (חוץ לירושלים) \u0003היו עושין כן\u0004 להיות נעורים כל הלילה \u0003זכר למקדש, אלא שהיו חוטאין,\u0004 שהיו הגברים והנשים משחקים במשחקים משותפים והגיעו בשל כך לידי עבירה.","\u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב נחמן בר יצחק: תרגומא\u0004 \u0005[תרגם],\u0006 אמור את הדברים כלפי העיר \u0003נהרדעא,\u0004 שבה היה מצוי דבר זה. כפי המסופר: ש\u0003אמר לו אליהו\u0004 הנביא \u0003לרב יהודה אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב סלא חסידא\u0004 \u0005[החסיד]:\u0006 \u0003אמריתו\u0004 \u0005[אומרים אתם]\u0006 ומתפלאים: \u0003\"אמאי לא אתי\u0004 \u0005[מדוע לא בא]\u0006 \u0003משיח\"?\u0004 ומה פלא, \u0003והא האידנא יומא דכיפורי הוא\u0004 \u0005[והרי עכשיו יום הכיפורים הוא]\u0006 \u0003ואבעול כמה בתולתא\u0004 \u0005[ונבעלו\u0006 בלילה זה \u0005כמה בתולות]\u0006 \u0003בנהרדעא,\u0004 כפי שאמרנו שהיו נעורים בלילה ומגיעים לידי פריצות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003הקדוש ברוך הוא מאי אמר\u0004 \u0005[מה אומר]\u0006 הוא על חטאים אלה שעושים בני ישראל? \u0003אמר ליה\u0004 \u0005[לו],\u0006 כך הוא אומר:"],["\u0003\"לפתח חטאת רבץ\"\u0004 (בראשית ד, ז) ולא ייפלא איפוא שבני אדם חוטאים. שאל אותו: \u0003ושטן מאי אמר\u0004 \u0005[מה אומר]\u0006 הוא, מה אומר המקטרג על דבר זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שטן ביומא דכיפורי\u0004 \u0005[השטן ביום הכיפורים] —\u0006 \u0003לית ליה רשותא לאסטוני\u0004 \u0005[אין לו רשות להסטין,\u0006 לקטרג\u0005].\u0006 \u0003ממאי\u0004 \u0005[ממה]\u0006 למדנו זאת? \u0003אמר רמי בר חמא: \"השטן\" בגמטריא תלת מאה ושיתין וארבעה הוי\u0004 \u0005[שלוש מאות ששים וארבעה הם]\u0006 ללמד: \u0003תלת מאה ושיתין וארבעה יומי אית ליה רשותא לאסטוני\u0004 \u0005[שלוש מאות ששים וארבעה ימים\u0006 בשנה \u0005יש לו רשות להסטין,\u0006 לקטרג\u0005]\u0006 וומתוך ששנת החמה בת שלוש מאות שישים וחמישה ימים, נשאר איפוא יום אחד שהוא \u0003יומא דכיפורי\u0004 \u0005[יום הכיפורים],\u0006 בו \u0003לית ליה רשותא לאסטוני\u0004 \u0005[אין לו רשות להסטין,\u0006 לקטרג\u0005].\u0006 שיום זה נעלה במדרגתו משאר ימים, ואין בו מקום לדברי האשמה של השטן.","\u0003בכל יום תורמין את המזבח\u0004 שמסירים ממנו מעט אפר (דשן) ומניחים אותו במזרחו של הכבש, כדי לקיים מצוות תרומת הדשן, והיו עושים זאת בזמן \u0003קריאת הגבר או סמוך לו\u0004 ואין מקפידים בדיוק בזמן \u0003בין לפניו בין לאחריו. וביום הכפורים\u0004 היו תורמים כבר \u0003מחצות\u0004 הלילה, \u0003וברגלים\u0004 כבר מן \u0003האשמורה הראשונה, ולא היתה קריאת הגבר מגעת\u0004 ברגלים \u0003עד שהיתה\u0004 ה\u0003עזרה מלאה מישראל\u0004 שהיו באים ומביאים עימם את שנדרו ונדבו במשך השנה לקרבן, כדי שיוכלו להקריבם מיד לאחר הקרבת התמיד.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת זבחים: \u0003אברים שפקעו\u0004 (שנפלו מתוך להט האש) \u0003מעל גבי המזבח;\u0004 אם נפלו \u0003קודם חצות\u0004 הלילה — \u0003יחזיר\u0004 אותם לאש, \u0003ומועלין בהן\u0004 שאם נהנה מהם בכלשהו, הריהו מועל בקודש, שאיברים אלה עומדים עדיין בקדושתם. אולם אם נפלו \u0003לאחר חצות — לא יחזיר\u0004 ושוב \u0003אין מועלין בהן,\u0004 והרי הם כאפר שנשרף.","שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שזמן חצות הלילה קובע, שהוא נידון כסוף זמן שריפת האברים והפיכתם לאפר? \u0003אמר רב: כתוב אחד אומר: \"כל הלילה והקטיר\"\u0004 כאמור: \"היא העולה על מוקדה על המזבח כל הלילה עד הבוקר\" (ויקרא ו, ב), משמע שכל הלילה הוא הזמן המיועד לשריפת איברי הקרבנות, \u0003וכתוב אחד אומר: \"כל הלילה... והרים\u0004 את הדשן\u0003\"\u0004 (ויקרא ו, ב-ג) משמע שניתן להרים את האפר כל הלילה! \u0003הא כיצד\u0004 תיישב את הכתובים? אלא \u0003חלקהו\u0004 את הלילה לשני חלקים \u0003חציו להקטרה\u0004 של האיברים, \u0003וחציו להרמה\u0004 של הדשן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב כהנא:\u0004 שנינו במשנתנו \u0003בכל יום תורמין את המזבח בקריאת הגבר או סמוך לו בין מלפניו בין מלאחריו, וביום הכפורים\u0004 היו תורמים כבר \u0003מחצות, וברגלים\u0004 כבר \u0003מאשמורה הראשונה,\u0004"],["\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי זמן תרומת הדשן \u0003מחצות דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא,\u0004 אם כן \u0003היכי מקדמינן והיכי מאחרינן\u0004 \u0005[כיצד מקדימים אנו וכיצד מאחרים אנו]\u0006 מן הזמן הקצוב בתורה?","\u0003אלא אמר ר' יוחנן:\u0004 לא מכאן למדים אלא \u0003ממשמע שנאמר\u0004 לענין הקטרת האיברים: \u0003\"כל הלילה\"\u0004 (ויקרא ו, ב) \u0003איני יודע שהיא עד הבקר? ומה\u0004 אם כן \u0003תלמוד לומר \"עד הבקר\"\u0004 (ויקרא ו, ב) כוונתו: \u0003תן בקר לבקרו של לילה,\u0004 כלומר: הקדם והשכם לפני בוא הבוקר, שאז זמן תרומת הדשן. אולם הקדמה זו לא נקבע לה שיעור מפורש בתורה, ונוהגים בזה לפי הצורך.","\u0003הלכך\u0004 (לכן), \u0003בכל יום תורמין את המזבח בקריאת הגבר או סמוך לו בין מלפניו בין מלאחריו,\u0004 שבקדימה קלה זו \u0003סגיא\u0004 \u0005[די],\u0006 \u0003ביום הכפורים דאיכא חולשא\u0004 \u0005[שיש חולשה]\u0006 של ה\u0003כהן גדול\u0004 שהרי עליו מוטלת כל עבודת היום, לכך מקדימים יותר ו\u0003עבדינן\u0004 \u0005[עושים אנו]\u0006 כבר \u0003מחצות. וברגלים דנפישי\u0004 \u0005[שמרובים]\u0006 \u0003ישראל\u0004 הבאים, \u0003ונפישי\u0004 \u0005[ומרובים]\u0006 ה\u0003קרבנות\u0004 שמביאים להקריב בחג, מקדימים יותר ו\u0003עבדינן\u0004 עוד \u0005[עושים אנו]\u0006 \u0003מאשמורת הראשונה. כדקתני טעמא\u0004 \u0005[כפי ששנינו את הטעם]\u0006 במשנתנו עצמה: \u0003לא היתה קריאת הגבר מגעת עד שהיתה עזרה מלאה מישראל.\u0004","במשנתנו הוזכרה קריאת הגבר כסימן לזמן מסויים, ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הביטוי: \u0003\"קריאת הגבר\"? רב אמר:\u0004 פירושו: \u0003קרא גברא\u0004 \u0005[האיש],\u0006 כלומר הכריז האיש הממונה על כך שעל הכהנים לעמוד לעבודתם. \u0003ר' שילא אמר\u0004 שתרגום הביטוי הוא: \u0003קרא תרנגולא\u0004 \u0005[התרנגול],\u0006 שאף הוא קרוי \"גבר\".","מסופר: \u0003רב איקלע לאתריה\u0004 \u0005[הזדמן למקומו]\u0006 של \u0003ר' שילא,\u0004 ור' שילא היה ידוע כחכם העיר, ואילו רב עדיין לא היה ידוע שם. \u0003לא הוה אמורא למיקם עליה\u0004 \u0005[לא היה מתורגמן שיעמוד לפני]\u0006 \u0003ר' שילא\u0004 ויתרגם את דבריו לקהל, \u0003קם\u0004 \u0005[עמד]\u0006 \u0003רב עליה\u0004 \u0005[עליו]\u0006 כמתורגמן, והזכיר ר' שילא בתוך דבריו את המושג \"קריאת הגבר\" \u0003וקא מפרש\u0004 \u0005[ופירש]\u0006 רב לקהל ואמר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש המושג: \u0003\"קריאת הגבר\" — קרא גברא\u0004 \u0005[האיש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שילא: ולימא מר: \"קרא תרנגולא\"\u0004 \u0005[שיאמר אדוני\u0006 פירוש הדבר: \u0005קרא התרנגול]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב, הפתגם העממי אומר: \u0003\"אבוב לחרי — זמר, לגרדאי — לא מקבלוה מיניה\u0004 \u0005[אבוב בשביל השרים הוא כלי זמר,\u0006 ואילו \u0005האורגים\u0006 הפחותים \u0005אינם מקבלים ממנו]\u0006\u0003\",\u0004 משום שבחוסר הבנתם אינם נהנים מנגינתו. אף ביאור זה שאמרתי, הרי שמעוהו לפניך שרים וגדולים ממך בתורה ונתקבל על דעתם, ואתה, שאינך גדול כמותם, אין הדבר מקובל עליך?","הלא \u0003כי הוה קאמינא עליה\u0004 \u0005[כאשר הייתי עומד לפני]\u0006 \u0003ר' חייא ומפרישנא\u0004 \u0005[הייתי מפרש]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003\"קריאת הגבר\" — קרא גברא\u0004 \u0005[האיש],\u0006 \u0003ולא אמר לי ולא מידי\u0004 \u0005[דבר]\u0006 \u0003ואת אמרת\u0004 \u0005[ואתה\u0006 ר' שילא \u0005אומר]\u0006 \u0003לי: אימא\u0004 \u0005[אמור]:\u0006 \u0003קרא תרנגולא\u0004 \u0005[התרנגול].\u0006 כיון ששמע ר' שילא דברים אלה, הבין מיהו המתורגמן הזה שלפניו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מר ניהו\u0004 \u0005[אדוני הוא]\u0006 \u0003רב? נינח מר\u0004 \u0005[שינוח אדוני]\u0006 והפסק מלתרגם, שאין זה כבודך שתהא לי כמסייע בלבד. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמרי אינשי\u0004 [\u0005אומרים בני אדם]\u0006 בפתגם: \u0003\"אי תגרת ליה\u0004 \u0005[אם נשכרת לו] —\u0006 \u0003פוץ עמריה\u0004 \u0005[נפץ צמרו]\u0006\u0003\",\u0004 שכיון שנשכר אדם לעבודה, עליו לעשות אף מלאכה בזויה. כלומר: אם הסכמת וקבלת על עצמך דבר — צריך אתה לעשות אותו בשלימות. \u0003איכא דאמרי, הכי אמר ליה\u0004 \u0005[יש אומרים\u0006 ש\u0005כך אמר לו]\u0006 לר' שילא: \u0003מעלין בקדש ולא מורידין,\u0004 וכיון שמלאכת המתורגמן נעשתה על ידי אדם גדול כמותי — אין ראוי שיבוא תחתי אחר בדרגה נמוכה ממני, ויהא בכך איפוא בזיון לתורה.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב, תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' שילא\u0004 בפירוש הביטוי הזה. ומפרטים: \u0003תניא כותיה\u0004 \u0005[שנויה כשיטתו]\u0006 של \u0003רב: גביני\u0004 ה\u0003כרוז\u0004 שהיה הממונה במקדש \u0003מה הוא אומר\u0004 בהכרזתו: \u0003\"עמדו כהנים לעבודתכם, ולוים לדוכנכם, וישראל למעמדכם\".\u0004 ומסופר: \u0003והיה קולו\u0004 רם כל כך, עד שהיה \u0003נשמע בשלש פרסאות\u0004 (שנים עשר מיל),","ו\u0003מעשה באגריפס המלך שהיה בא בדרך ושמע קולו\u0004 של גביני הכרוז במרחק \u0003שלש פרסאות, וכשבא\u0004 המלך \u0003לביתו שיגר לו\u0004 המלך \u0003מתנות\u0004 מתוך התפעלות מחוזק קולו. ומעירים \u0003ואף על פי כן\u0004 למרות קול רם ומשובח זה, קולו של ה\u0003כהן\u0004 ה\u0003גדול\u0004 היה רם ו\u0003משובח ממנו.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003וכבר\u0004 היה מקרה \u0003שאמר\u0004 כהן גדול בשעת וידויו על פרו ביום הכיפורים \u0003\"אנא השם\" ונשמע קולו ביריחו. ואמר רבה בר בר חנה אמר ר' יוחנן: מירושלים ליריחו\u0004 מרחק \u0003עשר פרסי\u0004 (ארבעים מיל).","ולא רק שהיה זה מרחק גדול יותר, אלא \u0003ואף על גב דהכא איכא חולשא, והכא ליכא חולשא\u0004 \u0005[ואף על פי שכאן\u0006 ביום הכיפורים \u0005יש חולשה\u0006 של הכהן הגדול הצם, \u0005וכאן\u0006 בשאר הלילות \u0005אין חולשה\u0006 לכרוז\u0005]\u0006 \u0003והכא יממא והתם ליליא\u0004 \u0005[וכאן\u0006 ביום הכיפורים אומר הכהן הגדול דבר זה \u0005ביום, וכאן\u0006 הכרוז מכריז \u0005בלילה]\u0006 והקול נשמע בלילה יותר,","וכמו ש\u0003אמר ר' לוי: מפני מה אין קולו של אדם נשמע ביום כדרך שנשמע בלילה — מפני\u0004 קולו של \u0003גלגל חמה\u0004 שכשמהלך ברקיע \u0003מנסר כחרש\u0004 (נגר) \u0003המנסר בארזים,\u0004 וקול זה מחריש קולות רבים אחרים. ומעירים: \u0003והאי חירגא דיומא\u0004 \u0005[וזוהי אותה נסורת של היום]\u0006 היא האבק הנראה לעינים כשהשמש מאירה מול חפצים ו\u0003\"לא\" שמיה\u0004 \u0005[שמו].\u0006 והוא ש\u0003אמר נבוכדנצר: \"וכל דיירי ארעא כלא חשיבין\"\u0004 \u0005[וכל דיירי הארץ כלא נחשבים]\u0006 (דניאל ד, לב) ופירוש הפסוק לפי זה: שהכל נחשבים כאבק הדק שכמעט אינו נראה לעין.","כיון שהוזכר מאמר זה בענין קולות, מביאים: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלמלא\u0004 קולו של \u0003גלגל חמה\u0004 היה \u0003נשמע קול המונה\u0004 (הרעש וההמיה) \u0003של\u0004 העיר \u0003רומי, ואלמלא קול המונה של רומי\u0004 היה \u0003נשמע\u0004 בעולם \u0003קול גלגל חמה.\u0004 ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין זה: \u0003שלש קולות הולכין מסוף העולם ועד סופו, ואלו הן: קול גלגל חמה, וקול המונה של רומי, וקול נשמה בשעה שיוצאה מן הגוף\u0004 שכל העולם היה צריך לשמוע אותם, \u0003ויש אומרים: אף\u0004 קול של \u0003לידה\u0004"],["\u0003ויש אומרים: אף רידייא\u0004 קול המלאך הממונה על השקיית האדמה, כשהוא קורא לשמים ולמעיינות תהום לתת ממימיהם להשקות את הארץ. ומעירים: \u0003ובעו רבנן רחמי\u0004 \u0005[ובקשו חכמים רחמים]\u0006 על קול זה של ה\u0003נשמה בשעה שיוצאה מן הגוף ובטלוה\u0004 \u0005[ובטלוהו]\u0006 שלא יישמע כל כך. על כל פנים מדברי הברייתא שהובאה נשמע כי קריאת הגבר, הכוונה להכרזת כרוז מיוחד, וכדברי רב.","\u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' שילא: היוצא לדרך\u0004 בחשיכה \u0003קודם קריאת הגבר\u0004 והרגוהו המזיקים — \u0003דמו בראשו\u0004 (עוון מיתתו חל על ראשו), לפי שהוא גרם דבר זה לעצמו. \u0003ר' יאשיה אומר:\u0004 איסור זה קיים \u0003עד שישנה\u0004 התרנגול ויקרא, \u0003ויש אומרים: עד שישלש. ובאיזה תרנגול אמרו — בתרנגול בינוני,\u0004 ומשמע מכאן כי קריאת הגבר — קריאת התרנגול היא.","\u0003אמר רב יהודה אמר רב: בשעה שישראל עולין לרגל,\u0004 הריהם \u0003עומדין צפופין ומשתחוים\u0004 בשעת הוידוי כשהם \u0003רווחים,\u0004 כדי שלא ישמע האחד את וידויו של חבירו, \u0003ונמשכין\u0004 מצד ריבוי הקהל עד \u0003אחת עשרה אמה אחורי בית הכפורת\u0004 (מקום קודש הקדשים). ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 מה פירושו של משפט זה? ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003אף על פי\u0004 שמרוב ריבוי הקהל אינם עומדים רק בצידה האחד של העזרה אלא \u0003נמשכין אחת עשרה אמה אחורי בית הכפורת, ועומדים צפופין,\u0004 בכל זאת \u0003כשהן משתחוין — משתחוין רווחים, וזה אחד מעשרה נסים שנעשו במקדש.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עשרה נסים נעשו בבית המקדש: לא הפילה אשה\u0004 הרה את עוברה \u0003מריח בשר הקדש,\u0004 שאשה הרה מתאוה למאכלים שונים, ופעמים שמגיעה על ידי כך לידי הפלה. \u0003ולא הסריח בשר הקדש מעולם. ולא נראה זבוב בבית המטבחים,\u0004 אף שדרכם של זבובים להיות במקום בו יש דם ובשר. \u0003ולא אירע קרי לכהן גדול ביום הכפורים. ולא נמצא פסול בעומר, ובשתי הלחם, ובלחם הפנים\u0004 שהם קרבנות ציבור. והיו ישראל \u0003עומדים צפופים, ומשתחוים רווחים. ולא הזיק נחש ועקרב בירושלים מעולם. ולא אמר אדם לחברו: צר לי המקום שאלין בירושלים.\u0004","על רשימה זו מעירים: \u0003פתח\u0004 בניסים שהיו \u0003במקדש, וסיים\u0004 בניסים שהיו \u0003בירושלים;\u0004 ואם כן לא היו במקדש עצמו עשרה ניסים! ומשיבים: \u0003איכא תרתי אחרנייתא\u0004 \u0005[יש שני\u0006 ניסים \u0005אחרים]\u0006 \u0003במקדש\u0004 ואלו הם: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעולם לא כבו גשמים אש של עצי המערכה,\u0004 אף על פי שהמזבח היה עומד בעזרה בלא גג. \u0003ועשן המערכה,\u0004 ו\u0003אפילו\u0004 כש\u0003כל הרוחות שבעולם באות ומנשבות בו — אין מזיזות אותו ממקומו,\u0004 אלא מיתמר ועולה למעלה.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר אין]\u0006 ניסים במקדש? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 כי \u0003רב שמעיה\u0004 דרש בעיר \u0003קלנבו: שברי כלי חרס\u0004 שבהם היו מבשלים את קרבנות קדשי הקדשים הנאכלים, וצריכים לשברם אחר כך מחמת שבלעו מן הקרבן ובחלוף זמנם נעשו נותר, היו הם \u0003נבלעין במקומן\u0004 ולא היו נזרקים, וכן \u0003אמר אביי: מוראה ונוצה\u0004 של עולות העוף \u0003ודישון\u0004 אפר \u0003מזבח\u0004 הפנימי, \u0003ודישון\u0004 אפר המנורה, שלא נאמר שמוציאים אותם לבית הדשן כאפר המזבח החיצון, היו \u0003נבלעין במקומן\u0004 בנס. הרי שהיו יותר מעשרה ניסים במקדש!","ומשיבים: \u0003פסולי תלתא הוו\u0004 \u0005[פסולים שלושה הם]\u0006 שהרי מנו שלא היה פסול בשלושה דברים — בעומר, ובשתי הלחם, ובלחם הפנים — \u0003חשבינהו כחד\u0004 \u0005[חשוב אותם כ\u0006נס \u0005אחד]\u0006 שלא נמצא פסול בקרבנות צבור, \u0003אפיק תרי ועייל תרי\u0004 \u0005[הוצא שנים והכנס שנים]\u0006 אלה, והרי הם בסך הכל עשרה ניסים. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה חושב ומצרף ניסים הדומים זה לזה, אם כן \u0003בלועין נמי תרי הוו\u0004 \u0005[גם כן שנים הם],\u0006 בליעת כלי החרס ובליעת המוראה ונוצה, ואם כן \u0003חשבינהו בחד חסרו להו \u0004 \u0005[חשוב\u0006 אף \u0005אותם כ\u0006נס \u0005אחד]\u0006 והרי חסר מן הרשימה! ומשיבים: \u0003איכא נמי אחריתי\u0004 \u0005[יש עוד אחר],\u0006 ש\u0003אמר ר' יהושע בן לוי: נס גדול היה נעשה בלחם הפנים\u0004 שבמקדש, שבשעת \u0003סלוקו\u0004 בסוף השבוע מהשולחן היה עדיין חם כבשעת \u0003סדורו, שנאמר: \"לשום לחם חם ביום הלקחו\"\u0004 (שמואל א' כא, ז), כלומר: אף ביום הלקחו היה עדיין חם.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 מעשי נס במקדש? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' לוי: דבר זה מסורת בידינו מאבותינו: מקום ארון\u0004 הברית עצמו בקודש הקדשים — \u0003אינו מן המדה,\u0004 כי לפי החשבון לא היה יכול להיכנס שם. שהרי מידת קודש הקדשים עשרים אמה על עשרים אמה (מלכים א, ו) ואמרו בברייתא כי בכל צד מצידי הארון היו עשר אמות אויר, שם עשרים אמה בלא מקום הארון עצמו, אלא נס היה בו כאילו לא תפס מקום כלל. \u0003ואמר רבנאי אמר שמואל: כרובים\u0004 שהיו על ארון הברית — \u0003בנס היו עומדין\u0004 ולא תפסו מקום, שהרי אורך כנפיהם עשרים אמה (ראה מלכים א, ו) כמדת חלל קודש הקדשים וזאת בלא לחשב את מדת גופם, הרי שהיו עוד ניסים במקדש!","ומשיבים: \u0003ניסי דבראי\u0004 \u0005[ניסים שמחוץ\u0006 לעזרה\u0005]\u0006 שהכל רואים \u0003— קחשיב\u0004 \u0005[מנה],\u0006 \u0003ניסי דגואי\u0004 \u0005[ניסים שבפנים\u0006 בקודש\u0005]\u0006 שאין הכל יכולים לראות — \u0003לא קחשיב\u0004 \u0005[מנה].\u0006 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003לחם הפנים נמי\u0004 \u0005[גם כן]\u0006 \u0003ניסי דגואי\u0004 \u0005[נסים של פנים]\u0006 \u0003הוא,\u0004 שהרי לחם הפנים היה בתוך ההיכל ואין הכל יכולים לראות זאת, ובכל זאת הדבר נמנה בין עשרת הניסים! ומשיבים: \u0003לחם הפנים ניסי דבראי\u0004 \u0005[נסים של חוץ]\u0006 \u0003הוא,\u0004 לפי ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \"ושמת אותם שתים מערכות שש המערכת \u0003על השלחן הטהר\u0004 לפני ה'\" (ויקרא כד, ו), ומתוך שהודגש בכתוב \u0003\"טהור\" — מכלל\u0004 \u0005[מכאן]\u0006 \u0003שהוא\u0004 יכול להיות גם \u0003טמא,\u0004"],["הלא \u0003כלי עץ העשוי לנחת הוא,\u0004 כלומר: כלי עץ שאין מטלטלין אותו והוא מונח במקום אחד, ושנינו: \u0003כלי עץ העשוי לנחת — אינו מקבל טומאה,\u0004 ולא עוד אלא \u0003שחוצץ בפני\u0004 ה\u0003טומאה. אלא מלמד\u0004 שהיו \u0003מגביהין אותו לעולי רגלים\u0004 כדי להראות להם את לחם הפנים \u0003ואומרים להם: ראו חיבתכם לפני המקום\u0004 שנעשה נס בלחם, שבשעת \u0003סילוקו\u0004 הריהו חם כבשעת \u0003סדורו, שנאמר: \"לשום לחם חם ביום הלקחו\"\u0004 (שמואל א, כא, ז), וכיון שהיה השולחן מיטלטל מזמן לזמן כאמור, שוב אינו נחשב ככלי עץ העשוי לנחת ולכך הריהו יכול לקבל טומאה. ולפי דרכנו למדנו שנס זה שבלחם היה מן הניסים שבחוץ, שהכל ראו אותם.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 ניסים אחרים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אושעיא: בשעה שבנה שלמה\u0004 את \u0003בית המקדש נטע בו כל מיני מגדים של זהב והיו מוציאין\u0004 אלה \u0003פירותיהן בזמנן\u0004 כשאר עצים, \u0003וכשהרוח מנשבת בהן נושרין, שנאמר: \"ירעש כלבנון פריו\"\u0004 (תהלים עב, טז), משמע שהיו צומחים פירות בלבנון, שהוא לדברי חכמים רמז למקדש. \u0003וכשנכנסו גוים להיכל יבש\u0004 אילן זה של זהב, שנאמר: \u0003\"ופרח לבנון אמלל\"\u0004 (נחום א, ד), \u0003ועתיד הקדוש ברוך הוא להחזירן\u0004 לישראל את האילנות הניסיים הללו, \u0003שנאמר: \"פרח תפרח ותגל אף גילת ורנן כבוד הלבנון נתן לה\"\u0004 (ישעיה לה, ב). הרי שהיו ניסים נוספים בבית המקדש.","ומשיבים: \u0003ניסי דקביעי\u0004 \u0005[ניסים שהיו קבועים]\u0006 ועומדים תמיד במקומם במקדש \u0003לא קא חשיב\u0004 \u0005[אינו מחשיב]\u0006 ולא מנאם בין הניסים. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך]\u0006 לתרץ באופן זה, אפשר להשתמש בו לתרץ קושיה קודמת: \u0003ארון וכרובים נמי, ניסי דקביעי נינהו\u0004 \u0005[גם כן, ניסים הקבועים\u0006 במקומם \u0005הם]\u0006 ולכן לא מנאום בין ניסי המקדש.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 במנין הניסים, כי על אף הרוחות העזות לא היה זז \u0003עשן המערכה\u0004 ממקומו, ושואלים: \u0003ומי הוה\u0004 \u0005[והאם היה]\u0006 בכלל \u0003עשן במערכה\u0004 שעל גבי המזבח? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה דברים נאמרו באש של מערכה: רבוצה\u0004 היתה על העצים כצורת \u0003ארי, וברה\u0004 (בהירה וצחה) היתה כאור \u0003חמה, ויש בה ממש,\u0004 כלומר: היה באש זו ממשות עד כדי שהיתה ניתנת למישוש, וחזקה היתה כל כך עד \u0003שאוכלת\u0004 (מעכלת, שורפת) עצים \u0003לחין כיבשין, ואינה מעלה עשן!\u0004","ומשיבים: \u0003כי קא אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ומשמע מדברינו כי היה עשן במערכה — הרי אנו מדברים על אש המערכה של ה\u0003הדיוט דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"ונתנו בני אהרן הכהן אש על המזבח\"\u0004 (ויקרא א, ז) ללמדנו: \u0003אף על פי שאש יורדת מן השמים,\u0004 בכל זאת יש \u0003מצוה\u0004 מיוחדת \u0003להביא\u0004 אף \u0003מן ההדיוט.\u0004 ואש זו שהביאו הכהנים היא שהיתה מעלה עשן, ובעשן זה אירע נס.","בין הדברים המיוחדים באש של מערכה (ר\"י הלבן) נאמר כי היתה האש \u0003רבוצה כארי.\u0004 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' חנינא סגן הכהנים: אני ראיתיה\u0004 את אש המערכה במקדש והיתה \u0003רבוצה ככלב\u0004 ולא כארי! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003כאן\u0004 שהיתה רבוצה כארי — הריהי אש המערכה של ה\u0003מקדש\u0004 ה\u0003ראשון, כאן\u0004 בדברי ר' חנינא סגן הכהנים שהיתה ככלב — הוא \u0003במקדש\u0004 ה\u0003שני.\u0004","על תירוץ זה מקשים: \u0003ובמקדש שני מי הואי\u0004 \u0005[האם היתה]\u0006 בכלל אש מערכה הבאה מן השמים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שמואל בר איניא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 במקדש שני: \"עלו ההר והבאתם עץ ובנו הבית \u0003וארצה בו ואכבד\u0004 אמר ה'\" (חגי א, ח), \"אכבד\" הוא הכתיב \u0003וקרינן\u0004 \u0005[ואנו קוראים]\u0006 אותה מלה \u0003\"ואכבדה\";\u0004 ומסבירים: \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע\u0005]\u0006 \u0003מחוסר ה\"א\u0004 במלה זו — ללמד: \u0003אלו חמשה דברים\u0004 (כמנין ה\"א) \u0003שהיו\u0004 הבדל \u0003בין מקדש ראשון למקדש שני\u0004 שהיו חסרים במקדש שני, \u0003ואלו הן: ארון\u0004 הברית, \u0003וכפורת\u0004 אשר עליו, \u0003וכרובים\u0004 שעל הכפורת, \u0003אש, ושכינה, ורוח הקודש, ואורים ותומים.\u0004 הרי שבמקדש שני לא היתה אש! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003אין, מיהוה הוה, סיועי לא מסייעא\u0004 \u0005[כן, היתה\u0006 במקדש שני \u0005אש\u0006 משמים, ואולם \u0005לא היתה מסייעת]\u0006 בשריפת הקרבנות, והיתה רק נראית על המערכה. כיון שהוזכרו דברים מיוחדים שהיו באש המערכה מביאים ברייתא בנושא קרוב. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שש אשות\u0004 (מיני אש) \u0003הן: יש\u0004 אש \u0003אוכלת ואינה שותה, יש\u0004 אש \u0003שותה ואינה אוכלת, יש\u0004 אש שהיא גם \u0003אוכלת\u0004 וגם \u0003שותה, יש\u0004 אש ה\u0003אוכלת\u0004 דברים \u0003לחין כיבשין\u0004 בלי הבדל, \u0003ויש אש דוחה אש\u0004 אחרת מפניה, \u0003ויש אש אוכלת אש\u0004 אחרת.","","ומפרטים: \u0003יש אש אוכלת ואינה שותה — הא דידן\u0004 \u0005[זו\u0006 האש \u0005שלנו]\u0006 האש הרגילה השורפת (אוכלת) דברים, אך אינה מייבשת נוזלים מעצמה. אש \u0003שותה ואינה אוכלת — אש\u0004 של \u0003חולין,\u0004 אש הקדחת, שהיא מייבשת את הנוזלים שבגוף, אבל אינה שורפת ממש, אש \u0003אוכלת ושותה\u0004 כמו האש של \u0003אליהו\u0004 הנביא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ותיפול אש ה' ותאכל את העולה ואת העצים ואת האבנים ואת העפר \u0003ואת המים אשר בתעלה לחכה\"\u0004 (מלכים א' יח, לח). אש \u0003אוכלת\u0004 דברים \u0003לחין כיבשין\u0004 — זו אש של \u0003המערכה. יש אש דוחה אש\u0004 זו האש של המלאך \u0003גבריאל,\u0004 שנאמר בדניאל שהמלאך העשוי אש ירד לכבשן האש שהושלכו בו חנניה מישאל ועזריה ודחה מפניו את אש הכבשן. \u0003ויש אש אוכלת אש\u0004 — היא אש ה\u0003שכינה,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 לענין אחר: הקדוש ברוך הוא \u0003הושיט\u0004 את \u0003אצבעו\u0004 בין המלאכים שאף הם עשויים אש \u0003ושרפן,\u0004 משמע שאש השכינה שורפת אף את אש המלאכים. ושואלים: והאם \u0003עשן המערכה אפילו כל רוחות שבעולם אין מזיזות אותו ממקומו? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק בר אבדימי: במוצאי יום טוב האחרון של חג\u0004 הסוכות \u0003הכל צופין לעשן המערכה,\u0004 אם היתה הרוח באה מכיוון דרום והיה העשן \u0003נוטה כלפי צפון,\u0004 היו ה\u0003עניים שמחין ובעלי בתים עצבין, מפני\u0004 שדבר זה סימן \u0003שגשמי שנה מרובין\u0004 ועתידה האדמה להצמיח תבואה רבה \u0003ופירותיהן מרקיבין\u0004 מפני הלחות ולכן לא ניתן לאכסן אותם ומוכרחים להקדים למוכרם, ונמצאים בעלי השדות מפסידים, ועניים מרויחים. ואם \u0003נטה\u0004 עמוד העשן \u0003כלפי דרום,\u0004 מפני רוח צפונית — \u0003עניים עצבין, ובעלי בתים שמחין מפני שגשמי\u0004 אותה \u0003שנה מועטין\u0004 ואין פירות רבים, ועוד ש\u0003פירותיהן משתמרין.\u0004","","ואם היתה רוח מערבית והיה העשן נוטה \u0003כלפי מזרח\u0004 — הרי זה סימן לכך שגשמי השנה יבואו כראוי ויהיו פירות, וניתן יהיה גם לאחסן אותם זמן מסויים ו\u0003הכל שמחין.\u0004 היתה רוח מזרחית ונוטה היה העשן \u0003כלפי מערב — הכל עצבין\u0004 שרוח מזרחית אינה מביאה גשמים, והרי זה סימן לכך שתהא זו שנת בצורת. הרי שהיתה הרוח מטה את עשן המערכה! ומשיבים: \u0003דאזיל ואתי כדיקלי, ואבדורי לא הוה מיבדר\u0004 \u0005[\u0006העשן \u0005היה הולך ובא,\u0006 מתנועע, \u0005כמו\u0006 עץ \u0005דקל\u0006 ברוח, \u0005אבל לא היה מתפזר].\u0006 שאכן היתה הרוח מטה את כיוון עשן המערכה, אך אינה מפזרת אותו לגמרי.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 כאן: אם היה עמוד העשן נוטה \u0003כלפי מזרח,\u0004 שנושבת רוח מערבית — \u0003הכל שמחין,\u0004 היה נוטה \u0003כלפי מערב\u0004 מפני הרוח מזרחית — \u0003הכל עצבין. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה ממקום אחר\u0005],\u0006 שאמרו חכמים: רוח \u0003מזרחית — לעולם יפה,\u0004 רוח \u0003מערבית — לעולם קשה, רוח צפונית — יפה לחטין בשעה\u0004 שכבר גדלו ו\u0003הביאו שליש, וקשה לזיתים בזמן שהן חונטין\u0004 (תחילת היותם לפירות), \u0003רוח דרומית — קשה לחטין בשעה שהביאו שליש, ויפה לזיתים בזמן שהן חונטין.\u0004","\u0003ואמר רב יוסף\u0004 על כך, \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003מר זוטרא: וסימניך\u0004 איזו רוח יפה לחיטים ואיזו לזיתים — שבמקדש היה \u0003שלחן בצפון, ומנורה בדרום.\u0004 ועל השלחן היו מניחין לחם העשוי מחיטים, ובמנורה היו מדליקין שמן העשוי מזיתים, \u0003האי מרבה דידיה\u0004 \u0005[\u0006צד \u0005זה\u0006 צפון \u0005מגדל את שלו]\u0006 את החיטים, השייכות לשלחן שבצפון, ו\u0003האי מרבה דידיה\u0004 \u0005[וזה\u0006 צד דרום \u0005מגדל את שלו]\u0006 את הזיתים שמהם מדליקים מנורה שבדרום. ועל כל פנים יש סתירה בהערכת רוח מזרחית ומערבית, אם טובה היא או רעה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003לן\u0004 \u0005[לנו]\u0006 לבני בבל, שאף שרוח מזרחית, רוח קדים יבשה היא, מכל מקום מתוך שבבל היא ארץ משופעת במים, אין אדמתה ממהרת להתייבש ואין הדבר פוגע באיכות התבואה, \u0003והא\u0004 \u0005[וזה] —\u0006 \u0003להו\u0004 לבני ארץ ישראל, שאינה משופעת במים והרוח המזרחית ממהרת ליבש את אדמתה ומקלקלת את התבואה.",""],["\u0003בראשונה\u0004 היה נהוג כי \u0003כל מי\u0004 מן הכהנים שהיה \u0003רוצה לתרום את המזבח\u0004 (להסיר ממנו את הדשן) — \u0003תורם. ובזמן\u0004 שהרוצים בכך \u0003הן מרובין\u0004 קובעים את הזכאי על ידי תחרות: \u0003רצין ועולים בכבש\u0004 העולה למזבח, \u0003כל\u0004 הממהר לרוץ ו\u0003קודם את חבירו\u0004 להכנס בתוך \u0003ארבע אמות\u0004 הסמוכות לראש המזבח — \u0003זכה\u0004 והוא התורם. \u0003ואם היו שניהן שוין —\u0004 לא זכה בכך אף אחד משניהם, אלא היה \u0003הממונה אומר להן\u0004 לכל הכהנים: \u0003הצביעו\u0004 (הוציאו אצבעות) והיה מפיל גורל ביניהם, וכאשר יבואר.","\u0003ומה הן מוציאין\u0004 בשעת הצבעה זו של הפייס — אצבע \u0003אחת או שתים, ואין מוציאין אגודל במקדש\u0004 שכהן שלפי חשבונו חסרים עוד שנים למניינו של הממונה כדי שהמנין יסתיים בו ויזכה הוא בגורל, היה מצביע באגודלו ובאצבע נוספת, ומתוך שניתן להרחיק את האגודל בנקל מן האצבע הסמוכה לו וליצור רושם כאילו היו אלו אצבעותיהם של שנים, הרי שבאופן פשוט ביותר היה כל כהן יכול להטות את תוצאות הגורל לטובתו, שלא כדין, ובשל כך לא היו מצביעים באגודל.","כך היה הנוהג מתחילה, אולם אירע \u0003מעשה שהיו שניהם\u0004 שני הכהנים שרצו בכך \u0003שוין\u0004 בזריזות, \u0003ורצין ועולין בכבש, ודחף אחד מהן את חבירו ונפל ונשברה רגלו. וכיון שראו בית דין שבאין לידי סכנה\u0004 על ידי תחרות זו \u0003התקינו\u0004 באותה שעה \u0003שלא יהו תורמין את המזבח אלא בפייס\u0004 (הגרלה). \u0003ארבע פייסות היו שם\u0004 במקדש בכל יום, כדי לקבוע מי הכהן הזוכה בכל עבודה, \u0003וזה הפייס הראשון\u0004 — לתרומת המזבח.","על הנוהג שהיה במקדש בראשונה שואלים: \u0003והא מעיקרא מאי טעמא לא תקינו לה רבנן פייסא\u0004 \u0005[וזו,\u0006 תרומת הדשן, \u0005מתחילה מה טעם לא תיקנו לה חכמים פייס]\u0006 כמו לשאר עבודות? ומשיבים: \u0003מעיקרא סבור\u0004 \u0005[מתחילה היו סבורים]:\u0006 \u0003כיון\u0004 ש\u0003עבודת לילה היא — לא חשיבא להו ולא אתו\u0004 \u0005[אינה חשובה להם\u0006 לכהנים \u0005ולא יבואו]\u0006 כהנים מרובים, ואין צורך לעשות פייס ביניהם. \u0003כיון דחזו דקאתו, ואתו\u0004 \u0005[כיון שראו שבאו, והגיעו]\u0006 \u0003לידי סכנה — תקינו לה פייסא\u0004 \u0005[התקינו לה פייס].\u0006","ומקשים: \u0003והרי\u0004 הקטרת \u0003איברים\u0004 של קרבן העולה \u0003ופדרים\u0004 (חלב) של שאר קרבנות ש\u0003עבודת לילה היא ותקינו\u0004 \u0005[והתקינו]\u0006 \u0003לה רבנן פייסא\u0004 \u0005[חכמים פייס]!\u0006 ומשיבים: הקטרה זו אינה עבודת לילה ממש, אלא \u0003סוף עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא.\u0004","על כך מקשים: אם כן \u0003האי נמי\u0004 \u0005[זו גם כן]\u0006 תרומת הדשן \u0003תחלת עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא,\u0004 ש\u0003אמר ר' יוחנן:\u0004 מי ש\u0003קידש\u0004 (רחץ) \u0003ידיו לתרומת הדשן, למחר\u0004 כלומר בשעות היום, אם לא יצא מתחום בית המקדש \u0003אין צריך לקדש\u0004 שוב, \u0003שכבר קידש מתחילת עבודה,\u0004 הרי שתרומת הדשן אף כי היא נעשית בלילה נחשבת תחילת עבודת היום!","על כן מתקנים את דברי ר' יוחנן: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 בנוסח זה: \u0003שכבר קידש מתחילה לעבודה\u0004 שאמנם התרומה שייכת לעבודת הלילה, אבל כיון שאין הפסק והכהן כבר קידש עצמו לעבודה במקדש הרי זה נחשב כדבר אחד.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שכך יש להסביר את טעמו של המנהג הראשון: \u0003מעיקרא סבור\u0004 \u0005[מתחילה סברו]\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003אונס שינה,\u0004 שקשה לכהנים להתעורר משנתם הרי ש\u0003לא אתו\u0004 \u0005[יבואו],\u0006 \u0003כיון דחזו דאתו, וקאתו נמי\u0004 \u0005[שראו שהם באים, ובאים גם כן]\u0006 \u0003לידי סכנה — תקינו\u0004 \u0005[התקינו]\u0006 \u0003לה רבנן פייסא\u0004 \u0005[חכמים פייס].\u0006 ומקשים: \u0003והרי\u0004 הקטרת \u0003איברים ופדרים, דאיכא\u0004 \u0005[שיש]\u0006 גם בכך \u0003אונס שינה\u0004 שהרי אף זו עבודת לילה, ובכל זאת \u0003תקינו\u0004 \u0005[התקינו]\u0006 \u0003לה רבנן פייסא\u0004 \u0005[חכמים פייס]\u0006 מתחילה! ומשיבים: \u0003שאני מיגנא ממיקם\u0004 \u0005[שונה שכיבה מקימה]\u0006 שאין זה קשה כל כך לאחר לשכב, אך קשה יותר להשכים לקום.","לעצם עניינה של המשנה תוהים: \u0003ותקנתא להך גיסא הואי\u0004 \u0005[וכי התקנה לצד זה היתה]\u0006 כלומר, וכי מפני התקלה האמורה תיקנו זאת? והלא יודעים אנו כי \u0003תקנתא להאי גיסא הואי\u0004 \u0005[תקנה לצד הזה\u0006 האחר \u0005היתה],\u0006 שכן היו עוד מלאכות חשובות שהיו צריכות להיעשות על ידי הכהנים ובשלהן היו צריכים לפייס זה! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שזכה בתרומת הדשן יזכה\u0004 עם זה גם \u0003בסידור המערכה\u0004 שעל המזבח ובהבאת \u0003שני גזירי עצים\u0004 שהיו מעלים למצוה בכל יום, ועבודות חשובות אלו ודאי שלא היו יכולות להתחלק אלא בפייס!","\u0003אמר רב אשי: שתי תקנות הוו\u0004 \u0005[היו]\u0006 כאן; \u0003מעיקרא סבור לא אתו\u0004 \u0005[מתחילה סברו\u0006 חכמים \u0005שלא יבואו]\u0006 כהנים מרובים, ולכן לא תיקנו פייס. \u0003כיון דחזו דקאתו ואתו נמי\u0004 \u0005[שראו שבאים, ובאים גם כן]\u0006 \u0003לידי סכנה — תקינו\u0004 \u0005[התקינו]\u0006 \u0003לה\u0004 חכמים \u0003פייסא\u0004 \u0005[פייס],\u0006 \u0003כיון דתקינו\u0004 \u0005[שהתקינו]\u0006 \u0003לה\u0004 לתרומת הדשן \u0003פייסא\u0004 \u0005[פייס] —\u0006 \u0003לא אתו\u0004 \u0005[היו באים],\u0006 \u0003אמרי\u0004 \u0005[\u0006ש\u0005היו אומרים]:\u0006 \u0003מי יימר דמתרמי לן\u0004 \u0005[מי יאמר שיזדמן לנו]\u0006 שנזכה בפיס זה? ולכן לא טרחו לבוא. \u0003הדר תקינו להו\u0004 \u0005[חזרו\u0006 ו\u0005תיקנו להם]\u0006 ש\u0003מי שזכה בתרומת הדשן יזכה בסידור מערכה ו\u0004בסידור \u0003שני גזירי עצים, כי היכי\u0004 \u0005[כדי]\u0006 בשל החשיבות הרבה שבכל העבודות הללו כאחד \u0003דניתו וניפייסו\u0004 \u0005[שיבואו ו\u0006ישתתפו \u0005בפייס].\u0006","שנינו במשנה שבתחילה \u0003בזמן שהן מרובין\u0004 היו רצים ועולים בכבש, והמקדים להגיע לארבע אמות זכה. \u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 \u0003לי\u0004 כי \u0003ארבע אמות\u0004 אלו \u0003דארעא\u0004 \u0005[של קרקע]\u0006 הסמוכות לכבש, ודאי ש\u0003לא\u0004 נחשבו לתחרות זו, כי \u0003רצין ועולין בכבש תנן\u0004 \u0005[שנינו]\u0006 ולא סמוך לכבש, \u0003קמייתא נמי\u0004 \u0005[\u0006אמות \u0005הראשונות\u0006 מעליהן \u0005גם כן]\u0006 \u0003לא,\u0004 שהרי \u0003רצין ועולין בכבש תנן\u0004 \u0005[שנינו]\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר \u0003כל הקודם את חבירו,\u0004 משמע שצריכים קודם לעלות בכבש ורק אז מתחילה התחרות.","האמות \u0003דביני ביני\u0004 \u0005[שבינתיים]\u0006 מארבע אמות ראשונות ולמעלה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא — דלא מסיימא מילתא\u0004 \u0005[ש\u0006כן \u0005אין הדבר מוגדר]\u0006 ואין סימן מובהק לדעת היכן מתחילות ארבע האמות הקובעות, ואם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 \u0003לי\u0004 שבארבע אמות \u0003דגבי\u0004 \u0005[שליד]\u0006 ה\u0003מזבח תנן\u0004 \u0005[שנינו]\u0006 שהמגיע אליהן ראשונה הוא הזוכה.","עד כאן בירר רב פפא את הדברים בעצמו, כהקדמה למה ש\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 שאלה זו: \u0003ארבע אמות שאמרו\u0004 שהן בארבע הסמוכות למזבח, האם מחשיבים אותן \u0003בהדיה\u0004 \u0005[ביחד]\u0006 עם \u0003אמה יסוד ואמה סובב\u0004 של המזבח, שהכבש ממשיך לעלות גם מעל אלה,"],["\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מאמה יסוד ואמה סובב\u0004 ששתי אמות אלה שבולט הכבש מעבר לתחום המזבח אינן נחשבות? לשאלה זו של רב פפא לא נמצאה תשובה, וסוכם כי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה ש\u0003אם היו שניהן שוין הממונה אומר להם הצביעו. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 פירוש \"הצביעו\" הוא: \u0003הוציאו אצבעותיכם למנין.\u0004 ושואלים: \u0003ונימנינהו לדידהו\u0004 \u0005[ושימנה אותם]\u0006 עצמם, ומדוע מונים את אצבעותיהם? ומשיבים: הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יצחק.\u0004 ש\u0003אמר ר' יצחק: אסור למנות את ישראל\u0004 עצמם \u0003ואפילו לדבר מצוה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויפקדם בבזק\u0004 ויהיו בני ישראל שלוש מאות אלף ואיש יהודה שלושים אלף\u0003\"\u0004 (שמואל א' יא, ח), כלומר: מנה אותם באמצעות שברי חרסים (\"בזק\") שנתן כל אחד מהם, ולא מנה אותם עצמם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ממאי דהאי \"בזק\" לישנא דמיבזק\u0004 \u0005[מנין ש\"בזק\" זה\u0006 שבכתוב \u0005לשון שבירה]\u0006 \u0003הוא? ודילמא שמא דמתא\u0004 \u0005[ושמא שם עיר]\u0006 \u0003הוא, כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"וימצאו את אדני בזק\u0004 בבזק\u0003\"\u0004 (שופטים א, ה) הרי שבזק שם מקום הוא! \u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 הראיה: נאמר: \u0003\"וישמע שאול את העם ויפקדם בטלאים\"\u0004 (שמואל א' טו, ד), הרי שלא מנה אותם אלא את הטלאים, שכל אחד נטל טלה מעדר המלך והעמידו במקומו.","\u0003אמר ר' אלעזר: כל המונה את ישראל עובר בלאו, שנאמר: \"והיה מספר בני ישראל כחול הים אשר לא ימד\"\u0004 (הושע ב, א) והמונה אותם עובר על \"לא ימד\". \u0003רב נחמן בר יצחק אמר: עובר בשני לאוין, ש\u0004הרי \u0003נאמר\u0004 באותו כתוב: \u0003\"לא ימד ולא יספר\"\u0004 (הושע ב, א).","\u0003אמר ר' שמואל בר נחמני, ר' יונתן רמי\u0004 \u0005[היה משליך,\u0006 מראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק: \u0003\"והיה מספר בני ישראל כחול הים\"\u0004 משמע שיש להם מספר, אף כי הוא מספר גדול מאוד, ומצד שני נאמר: \u0003\"אשר לא ימד ולא יספר\"\u0004 שאין להם מספר, הא כיצד?","ומתרץ: \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003כאן — בזמן שישראל עושין רצונו של מקום,\u0004 לא ימד כלל, \u0003כאן — בזמן שאין עושין רצונו של מקום,\u0004 שאז מספרם כחול הים. \u0003רבי אמר משום אבא יוסי בן דוסתאי\u0004 תירוץ אחר; \u0003לא קשיא\u0004 \u0005[קשה],\u0006 וכך יש ליישב: \u0003כאן — בידי אדם\u0004 לא ימד ולא יספר, \u0003כאן — בידי שמים,\u0004 הרי הם כחול הים.","\u0003אמר רב נהילאי בר אידי אמר שמואל: כיון שנתמנה אדם פרנס על הציבור\u0004 — הריהו \u0003מתעשר.\u0004 וראיה לדבר, \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]\u0006 בשאול: \u0003\"ויפקדם בבזק\"\u0004 כלומר, בשברי חרסים. \u0003ולבסוף כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויפקדם בטלאים\",\u0004 משמע שיכול היה לתת טלאים משלו כנגד מספרם של כל אותם האנשים. ושואלים: \u0003ודילמא מדידהו\u0004 \u0005[ושמא\u0006 נתנו הם טלאים אלה \u0005משלהם]?\u0006 ודוחים: \u0003אם כן, מאי רבותא דמילתא\u0004 \u0005[מה גדולתו של הדבר],\u0006 כלומר: מה טעם לספר שפקדם בטלאים? אלא ודאי הודיענו כאן בדרך אגב רוב עושרו של שאול.","כיון שהזכרנו פסוק זה, מפרשים גם את ההמשך. נאמר: \u0003\"ויבוא שאול עד עיר עמלק וירב בנחל\"\u0004 (שמואל א' טו, ה) \u0003אמר ר' מני:\u0004 עשה מריבה כביכול עם ה' \u0003על עסקי נחל.\u0004 כי \u0003בשעה שאמר לו הקדוש ברוך הוא לשאול:\u0004 \"עתה \u0003לך והכיתה את עמלק\u0004 והחרמתם את כל אשר לו ולא תחמול עליו והמתה מאיש עד אשה מעולל ועד יונק משור ועד שה מגמל ועד חמור\" (שמואל א' טו, ג) \u0003אמר\u0004 שאול: \u0003מה נפש אחת\u0004 שנרצחה ואין ידוע מי הרגה \u0003אמרה תורה הבא עגלה ערופה\u0004 שיש להביא עגלה ולערוף אותה בנחל, לכפר על העיר הקרובה אל החלל, עד שימצא הרוצח — \u0003כל הנפשות הללו\u0004 של העמלקים, \u0003על אחת כמה וכמה\u0004 שצריך לחוס עליהם.","ועוד: \u0003אם אדם חטא — בהמה מה חטאה\u0004 ומדוע צריכים להשמיד גם את בהמותיהם? \u0003ואם גדולים חטאו — קטנים מה חטאו? יצאה בת קול ואמרה לו: \"אל תהי צדיק הרבה\"\u0004 (קהלת ז, טז) ואל תהיה רחום יותר מהבורא עצמו, שאין זו צדקות אלא חולשה. לאחר מכן \u0003בשעה שאמר לו שאול לדואג: \"סב אתה ופגע בכהנים\u0004 ויסוב דואג האדומי ויפגע הוא בכהנים וימת ביום ההוא שמונים וחמישה איש נושא אפוד בד. ואת נוב עיר הכהנים הכה לפי חרב מאיש ועד אשה מעולל ועד יונק ושור וחמור ושה לפי חרב\u0003\"\u0004 (שמואל א' כב, יח-יט). \u0003יצאה בת קול ואמרה לו: \"אל תרשע הרבה\"\u0004 (קהלת ז, יז).","כיון שהוזכר שאול וחטאו \u0003אמר רב הונא: כמה לא חלי ולא מרגיש גברא דמריה סייעיה\u0004 \u0005[אינו חושש ואינו מרגיש אדם שאדונו,\u0006 הקדוש ברוך הוא, \u0005מסייע לו]\u0006 וראיה לדבר מדוד, \u0003שאול\u0004 נכשל בעבירה \u0003אחת ועלתה\u0004 (נחשבה) \u0003לו,\u0004 והורד מגדולתו. ואילו \u0003דוד\u0004 נכשל \u0003בשתים ולא עלתה לו\u0004 ונשאר בגדולתו. ושואלים: \u0003שאול באחת מאי\u0004 \u0005[מה]\u0006 \u0003היא — מעשה\u0004 של \u0003אגג\u0004 שלא עשה כמצוות ה' ולא הרגו. ואולם \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 עוד \u0003מעשה\u0004 של \u0003נוב עיר הכהנים!\u0004 ומשיבים: כבר אחר ה\u0003מעשה\u0004 של \u0003אגג כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"נחמתי כי המלכתי את שאול למלך\"\u0004 (שמואל א' טו, יא).","ואילו \u0003דוד\u0004 נכשל \u0003בשתים, מאי נינהו\u0004 \u0005[מה הם]\u0006 — מעשה שהרג את \u0003אוריה,\u0004 והענין של \u0003הסתה\u0004 שבסוף ימיו גרם למנות את ישראל ובשל כך מתו בדבר.","ומקשים: \u0003והא איכא נמי\u0004 \u0005[והרי יש גם כן]\u0006 \u0003מעשה של בת שבע,\u0004 שלקח אשת איש להיות לו אשה! ומשיבים: \u0003התם אפרעו מיניה\u0004 \u0005[שם נפרעו ממנו]\u0006 ולכן אין הדבר נחשב עוד בין עוונותיו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת הכבשה ישלם ארבעתים\"\u0004 (שמואל ב' יב, ו), וכך אכן עלתה לו, שתחת בת שבע (הכבשה שבמשל) נפגעו מבניו \u0003ילד\u0004 ראשון שנולד לבת שבע ומת, \u0003אמנון, תמר\u0004 שנאנסה, \u0003ואבשלום,\u0004 הרי ארבעה.","ושואלים: אם כן \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 במניית ישראל \u0003אפרעו מיניה\u0004 \u0005[נפרעו ממנו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתן ה' דבר בעם מהבקר ועד עת מועד\"\u0004 (שמואל ב' כד, טו)! ומשיבים: \u0003התם לא אפרעו מגופיה\u0004 \u0005[שם לא נפרעו מגופו]\u0006 אלא מישראל.","ומקשים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 במעשה בת שבע \u0003לא אפרעו מגופיה\u0004 \u0005[לא נפרעו מגופו]\u0006 אלא מבניו! ומשיבים \u0003לאיי\u0004 \u0005[לא כן]\u0006 \u0003אפרעו מגופיה\u0004 \u0005[נפרעו מגופו]\u0006 ש\u0003אמר רב יהודה אמר רב: ששה חדשים נצטרע דוד ופרשו הימנו\u0004 \u0005[ממנו]\u0006 \u0003סנהדרין\u0004 מתוך מחאה על התנהגותו, \u0003ונסתלקה הימנו\u0004 \u0005[ממנו]\u0006 ה\u0003שכינה, דכתיב\u0004 \u0005[שנאמר]\u0006 בתפילת דוד: \u0003\"ישובו לי יראיך וידעי עדתיך\"\u0004 (תהלים קיט, עט), ומתוך שביקש על שיבתם של יראי ה' ויודעי עדותיו, שהם חכמי הסנהדרין, משמע שפרשו ממנו. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 כמו כן: \u0003\"השיבה לי ששון ישעך\u0004 ורוח נדיבה תסמכני\u0003\"\u0004 (תהלים נא, יד), כלומר: ביקש שתשוב אליו רוח הקודש שנסתלקה ממנו.","ומקשים: וכי רק באלה נכשל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב: קבל דוד לשון הרע\u0004 על מפיבושת בן יהונתן מפי ציבא, שחשדו ששמח במפלתו, ואם כן חטא אף בכך! ומשיבים: אם כך יש לומר כדברי \u0003שמואל\u0004 ש\u0003אמר: לא קבל דוד לשון הרע,\u0004 אלא אכן אמת היה הדבר.","ומוסיפים: ולשיטת \u0003רב נמי\u0004 \u0005[גם כן]\u0006 תקשה \u0003שאמר קבל דוד לשון הרע — הא איפרעו מיניה\u0004 \u0005[הרי נפרעו ממנו]\u0006 בענין זה, שכן \u0003אמר רב יהודה אמר רב: בשעה שאמר לו דוד למפיבושת: \"אמרתי אתה וציבא תחלקו את השדה\"\u0004 (שמואל ב' יט, ל), \u0003יצאה בת קול ואמרה לו: \"רחבעם וירבעם יחלקו את המלכות\",\u0004 הרי שנענש על עבירה זו.","ועוד דנים בעניינם של שאול ודוד. נאמר: \u0003\"בן שנה שאול במלכו\"\u0004 (שמואל א' יג, א), ולכאורה, דבר זה תמוה! \u0003אמר רב הונא:\u0004 לומר שבשעה שמלך היה \u0003כבן שנה, שלא טעם טעם חטא\u0004 שהיה כשר וישר לגמרי.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הסברה זו \u0003רב נחמן בר יצחק: ואימא\u0004 \u0005[ואמור]\u0006 שכוונת הפסוק באומרו \u0003\"כבן שנה\", שמלוכלך בטיט ובצואה\u0004 תמיד? ומעירים: כי \u0003אחויאו ליה\u0004 \u0005[הראו לו]\u0006 \u0003לרב נחמן סיוטא בחלמיה\u0004 \u0005[פחדים בחלומו]\u0006 והבין שהוא עונש על שזלזל בשאול. \u0003אמר: נעניתי לכם עצמות שאול בן קיש\u0004 כלומר, מבקש אני מחילה מעצמות שאול על שפגעתי בו. \u0003הדר חזא סיוטא בחלמיה\u0004 \u0005[חזר וראה פחדים בחלומו]\u0006 והבין שלא ביקש סליחה בלשון מכובדת כראוי. וחזר ו\u0003אמר: נעניתי לכם עצמות שאול בן קיש מלך ישראל\u0004 ואז פסקו ממנו הפחדים בחלומותיו.","\u0003אמר רב יהודה אמר שמואל: מפני מה לא נמשכה מלכות בית שאול\u0004 לדורות רבים — \u0003מפני שלא היה בו שום דופי\u0004 של יוחסין, שהיה כשר מכל הצדדים, ש\u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק: אין מעמידין\u0004 (ממנים) \u0003פרנס על הציבור אלא אם כן קופה של שרצים\u0004 של פגמי יחוס \u0003תלויה לו מאחוריו.\u0004 ומדוע? \u0003שאם תזוח דעתו עליו\u0004 ויתגאה על הציבור \u0003אומרין לו: חזור\u0004 והבט \u0003לאחוריך\u0004 מאיזו משפחה אתה בא. ולכן דוד, שבא ממשפחה שהיו בה כמה פגמי יחוס (תמר, רות המואביה) נמשכה מלכותו ולא כן שאול.","\u0003אמר רב יהודה אמר רב: מפני מה נענש שאול\u0004 והגיע לידי עבירה — \u0003מפני ש\u0004מתחילה \u0003מחל על כבודו, שנאמר: \"ובני בליעל אמרו מה ישענו זה ויבזהו ולא הביאו לו מנחה ויהי כמחריש\"\u0004 (שמואל א' י, כז), ונאמר: \u0003\"ויעל נחש העמוני ויחן על יביש גלעד\"\u0004 (שמואל א' יא, א), שאילו היה תופס את המלוכה בתוקף לא היה נחש מעיז להתקיף את יושבי יבש, ונמצא שגרמה ענוותנותו למכשול.","\u0003ואמר ר' יוחנן משום\u0004 (משמו של) \u0003ר' שמעון בן יהוצדק: כל תלמיד חכם\u0004"],["\u0003שאינו נוקם ונוטר כנחש\u0004 על עלבון שהעליבו אותו — \u0003אינו\u0004 נחשב כ\u0003תלמיד חכם,\u0004 שכן ראוי לו לעשות לכבוד התורה ולומדיה. ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתורה במפורש איסור \u0003\"לא תקם ולא תטר\u0004 את בני עמך\u0003\"\u0004 (ויקרא יט, יח)! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005],\u0006 בענין חטא \u0003ממון הוא דכתיב\u0004 \u0005[שנאמר]\u0006 ולא בפגיעה אישית, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזו היא נקימה ואיזו היא נטירה? נקימה\u0004 מה היא — כגון ש\u0003אמר לו\u0004 לחבירו: \u0003השאילני מגלך,\u0004 ו\u0003אמר לו\u0004 חבירו: \u0003לאו\u0004 (לא). \u0003למחר אמר לו הוא\u0004 החבר שסרב לו: \u0003השאילני קרדומך! אמר לו:\u0004 הראשון \u0003איני משאילך, כדרך שלא השאלתני — זו היא נקימה.\u0004","\u0003ואיזו היא נטירה? אמר ליה\u0004 \u0005[לו]\u0006 לחבירו: \u0003השאילני קרדומך,\u0004 ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 החבר: \u0003לא. למחר אמר ליה\u0004 \u0005[לו]\u0006 אותו חבר: \u0003השאילני חלוקך! אמר לו: הילך\u0004 (הא לך), לפי ש\u0003איני כמותך שלא השאלתני. זו היא נטירה\u0004 שאינו עושה כמעשהו אך מכל מקום נוטר הוא לו בלבו ומזכיר לו את חטאו. ומכאן רואים שהדבר נאמר רק בדברים שבממון.","ומקשים: ובדברים שיש בהם משום \u0003צערא דגופא\u0004 \u0005[צער הגוף]\u0006 \u0003לא\u0004 נאמר שאסור לנקום? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנעלבין ואינן עולבין, שומעין חרפתן ואינן משיבין, עושין מאהבה ושמחין ביסורין — עליהן הכתוב אומר: \"ואהביו כצאת השמש בגברתו\"\u0004 (שופטים ה, לא). הרי שאף על עלבון שבגופו ראוי למחול!","ומשיבים: אכן, גם בענין צער הגוף יש איסור נקימה, ובתלמיד חכם מדובר \u0003לעולם\u0004 מדובר כאן \u0003דנקיט ליה בליביה\u0004 \u0005[שהוא שומר לו בלבו]\u0006 טינה, אף שאינו נוקם בו או מזכיר לו חטאיו. ומקשים עוד: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: כל המעביר על מדותיו\u0004 (המוחל על עלבונו) \u0003מעבירין לו\u0004 (סולחים לו) \u0003על כל פשעיו!\u0004 ומשיבים: אכן, גם תלמיד חכם שנעלב צריך למחול, אך זהו דווקא במקרה \u0003דמפייסו ליה ומפייס\u0004 \u0005[שמפייסים אותו ומתפייס],\u0006 אך אם לא פייסוהו, ראוי לו לתלמיד חכם שלא ימחול, משום כבוד התורה.","במשנה נתבאר כי לצורך עריכת הפייס היה הממונה אומר לכהנים להוציא אצבעות, ונוקב במספר גדול ומתחילים למנות בכהן שלסימן נטלו ממנו את מצנפתו. \u0003מה הן\u0004 הכהנים היו \u0003מוציאין\u0004 — אצבע \u0003אחת או שתים.\u0004 ושואלים \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאמרת \u0003שתים מוציאין, אחת מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שמוציאים?","\u0003אמר רב חסדא: לא קשיא\u0004 \u0005[קשה];\u0006 כך יש להבין: \u0003כאן — ב\u0004אדם \u0003בריא\u0004 היכול להוציא אצבע אחת בלא השניה, \u0003כאן — בחולה\u0004 שקשה לו לכוין ולהוציא אצבע אחת בלבד. \u0003והתניא\u0004 \u0005[וכן שנינו\u0006 בברייתא\u0005]:\u0006 אצבע \u0003אחת — מוציאין, שתים — אין מוציאין. במה דברים אמורים — בבריא, אבל בחולה — אפילו שתים מוציאין.\u0004 וחולים היושבים או שוכבים בפינה משלהם \u0003יחידין\u0004 — \u0003מוציאין שתים, ואין מונין להם אלא\u0004 אצבע \u0003אחת\u0004 בלבד.","ומקשים: והמוציא שתים האם במציאות \u0003אין מונין לו אלא אחת? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מוציאין לא שליש\u0004 (אצבע שלישית) \u0003ולא גודל\u0004 (אגודל) \u0003מפני הרמאים\u0004 — שמא כשיראה שהמנין מתקרב אליו יכניס או יוציא את אגודלו כדי שסוף הספירה תהא בו. \u0003ואם הוציא שליש — מונין לו\u0004 אף אצבע שלישית זו, שכיון שכשמוציא שלוש אצבעות כאחת אינו יכול להרחיקן זו מזו, אין הדבר נראה כרמאות. הוציא \u0003גודל — אין מונין לו, ולא עוד אלא\u0004 מי שהוציא גודל \u0003לוקה מן הממונה בפקיע.\u0004","הרי שאם הוציא יותר מאצבע אחת — נמנים לו כל האצבעות שהוציא! ומשיבים: מכאן אין קושיה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מונין לו נמי\u0004 \u0005[גם כן]\u0006 \u0003אחת,\u0004 שאם הוציא שלוש אצבעות מונים אותן רק כמספר אחד.","הוזכר כאן הלוקה בפקיע, ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הוא \u0003פקיע? אמר רב:\u0004 זהו \u0003מדרא.\u0004 אף מילה זו לא היתה מובנת וידועה במשך הדורות, ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מדרא? אמר רב פפא: מטרקא דטייעי דפסיק רישיה\u0004 \u0005[שוט של ערבים שראשו קצוץ,\u0006 ומפוצל לרצועות דקות יותר\u0005]\u0006 והוא הפקיע שבו היו מלקים.","אגב כך \u0003אמר אביי: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 כי \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003\"בן ביבאי ממונה על הפקיע\", אמינא\u0004 \u0005[אמרתי]\u0006 שפירושו הוא שהיה ממונה על עשיית \u0003פתילתא\u0004 \u0005[פתילות].\u0006 \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מבלאי מכנסי הכהנים ומהמייניהן\u0004 (ומהאבנטים שלהם), \u0003מהן היו מפקיעין\u0004 (מתירים ופורמים) \u0003ובהן היו\u0004 עושים פתילות שבהן היו \u0003מדליקין\u0004 האורות שבשמחת בית השואבה. \u0003כיון דשמענא להא דתניא\u0004 \u0005[ששמעתי את זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ולא עוד אלא שלוקה מן הממונה בפקיע, אמינא\u0004 \u0005[אומר אני]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003פקיע — נגדא\u0004 \u0005[מלקות],\u0006 שבן ביבאי היה הממונה על עונשי הגוף במקדש.","שנינו במשנה \u0003מעשה שהיו שניהן שוין ורצין ועולין בכבש.\u0004 ודחף אחד את חברו ונשברה רגלו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מעשה בשני כהנים שהיו שניהן שוין\u0004 במרוצם, \u0003ורצין ועולין בכבש, קדם אחד מהן לתוך ארבע אמות של חבירו\u0004 ומתוך כעס \u0003נטל סכין ותקע לו בלבו.\u0004","\u0003עמד ר' צדוק על מעלות האולם, ואמר: אחינו בית ישראל שמעו! הרי הוא אומר \"כי ימצא חלל...\u0004 לא נודע מי הכהו... \u0003ויצאו זקניך ושפטיך\u0004 ומדדו אל הערים אשר סביבות החלל\u0003\"\u0004 (דברים כא, א-ב) וזקני העיר הסמוכה למקום מציאת החלל היו צריכים להביא עגלה ערופה. \u0003אנו,\u0004 כלומר: במקרה שלנו \u0003על מי להביא עגלה ערופה?\u0004 ומשל מי תלקח? האם חובה זו מוטלת \u0003על העיר\u0004 וחכמיה הם שיביאו, \u0003או\u0004 שחובה היא \u0003על העזרות\u0004 ועל הכהנים להביאה? \u0003געו\u0004 (פרצו) \u0003כל העם בבכיה\u0004 מחמת הצער.","\u0003בא אביו של תינוק\u0004 של אותו כהן צעיר שנדקר \u0003ומצאו כשהוא מפרפר\u0004 עדיין. \u0003אמר: הרי הוא כפרתכם\u0004 לכשימות, אבל \u0003עדיין בני מפרפר\u0004 ולא מת, ומשום כך \u0003לא נטמאה סכין.\u0004 והעירו בתוספתא: \u0003ללמדך שקשה\u0004 היתה \u0003עליהם טהרת כלים יותר משפיכות דמים.\u0004 שהרי אפילו אביו של הבן שנדקר למות, דאג יותר שהסכין לא תטמא, מאשר לעצם העובדה שנהרג שם בנו. \u0003וכן הוא אומר: \"וגם דם נקי שפך מנשה הרבה מאד עד אשר מלא את ירושלים פה לפה\"\u0004 (מלכים ב' כא, טז) ולא שמו ליבם עוד לשפיכות דמים.","תחילה שואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003מעשה קדים\u0004 \u0005[קדם]\u0006 זה ששנינו במשנה או זה שבתוספתא? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שקדם מעשה זה שהיתה בו \u0003שפיכות דמים, השתא\u0004 \u0005[עכשיו]\u0006 נמצא כי בשל מעשה שהיתה בו \u0003שפיכות דמים לא תקינו פייסא\u0004 \u0005[תיקנו פייס]\u0006 והמשיכו לעשות תחרות כמו קודם, על מעשה זה ש\u0003נשברה רגלו תקינו\u0004 \u0005[התקינו]?!\u0006 אלא ודאי צריך לומר שהמעשה שבמהלך התחרות \u0003נשברה רגלו\u0004 של אחד הכהנים \u0003קדים\u0004 \u0005[קדם].\u0006","ושואלים: אם כן הוא, שביטלו את התחרות מיד לאחר המעשה הראשון ותיקנו תמורתו פייס, \u0003כיון דתקינו פייסא\u0004 \u0005[שתיקנו פייס],\u0006 כל אותו מעשה שהיו רצים בתוך \u0003ארבע אמות מאי עבידתייהו\u0004 \u0005[מה מעשיהם]?\u0006 שהרי שוב לא היה מקום לתחרות זו! \u0003אלא\u0004 יש לחזור למה שאמרו, \u0003לעולם\u0004 יש לומר כי המעשה של \u0003שפיכות דמים קדים\u0004 \u0005[קודם]\u0006 היה, אלא \u0003מעיקרא סבור אקראי בעלמא\u0004 \u0005[מתחילה סברו\u0006 כי \u0005מקרה בלבד]\u0006 \u0003הוא,\u0004 שודאי אין זה מצוי שיגיעו לידי שפיכות דמים, ולא קבעו בגלל אפשרות רחוקה כזאת תקנה גמורה בדבר. \u0003כיון דחזי אפילו ממילא אתו\u0004 \u0005[שראו שאפילו בדרך כלל באים]\u0006 הם \u0003לידי סכנה,\u0004 שהרי אחר נדחף והופל — \u0003תקינו רבנן פייסא\u0004 \u0005[תקנו חכמים פייס].\u0006","לאחר ביאור נקודה זו, מבארים כמה פרטים במעשה שסופר בתוספתא: מסופר כי \u0003עמד ר' צדוק על מעלות האולם ואמר: \"אחינו בית ישראל שמעו: הרי הוא אומר: \"כי ימצא חלל באדמה\", אנן\u0004 \u0005[אנו]\u0006 \u0003על מי להביא\u0004 עגלה \u0003על העיר או על העזרות\"?\u0004 ותוהים: וכי \u0003ירושלים בת אתויי\u0004 \u0005[שייכת להביא]\u0006 \u0003עגלה ערופה היא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשרה דברים נאמרו בירושלים\u0004 שאינה כשאר כל ערי ישראל, \u0003וזו אחת מהן:\u0004"],["\u0003אינה מביאה עגלה ערופה\u0004 כי הלכה זו נאמרה רק בעיר שהיא נחלת שבט מסויים מישראל, ואילו ירושלים לא נתחלקה לשבטים, ושייכת לכל ישראל. ועוד: הלא \u0003\"לא נודע מי הכהו\" כתיב\u0004 \u0005[נאמר]\u0006 (דברים כא, א), לומר כי עיקר דין עגלה ערופה הוא כאשר נמצא חלל ואין ידוע מי הרגו \u0003והא\u0004 \u0005[והרי]\u0006 זה שנדקר על הכבש \u0003נודע מי הכהו! אלא\u0004 יש לומר שר' צדוק לא נתכוון כלל להלכה זו עצמה של עגלה ערופה, אלא \u0003כדי להרבות בבכיה\u0004 וכדי להדגיש את הזעזוע שבמאורע אמר מה שאמר.","נאמר בתוספתא: \u0003בא אביו של תינוק ומצאו כשהוא מפרפר, אמר: הרי הוא כפרתכם\u0004 לכשימות אבל \u0003עדיין בני קיים\u0004 ולכך אין הסכין בה נדקר טמאה. והוסיפו שם: \u0003ללמדך שקשה עליהם טהרת כלים יותר משפיכות דמים. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: האם יש להבין מהערה זו כי \u0003שפיכות דמים הוא דזל\u0004 \u0005[ש\u0006נעשתה \u0005מזולזלת],\u0006 \u0003אבל טהרת כלים כדקיימא קיימא\u0004 \u0005[כפי שעמדה היא עומדת]\u0006 ולא נתכוונו לומר שהקפידו יותר מדי בטהרת כלים, אלא שזלזלו בשפיכות דמים. \u0003או דילמא\u0004 \u0005[או שמא]\u0006 \u0003שפיכות דמים כדקיימא קיימא\u0004 \u0005[כפי שעמדה היא עומדת]\u0006 \u0003אבל טהרת כלים היא דחמירא\u0004 \u0005[שחמורה]\u0006 היתה עליהם יותר מכראוי?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר, \u0003מדקא נסיב לה תלמודא\u0004 \u0005[כיון שהוא מביא את הלימוד]\u0006 מן הכתוב: \u0003\"וגם דם נקי שפך מנשה\" שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהתכוון לומר כי \u0003שפיכות דמים הוא דזל\u0004 \u0005[ש\u0006נעשתה \u0005מזולזלת]\u0006 \u0003וטהרת כלים כדקיימא קיימא\u0004 \u0005[כפי שעמדה היא עומדת].\u0006","מכאן שבים לעיקר המצוה של תרומת הדשן ועניינים הקשורים בה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר לאחר מצות תרומת הדשן: \u0003\"ופשט\u0004 את בגדיו \u0003ולבש בגדים אחרים והוציא את הדשן\u0004 אל מחוץ למחנה אל מקום טהור\u0003\"\u0004 (ויקרא ו, ד), \u0003שומעני\u0004 (לומד אני) מכאן לכאורה שהחלפת בגדים זו היא מצוה מיוחדת בתורה \u0003כדרך יום הכפורים\u0004 שהכהן הגדול מחליף בגדי זהב בבגדי לבן, ואף כאן \u0003שפושט בגדי קודש ולובש בגדי חול,\u0004","\u0003תלמוד לומר: \"ופשט את בגדיו ולבש בגדים אחרים\" — מקיש\u0004 \u0005[משוה]\u0006 הכתוב \u0003בגדים שלובש לבגדים שפושט, מה להלן\u0004 אלה שפושט \u0003בגדי קודש\u0004 הם, שהרי עשה בהם מצות תרומת הדשן, \u0003אף כאן\u0004 בגדים שמשמשים להוצאת הדשן מן המחנה \u0003בגדי קודש.\u0004","\u0003אם כן מה תלמוד לומר \"\u0004בגדים \u0003אחרים\"?\u0004 כוונתו לומר: \u0003פחותין מהן\u0004 בטיב. \u0003ר' אליעזר אומר:\u0004 נאמר: \u0003\"אחרים והוציא\" לימד על הכהנים בעלי מומין\u0004 שהם \"אחרים\", שאינם ראויים לשאר עבודות הקודש, \u0003שכשרין להוציא\u0004 את \u0003הדשן,\u0004 שהוא לומד מן הכתובים שכהנים שאינם עושים עבודות אחרות הם העושים מלאכה זו.","ומעתה מפרשים את הברייתא, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: בגדים \u0003אחרים פחותין מהן,\u0004 ומעירים הרי זה \u0003כדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בגדים שבשל בהן\u0004 אדם \u0003קדרה לרבו\u0004 שנתלכלכו על ידי כך \u0003לא ימזוג בהן כוס לרבו\u0004 שהוא שירות מכובד וחשוב, וכן הוצאת הדשן לא תיעשה בבגדים המשובחים השייכים לעבודות אחרות. מלשון הברייתא לא נתברר היטב מהו היקף המחלוקת שבין התנא הראשון ור' אליעזר.","\u0003אמר ריש לקיש כמחלוקת בהוצאה\u0004 של הדשן שר' אליעזר מתיר לעשותה על ידי בעלי מומין, \u0003כך מחלוקת בהרמה\u0004 שלדעת ר' אליעזר אף בעלי מומים כשרים בה. ואילו \u0003ר' יוחנן אמר: מחלוקת\u0004 זו אינה אלא \u0003בהוצאה\u0004 של הדשן, \u0003אבל בהרמה — דברי הכל עבודה היא,\u0004 ואינה כשרה בבעלי מומים.","ומסבירים \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ריש לקיש — אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: אי סלקא דעתך\u0004 \u0005[אם עולה בדעתך לומר]\u0006 כי הרמת הדשן \u0003עבודה היא,\u0004 וכי \u0003יש לך עבודה שכשירה בשני כלים\u0004 בכתונת ומכנסים בלבד? והרי בתיאור בגדי הכהן הנחוצים להוצאת הדשן נאמר רק: \"ולבש הכהן מידו בד ומכנסי בד ילבש על בשרו והרים את הדשן\" (ויקרא ו, ג).","\u0003ור' יוחנן\u0004 מסביר: כדי שלא תאמר שנעשית ההוצאה בבגדי חול שלו, לכך \u0003גלי רחמנא\u0004 \u0005[גלתה התורה]\u0006 שצריך \u0003בכתונת ומכנסים\u0004 שהם בגדי קודש כדין כל עבודה אחרת, ומאחר שגילתה התורה עיקרון זה אם כן \u0003הוא הדין\u0004 לשנים האחרים \u0003למצנפת ואבנט.\u0004","ושואלים: ולדעת ר' יוחנן \u0003ומאי שנא הני\u0004 \u0005[מדוע שונים אלה]\u0006 שדווקא אותם הזכיר הכתוב במפורש? ומשיבים: כי לדעתו הוזכרו אלה משום שיש ללמוד מהם הלכות מיוחדות. מה שנאמר: \u0003\"מדו בד\"\u0004 הריהו ללמד שתהא הכתונת \u0003כמדתו\u0004 המדוייקת של הכהן דווקא. ומה שנתפרשו: \u0003\"מכנסי בד\" —\u0004 הרי זה בא \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין זה: \u0003מנין שלא יהא דבר קודם\u0004 בלבישת בגדי כהונה \u0003למכנסים, שנאמר: \"ומכנסי בד ילבש על בשרו\"\u0004 (ויקרא ו, ג) כלומר, על בשרו ממש, שצריכים המכנסים להיות תחילה.","ושואלים: \u0003וריש לקיש\u0004 שלדעתו נכתבו שנים אלה בדווקא, מנין אם כן למד הוא הלכות מקובלות אלה? ומשיבים: שהוא למד את ההלכות מדיוק לשון הכתובים. כיצד? ענין \u0003מדו\u0004 שתהא הכתונת \u0003כמדתו\u0004 לומד הוא \u0003מדאפקיה רחמנא\u0004 \u0005[ממה שהוציאה,\u0006 ביטאה, \u0005התורה]\u0006 חובת לבישת כתונת \u0003בלשון \"מדו\".\u0004 ואת ההלכה \u0003שלא יהא דבר קודם למכנסים\u0004 מן ההדגשה שבכתוב \u0003\"על בשרו\" נפקא\u0004 \u0005[יוצא\u0006 נלמד הדבר\u0005]\u0006 לדעתו.","ומעירים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שמחלוקת זו היא \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו כבר בנושא זה. שכן שנינו בברייתא: \"ומכנסי בד ילבש על בשרו\" (ויקרא ו, ג) מאחר שכבר נאמר \u0003\"על בשרו\" —\u0004 ודאי בלבישה מדבר הכתוב, ואם כן \u0003מה תלמוד לומר \"ילבש\"?\u0004 אלא הרי זה בא \u0003להביא\u0004 (להוסיף) שצריך ללבוש גם \u0003מצנפת ואבנט\u0004 לצורך מצוות \u0003הרמה,\u0004 אלה \u0003דברי ר' יהודה.\u0004","\u0003ר' דוסא אומר:\u0004 ריבוי לשון זה \"ילבש\" בא \u0003לרבות בגדי כהן גדול ביום הכפורים\u0004 שהם בגדי לבן כבגדי כהן הדיוט, שהן \u0003כשירין\u0004 אחר כך לעבודה \u0003לכהן הדיוט,\u0004 ואינם צריכים גניזה לאחר שאין הכהן הגדול יכול ללובשם בשנית לעבודת יום הכיפורים לשנה אחרת.","\u0003אמר רבי: שתי תשובות בדבר\u0004 לדחות רעיון זה, \u0003חדא\u0004 \u0005[אחת\u0006 מהן\u0005]:\u0006 משום ש\u0003אבנטו של כהן גדול\u0004 ביום הכיפורים עשוי פשתן בלבד ו\u0003לא זהו אבנטו של כהן הדיוט\u0004 שאבנט זה עשוי לדעתו כלאים, צמר ופשתים יחד. \u0003ועוד:\u0004 וכי \u0003בגדים שנשתמשת בהן קדושה חמורה\u0004 של כהן גדול \u0003תשתמש בהן קדושה קלה\u0004 של כהן הדיוט?! \u0003אלא מה תלמוד לומר\u0004 מן הריבוי \u0003\"ילבש\" —\u0004"],["\u0003לרבות את השחקים\u0004 בגדים שחוקים במקצת, שכשרים לעבודה כל עוד אינם קרועים.","ועוד לענין מחלוקת זו: בשימוש בבגדי כהן גדול נאמר: \u0003\"\u0004ובא אהרן אל אהל מועד ופשט את בגדי הבד אשר לבש בבואו אל הקודש \u0003והניחם שם\"\u0004 (ויקרא טז, כג), פסוק זה \u0003מלמד\u0004 שבגדי הכהן הגדול \u0003טעונין גניזה\u0004 שאין להשתמש בהם שוב. \u0003ר' דוסא אומר\u0004 (כשיטתו): אף ששוב אינם ראויים לכהן גדול, מכל מקום עדיין \u0003ראוין הן לכהן הדיוט, ומה תלמוד לומר: \"והניחם שם\",\u0004 שלכאורה משמע מכאן שאינם משמשים עוד — \u0003שלא ישתמש בהן\u0004 הכהן הגדול עצמו ב\u0003יום הכפורים אחר\u0004 לעבודה בקודש הקדשים. עתה חוזרים לענייננו בדבר בגדי כהונה בהוצאת הדשן.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003בהא קמיפלגי\u0004 \u0005[בענין זה חלוקים]\u0006 ר' יהודה ור' דוסא, \u0003דמר\u0004 \u0005[שחכם זה],\u0006 ר' יהודה, שלדעתו פרט לכתונת ומכנסים שנאמרו בפסוק במפורש, צריך הכהן ללבוש גם מצנפת ואבנט, \u0003סבר:\u0004 כי \u0003עבודה היא\u0004 ולכן צריכה ארבעה בגדים ולשם כך צריך הוא את הייתור של \"ילבש\" \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' דוסא, שלדעתו אינו צריך ללבוש מצנפת ואבנט, \u0003סבר:\u0004 כי \u0003לאו עבודה היא\u0004 ודיה בשנים המפורשים, ו\"ילבש\" מלמדנו הלכה אחרת.","את ההנחה הזו דוחים: אפשר לומר \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עבודה\u0004 גמורה \u0003היא, והכא בהא קמיפלגי\u0004 \u0005[וכאן בענין זה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה],\u0006 ר' יהודה, \u0003סבר:\u0004 כי \u0003צריכא קרא לרבויי\u0004 \u0005[צריכה פסוק\u0006 מיוחד \u0005לרבות]\u0006 מצנפת ואבנט, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' דוסא, \u0003סבר: לא צריכא קרא לרבויי\u0004 \u0005[אינה זקוקה לפסוק\u0006 מיוחד כדי \u0005לרבות]\u0006 והדבר מובן מאליו, שאין עבודה נעשית אלא בכל בגדי כהונה ואין צורך בהדגשה מיוחדת.","\u0003בעי ר' אבין: תרומת הדשן\u0004 שיעורה \u0003בכמה?\u0004 מהו השיעור שיש להרים מן הדשן כדי לצאת ידי מצוות הרמה? האם \u0003מתרומת מעשר ילפינן לה\u0004 \u0005[לומדים אנו אותה]\u0006 ולכך יש להרים כמותה אחד ממאה, \u0003או מתרומת\u0004 מלקוח השבי ששבו ב\u0003מדין\u0004 (במדבר ל״א:כ״ו) \u0003ילפינן לה\u0004 \u0005[לומדים אנו אותה]\u0006 שהיא אחד מחמש מאות? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: נאמר כאן: \"והרים\u0004 את הדשן\u0003\"\u0004 (ויקרא ו, ג) \u0003ונאמר להלן\u0004 במנחה: \u0003\"והרים\u0004 ממנו בקומצו מסולת המנחה\u0003\"\u0004 (ויקרא ו, ח) \u0003מה להלן\u0004 מרים \u0003בקומצו — אף כאן\u0004 מרים \u0003בקומצו.\u0004 ששיעור הרמה הינו קבוע ואינו ניטל כאחוז מסויים מכמות הדשן שעל גבי המזבח.","ב\u0003אמר רב:\u0004 אף שכל עבודות הקודש שהיו במקדש, אסור לזר (מי שאינו כהן) לעשות אותן, מכל מקום רק \u0003ארבע עבודות\u0004 מהן, \u0003זר\u0004 שעשה אותן \u0003חייב עליהן מיתה\u0004 בידי שמים. ואלו הן: \u0003זריקה\u0004 של הדם, \u0003והקטרה\u0004 של קטורת ואיברים \u0003וניסוך המים\u0004 בחג הסוכות \u0003וניסוך היין\u0004 על המזבח. \u0003ולוי אמר: אף תרומת הדשן. וכן תנא\u0004 \u0005[שנה]\u0006 \u0003לוי במתניתיה\u0004 \u0005[בקובץ המשניות שלו]:\u0006 \u0003אף תרומת הדשן.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רב —\u0004 שנאמר: \u0003\"ואתה ובניך אתך תשמרו את כהנתכם לכל דבר המזבח ולמבית לפרכת ועבדתם עבדת מתנה אתן את כהנתכם והזר הקרב יומת\"\u0004 (במדבר יח, ז) וכך הוא למד: \u0003\"עבודת מתנה\"\u0004 — עבודה שיש בה נתינה \u0003ולא עבודת סילוק,\u0004 ולכן תרומת הדשן אינה בכלל. \u0003\"ועבדתם\"\u0004 נדרש כמו עבד-תם \u0003עבודה תמה\u0004 גמורה ומשלימה כמו זריקה, \u0003ולא עבודה שיש אחריה עבודה\u0004 אחרת כמו שחיטה וקבלת הדם והולכתו.","\u0003ולוי\u0004 סבור — כי \u0003רבי רחמנא\u0004 \u0005[ריבתה התורה]\u0006 ממה שנאמר: \u0003\"לכל דבר המזבח\",\u0004 ללמד שכל עבודה שעושים על המזבח חשובה היא, ואסורה איסור מיתה לזר, ובכלל זה גם תרומת הדשן. ושואלים: \u0003ורב\u0004 מה לומד הוא מ\"לכל דבר המזבח\"? ומשיבים: כי לדעתו \u0003ההוא\u0004 \u0005[אותו]\u0006 ביטוי בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003שבע הזאות שבפנים\u0004 שמזה הכהן מפר העלם דבר של ציבור ומפר כהן המשיח ומפר יום הכיפורים על פרוכת קודש הקדשים, ושבע הזאות \u0003שבמצורע\u0004 שיהא הזר חייב עליהן אף שאינן על המזבח.","ושואלים: \u0003ולוי\u0004 מהיכן למד הוא הלכות אלה? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 למד\u0005]\u0006 מריבוי הכתוב שהרי נאמר: \u0003\"דבר\u0004 המזבח \u0003\"\u0004ומלשון הריבוי \u0003\"וכל דבר\"\u0004 למד הוא גם את אלה. ושואלים: \u0003ורב\u0004 מה לומד הוא מכאן? ומשיבים: כי הוא את הריבוי \u0003\"דבר\" \"וכל דבר\" לא דריש\u0004 \u0005[אינו דורש]\u0006 ואינו מוצא שיש ללמוד משינוי זה לימוד מיוחד.","ומקשים על לוי: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכך יש ללמוד את הכתוב: \u0003\"לכל דבר המזבח\"\u0004 — הרי זה \u0003כלל, \"עבודת מתנה\"\u0004 — הרי הוא \u0003פרט,\u0004 אם כן לפנינו \u0003כלל ופרט.\u0004 ולפי כללי מדרש ההלכה \u0003אין בכלל אלא מה שבפרט,\u0004 ויש ללמוד מכאן: \u0003עבודת מתנה — אין\u0004 \u0005[כן],\u0006 \u0003עבודת סילוק — לא,\u0004 וקשה אם כן לדעת לוי! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006"],["\u0003\"ולמבית לפרכת ועבדתם\"\u0004 (במדבר יח, ז), וכוונתו: בעבודת הקודש שעושים \u0003אל מבית לפרוכת\u0004 בקודש הקדשים, ביום הכיפורים הוא שיש לחלק ולומר שחייבים רק על \u0003עבודת מתנה ולא עבודת סילוק,\u0004 כגון הוצאת הכף ומחתה של הקטורת שהיה הכהן הגדול מכניס לקודש הקדשים ביום הכיפורים\u0003. הא\u0004 \u0005[הרי]\u0006 מה שעושים \u0003בחוץ, אפילו עבודת סילוק\u0004 חייבים עליה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, אם כן \u0003\"ועבדתם\"\u0004 שלמדת מכך שרק על עבודה תמה, זו שעושה סיום \u0003—\u0004 חייבים, אם כן \u0003נמי\u0004 \u0005[גם כן]\u0006 תפרש שהוא מתייחס רק \u0003\"אל מבית לפרוכת\"\u0004 שהחובה על הזר היא רק אם עשה \u0003עבודה תמה, ולא עבודה שיש אחריה עבודה\u0004 אחרת המשלימה אותה, שאם עשה עבודה כזו — אינו חייב מיתה. \u0003הא\u0004 \u0005[הרי]\u0006 בעבודות שבחוץ, \u0003אפילו עבודה שיש אחריה עבודה\u0004 תיחשב כעבודת קודש שחייב הזר עליה מיתה!","ומשיבים: \u0003\"ועבדתם\"\u0004 שנאמר בתוספת ו' החיבור \u0003הדר ערביה קרא\u0004 \u0005[חזר וערבו הכתוב]\u0006 לומר שלענין זה דין עבודת חוץ כדין עבודת פנים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 על פי שיטת לוי: \u0003עבודת סילוק\u0004 הנעשית \u0003בהיכל,\u0004 כגון דישון המזבח הפנימי ודישון המנורה, \u0003מהו\u0004 (מה דינה)? האם \u0003לפנים מדמינן ליה\u0004 \u0005[מדמים אנו אותה]\u0006 ואינה נחשבת כעבודת קודש לענין זה, שהרי הן נחשבות כ\"עבודה תמה\", שהרי אין לאחריהן כלום, \u0003או\u0004 שמא לעבודת \u0003חוץ מדמינן ליה\u0004 \u0005[מדמים אנו אותה]?\u0006","\u0003הדר פשטא\u0004 \u0005[חזר\u0006 הוא בעצמו \u0005ופתר\u0006 את הבעיה\u0005]:\u0006 אילו נאמר רק \u0003\"מבית\"\u0004 הייתי מבין רק בעבודות הנעשות בקודש הקדשים, כיון שכתוב גם \u0003\"ולמבית לפרוכת\"\u0004 בתוספת ו' הרי זה בא להוסיף.","ושואלים: \u0003אלא מעתה\u0004 שעל עבודה תמה חייבים גם בהיכל, \u0003זר שסידר את השלחן\u0004 של לחם הפנים \u0003ליחייב\u0004 \u0005[שיהיה חייב]!\u0006 ומשיבים: הטעם שאינו חייב הוא משום שאין זו עבודה תמה, כי \u0003איכא\u0004 \u0005[יש]\u0006 אחריה עדיין \u0003סידור בזיכין\u0004 (של לבונה על הלחם). ומקשים: אם כן זר ש\u0003סידר בזיכין\u0004 במקדש \u0003ליחייב\u0004 \u0005[שיהיה חייב]!\u0006 ודוחים: \u0003איכא\u0004 \u0005[יש]\u0006 עדיין עבודה של \u0003סילוק\u0004 הבזיכין משם, שהיא בעצם גמר עבודת לחם הפנים \u0003והקטרה,\u0004 וכיון שכך אין סידור הבזיכין נחשבת כעבודה תמה.","ושואלים עוד: \u0003זר שסידר את המנורה ליחייב\u0004 \u0005[שיהיה חייב]!\u0006 ודוחים: אין זו עבודה תמה, כי \u0003איכא\u0004 \u0005[יש\u0006 עדיין\u0005]\u0006 \u0003נתינת פתילה\u0004 במנורה. ומקשים: אם כן נתן \u0003פתילה — ליחייב,\u0004 \u0005[שיתחייב]!\u0006 ומשיבים: אף זו אינה סוף עבודה, כי \u0003איכא\u0004 \u0005[יש\u0006 עדיין\u0005]\u0006 \u0003נתינת שמן.\u0004","ומקשים: \u0003נתן שמן ליחייב\u0004 \u0005[שיתחייב]!\u0006 ומשיבים: אף זו אינה עבודה גמורה, כי \u0003איכא\u0004 \u0005[יש\u0006 עוד\u0005]\u0006 את עבודת ה\u0003הדלקה.\u0004 ומקשים: אם כן זר ש\u0003הדליק\u0004 את הנרות \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 על כך! ועונים: \u0003הדלקה לאו\u0004 \u0005[אינה\u0006 נחשבת\u0005]\u0006 \u0003עבודה,\u0004 משום שאין בה מעשה של ממש בגוף המנורה.","ושואלים: \u0003ולא\u0004 (וכי אין זו עבודה)? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"ונתנו בני אהרן הכהן אש על המזבח וערכו עצים על האש\"\u0004 (ויקרא א, ז), \u0003לימד על הצתת אליתא\u0004 \u0005[קיסם]\u0006 שבו מדליקים את אש המזבח, \u0003שלא תהא אלא בכהן כשר, ובכלי שרת!\u0004 הרי שאף ההדלקה נחשבת כעבודה! ומשיבים: \u0003הצתת אליתא\u0004 \u0005[קיסם]\u0006 — \u0003עבודה\u0004 חשובה \u0003היא,\u0004 שעושים מעשה בקיסם זה, אבל ה\u0003הדלקה\u0004 עצמה \u0003לאו עבודה היא.\u0004","ומוסיפים לשאול: \u0003אלא מעתה זר שסידר את המערכה\u0004 שעל המזבח \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 שהרי זו עבודת מתנה! ומשיבים: אין זו עבודה תמה, כי \u0003איכא\u0004 \u0005[יש]\u0006 עדיין \u0003סידור שני גזירי עצים\u0004 שמניחים למצוה בכל יום, והם באים אחר כך. ושואלים: אם כן, זר ש\u0003סידר שני גזירין\u0004 של עצים \u0003ליחייב\u0004 \u0005[שיתחייב]!\u0006 ומשיבים: \u0003איכא\u0004 \u0005[יש\u0006 עדיין\u0005]\u0006 \u0003סידור אברים\u0004 על האש שבא לאחר מכן.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: זר שסידר שני גזירי עצים חייב,\u0004 משמע שעבודה גמורה היא! ומשיבים: אכן, \u0003בהא פליגי\u0004 \u0005[בענין זה חלוקים]\u0006 רב ור' יוחנן; \u0003מר\u0004 \u0005[חכם זה],\u0006 ר' יוחנן, \u0003סבר:\u0004 כי סידור שני גזירי עצים \u0003עבודה תמה היא,\u0004 עבודה גמורה שאין עוד אחריה עבודה ממינה. \u0003ומר\u0004 \u0005[וחכם זה],\u0006 רב, \u0003סבר: לאו עבודה תמה היא,\u0004 ואינה מסתיימת אלא בסידור האיברים על העצים.","לגוף המחלוקת שהוזכרה תחילה מעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב, תניא כוותיה\u0004 \u0005[\u0006ו\u0005שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003לוי. תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב: עבודות שזר חייב עליהם מיתה,\u0004 אלו הן: \u0003זריקת דם בין לפנים\u0004 במזבח הזהב או על הפרוכת \u0003בין לפני ולפנים\u0004 שנעשית ביום הכיפורים בין בדי הארון בקודש הקדשים. \u0003והמזה\u0004 את הדם של \u0003חטאת העוף, והממצה\u0004 את דם עולת העוף על קיר המזבח כדינה, \u0003והמקטיר\u0004 את \u0003עולת העוף\u0004 על המזבח, \u0003והמנסך שלשה לוגין מים,\u0004 או \u0003שלשה לוגין יין\u0004 על המזבח. ולא מנה תרומת הדשן ביניהן.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003לוי: עבודות שזר חייב עליהן מיתה\u0004 אלו הן: \u0003המרים את הדשן, ושבע הזאות שבפנים\u0004 בקודש הקדשים, והזאות \u0003שבמצורע,\u0004 וכן \u0003המעלה\u0004 (מקטיר) \u0003על גבי המזבח בין דבר כשר בין דבר פסול.\u0004","עתה חוזרים לפירוש דברי המשנה. ושואלים: \u0003למה מפיסין?\u0004 על שאלה זו תוהים: \u0003למה מפיסין?!\u0004 הלא התשובה היא \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 כדי שלא יבואו לידי קטטה! ומסבירים: \u0003אלא\u0004 כך יש להבין את השאלה: \u0003למה מפיסין וחוזרין ומפיסין\u0004 ארבע פעמים ביום, שיתכנסו פעם אחת בלבד ויפיסו על כל העבודות בכינוס זה!","\u0003אמר ר' יוחנן: כדי להרגיש\u0004 (להרעיש) ברעש המתכנסים את \u0003כל העזרה, שנאמר: \"אשר יחדו נמתיק סוד בבית אלהים נהלך ברגש\"\u0004 (תהלים נה, טו), ללמדנו שיש צורך להרגיש ולעשות פומבי לעבודת הקודש ולהכנות לה וזהו מכבוד המקדש.","ושואלים: \u0003במה מפיסין,\u0004 מה היו בגדי הכהנים המשתתפים בפייס? \u0003רב נחמן אמר:\u0004 שהכהנים היו לבושים אז \u0003בבגדי חול, ורב ששת אמר:\u0004 שהיו לבושים \u0003בבגדי קדש.\u0004","ומסבירים את שיטותיהם; \u0003רב נחמן אמר: בבגדי חול, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שעושים זאת \u0003בבגדי קדש,\u0004 הלא \u0003איכא\u0004 \u0005[יש]\u0006 \u0003בעלי זרועות\u0004 תקיפים וחזקים, \u0003דחמסי ועבדי\u0004 \u0005[שחומסים ועושים\u0006 עבודה\u0005]\u0006 אף שלא זכו בגורל, שהרי הם לבושים כבר וראויים לעבודה. \u0003רב ששת אמר:\u0004 עושים זאת \u0003בבגדי קדש. דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שיעשו זאת \u0003בבגדי חול, אגב חביבותיה מיקרו ועבדי\u0004 \u0005[מתוך חביבותה\u0006 של העבודה להם \u0005יזדמן שיעשו\u0006 עבודה\u0005]\u0006 בבגדי חול שעליהם, ופוסלים איפוא את עבודתם.","\u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מסרון\u0004 את הכהנים \u0003לחזנין\u0004 (שמשין) \u0003והיו מפשיטין אותן את בגדיהן, ולא היו מניחין עליהן אלא מכנסים בלבד.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא\u0006 מדובר\u0005]\u0006 \u0003באותן שזכו לפייס\u0004 שמסופר כיצד היו פושטים מהם בגדי חול ומלבישים אותם בגדי כהונה. \u0003אמר רב הונא בר יהודה אמר רב ששת\u0004 לדחות ראיה זו: \u0003לא,\u0004 אפשר לפרש שהיו כולם לבושים בבגדי קודש ומדובר דווקא \u0003באותן שלא זכו לפייס\u0004 וכאן מבארים כיצד היו פושטים מהם את בגדי הכהונה שלבשו בשעת הפייס.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר כדברי רב ששת בהסבר זה. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 שמדובר \u0003באותן שזכו לפייס\u0004 ומבואר כיצד הפשיטום בגדי חול והלבישום בגדי קודש, כיצד אם כן נאמר שם: \u0003\"לא היו מניחין עליהן אלא מכנסים בלבד\"?\u0004 שמזה משמע כי היו מלבישים אותם בגדי קודש על בגדי החול ואחר כך בעודם לובשים את בגדי הקודש היו פושטים את מכנסי החול וחוזרים ולובשים את של קודש, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מניין שלא יהא דבר קודם למכנסים\u0004 בלבישת בגדי כהונה — \u0003תלמוד לומר: \"ומכנסי בד יהיו על בשרו\"\u0004 (ויקרא טז, ד), ומכאן משמע שבשעת לבישת מכנסי הקודש, היו הם לבושים כבר בבגדי הקודש!","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 רב נחמן, מה עונה הוא על קושיה זו? ומסבירים כי לדעתו \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה]\u0006 \u0003הכי קתני\u0004 \u0005[כך שנה,\u0006 כך ראוי להבין\u0005]:\u0006 \u0003עד שעודן עליהן בגדי חול מלבישין אותן מכנסי קדש, והיו מפשיטין אותן בגדי חול ולא היו מניחין אלא מכנסים בלבד\u0004 מבגדי הקודש, ואם כן אין ראיה גמורה לדבר.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר אני\u0006 את שיטתי \u0005זו]\u0006 שבבגדי קודש היו עושים את הפייס — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לשכת הגזית כמין בסילקי\u0004 (אולם גדול של ארמון) \u0003גדולה היתה, הפייס\u0004 היה נערך \u0003במזרחה\u0004 של הלשכה, \u0003וזקן\u0004 (חכם) מבית הדין היה \u0003יושב במערבה\u0004 להורות ולדון להם בכל מקרה של ספק. \u0003והכהנים מוקפין ועומדין\u0004 במעגל \u0003כמין בכוליאר\u0004 (צמיד), \u0003והממונה בא ונוטל מצנפת מראשו של אחד מהן, ויודעין שממנו\u0004 ה\u0003פייס מתחיל\u0004 וממנו מתחילים בספירה. ומעתה \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר\u0005]\u0006 שבשעת הפייס היו הכהנים לבושים \u0003בבגדי חול,\u0004 אם כן \u0003מצנפת בבגדי חול מי איכא\u0004 \u0005[האם ישנה]:\u0006 והלא היא מיוחדת רק לבגדי כהונה, ואם כן מכאן ראיה שהיו לבושים בבגדי קודש.","ודוחים: \u0003אין\u0004 \u0005[כן]\u0006 יש מצנפת בבגדי חול, כיצד — \u0003כדתני\u0004 \u0005[כפי ששנה]\u0006 \u0003רב יהודה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב שמואל בר יהודה: כהן שעשתה לו אמו כתונת\u0004 משלה כעין כתונת כהונה, מתוך חיבת בנה וחיבת המצוה \u0003עובד בה\u0004 הבן \u0003עבודת יחיד\u0004 אבל לא יקריב בה קרבנות הצבור. ואם כן יתכן שיהיו לכהנים מצנפות של חול שהיו כעין בגדי כהונה.","אגב הזכרת הברייתא בענין הפייס \u0003אמר אביי: שמע מינה\u0004 \u0005[למד ממנה]\u0006 מאותה ברייתא כי \u0003לשכת הגזית\u0004 היתה בנויה \u0003חציה בקדש\u0004 (בתוך העזרה) \u0003וחציה בחול\u0004 (בהר הבית), \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 גם כן כי \u0003שני פתחים היו לה\u0004 ללשכה זו \u0003אחד פתוח בקדש, ואחד פתוח בחול.\u0004 והוא מסביר דבריו: \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 כי לשכת הגזית \u0003כולה בקדש\u0004 — כיצד זה אמרו כי \u0003זקן יושב במערבה? והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003אין\u0004 רשות \u0003ישיבה בעזרה אלא למלכי בית דוד בלבד.\u0004 ואם הזקן יושב שם משמע שלא היה זה תחום הקודש.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 להיפך, כי לשכה זו \u0003כולה בחול\u0004 היא, אם כן איך עושים \u0003פייס במזרחה? והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 לקיים את הכתוב: \u0003\"בבית אלהים נהלך ברגש\"\u0004 (תהלים נה, טו) שממנו נלמד כי לכבוד המקדש היו כל המשתתפים בפייס עומדים בהיכל, כדי שישמע בו רעש, ואם היה הפייס נעשה בחול הרי \u0003ליכא\u0004 \u0005[אין\u0006 כאן\u0005],\u0006 שהרי אין זה בית אלוהים, המקדש עצמו, כי אם הר הבית. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לישכה זו \u0003חציה בקדש וחציה בחול.\u0004","ועוד: \u0003אי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003פתח אחד\u0004 בלבד \u0003יש לה\u0004 ללשכה זו \u0003ופתוח לקדש\u0004 כיצד אם כן היה \u0003זקן יושב במערבה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלשכות הבנויות בחול\u0004 בשטח הר הבית אבל \u0003פתוחות לקדש\u0004 לעזרה \u0003— תוכן קודש\u0004 כקדשות העזרה אף שהן עצמן בהר הבית שדינו חול. ומצד שני \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שהיה לה פתח אחד בלבד שהיה \u0003פתוח לחול\u0004 אם כן כיצד עושים \u0003פייס במזרחה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 לשכות \u0003בנויות בקדש ופתוחות לחול\u0004 אף על פי שהן עצמן בקודש — \u0003תוכן חול. אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 כי \u0003שני פתחים היו לה, אחד פתוח בקדש ואחד פתוח לחול.\u0004","\u0003הפייס השני\u0004 שהיו עושים בין הכהנים בכל יום היה: \u0003מי שוחט\u0004 את קרבן התמיד של שחרית, \u0003מי זורק\u0004 את דמו, \u0003מי מדשן מזבח הפנימי\u0004 מאפרו, \u0003ומי מדשן\u0004 (מוציא את האפר והפתילות החרוכות) \u0003את המנורה, ומי מעלה אברים\u0004 של קרבן התמיד \u0003לכבש\u0004 שליד המזבח כדי להקטירם אחר כך.","וכך היו מחלקים את האיברים להעלותם: \u0003הראש והרגל\u0004 הימנית מעלה כהן אחד, \u0003ושתי הידים\u0004 (הרגלים הקדמיות) היה מעלה כהן שני, את \u0003העוקץ\u0004 חוליות השדרה האחרונות והאליה \u0003והרגל\u0004 השמאלית היה מעלה כהן שלישי, \u0003והחזה והגרה\u0004 (הצואר) ומקצת איברים פנימיים המחוברים אליו, כגון: הקנה והכבד והלב והחזה היו מועלים על ידי כהן רביעי, \u0003ושתי הדפנות\u0004 (הצלעות) על ידי כהן חמישי, \u0003והקרבים\u0004 בכהן שישי. \u0003והסולת\u0004 של מנחת קרבן התמיד בכהן שביעי, \u0003והחביתין\u0004 (מנחה שהיה מביא הכהן הגדול בכל יום) בכהן שמיני, \u0003והיין\u0004 בכהן תשיעי. ובסך הכל \u0003שלשה עשר כהנים זכו בו\u0004 בפייס זה, תשעת הכהנים המעלים את התמיד והנספח לו, וארבעה שעסקו בשחיטה זריקה דישון המזבח ודישון המנורה.","\u0003אמר בן עזאי לפני ר' עקיבא משום\u0004 (משמו של) \u0003ר' יהושע:\u0004 לא כך היו מעלים את התמיד אלא \u0003דרך הלוכו\u0004 בחייו \u0003היה קרב\u0004 על המזבח ולא כסדר שאמרנו. וכאשר יבואר בסוגיית הגמרא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003כשהן מפיסין\u0004 (עושין את הפייס) האם \u0003לעבודה אחת\u0004 בלבד הן \u0003מפייסין,\u0004 כגון לשחיטת התמיד, ושאר שתים עשרה העבודות האחרות שנמנו במשנה היו מתחלקות בין הכהנים העומדים לצידו, לפי סדר עמידתם, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לכל עבודה ועבודה\u0004 משלוש עשרה העבודות האמורות, בנפרד \u0003הן מפייסין?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003ארבע פייסות היו שם. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003לכל עבודה\u0004 בנפרד \u0003הן מפייסין\u0004 — אם כן \u0003טובא הוו\u0004 \u0005[הרבה\u0006 פייסות \u0005היו]\u0006 ובודאי יותר מארבעה! \u0003אמר רב נחמן בר יצחק:\u0004 מכאן אין ראיה, כי אפשר לומר ש\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ארבע פעמים\u0004 היו הכהנים \u0003נכנסין\u0004 ומתקבצים כדי \u0003להפיס, ולכל חדא וחדא\u0004 \u0005[אחת ואחת,\u0006 פעם ופעם\u0005]\u0006 \u0003היו בה טובא\u0004 \u0005[הרבה]\u0006 \u0003פייסות,\u0004 לכל עבודה לחוד."],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר; ממה ששנינו: \u0003ר' יהודה אומר:\u0004 כשעשו פייס לקטורת, אף על פי שהיו צריכים לעבודה זו שני כהנים, האחד שהיה מוליך את הקטורת להקטרה בהיכל והשני שהיה חותה גחלים מהמזבח החיצון והיה מכניסם להיכל ומניחם על גבי מזבח הזהב, כדי שיוכל חבירו להניח עליהם את הקטורת, מכל מקום \u0003לא היה פייס\u0004 מיוחד להולכת ה\u0003מחתה אלא כהן שזכה בקטרת אומר לזה שעמו\u0004 (שעומד סמוך לו) \u0003זכה עמי במחתה.\u0004 הרי שלא עשו פייס מיוחד לכל עבודה בנפרד!","ראיה זו דוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מחתה וקטרת דחדא עבודה היא\u0004 \u0005[ש\u0006כ\u0005עבודה אחת היא]\u0006 נחשבת, ולכן אין ראוי לעשותה בשני פייסות.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שממקור זה רצוננו להוכיח מתחילה הוכחה הפוכה: \u0003דוקא מחתה וקטרת דחדא עבודה\u0004 \u0005[ש\u0006כ\u0005עבודה אחת]\u0006 \u0003היא\u0004 אמר ר' יהודה שאין צורך בפייס לחוד \u0003אבל שאר עבודות — בעי\u0004 \u0005[צריך]\u0006 \u0003פייס\u0004 לכל אחת בנפרד!","ודוחים ראיה זו: מכאן אין להוכיח כי \u0003מחתה אצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לומר במפורש שאינה צריכה פייס, ולא משום שאין כן הסדר בשאר עבודות, אלא, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל\u0004 ועבודה זו \u0003לא שכיחא\u0004 \u0005[אינה מצויה]\u0006 שהרי נעשית רק פעמיים בכל יום ואינה כשאר הקרבנות שבאים נדבה \u0003ומעתרא\u0004 \u0005[והיא מעשירה],\u0006 שאמרו חכמים שהקטרת הקטורת היא סגולה לעושר, \u0003נתקין לה פייס בפני עצמה\u0004 שהרי רבים הקופצים עליה. \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי בכל זאת אין עושים כן, ואם כן אין מכאן ראיה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנה \u0003ר' חייא\u0004 במפורש: \u0003לא לכל עבודה ועבודה מפייסין, אלא כהן שזכה בתמיד שנים עשר אחיו הכהנים\u0004 העומדים סמוך לו \u0003נמשכין עמו\u0004 לשאר עבודות שבקרבן התמיד. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003פייס השני\u0004 מי שוחט מי זורק וכו'. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים השאלה: \u0003מי מקבל\u0004 את הדם? שהרי לא נזכר בין הזוכים בפייס הכהן המקבל את הדם היוצא בשעת שחיטה, שאותו יש לזרוק אחר כך על המזבח. ואם כן מובן שכהן העושה עבודה אחרת עוסק גם בקבלת הדם, ויש לחקור האם ה\u0003שוחט\u0004 עצמו \u0003מקבל,\u0004 וטעם הדבר: \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 כי ה\u0003זורק\u0004 הוא ש\u0003מקבל,\u0004 אם כן יכול להווצר מצב ש\u0003אגב חביבותיה\u0004 \u0005[חביבותה]\u0006 של המצוה, שהוא חפץ למהר ולזרוק אינו ממתין ו\u0003לא\u0004 \u0005[אינו]\u0006 \u0003מקבל ליה לכוליה\u0004 \u0005[את כל]\u0006 ה\u0003דם,\u0004 אלא כשיש בידו דם כדי זריקה ממהר הוא לזורקו.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר בצד אחר: כי \u0003זורק מקבל, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שה\u0003שוחט\u0004 הוא ש\u0003מקבל — זימנין דשחיט\u0004 \u0005[פעמים ששוחט]\u0006 \u0003זר,\u0004 שהרי שחיטת הקרבן אינה בין עבודות הקודש ומותרת בכל אדם, ולפי ההרגל יקבל הוא עצמו את הדם וישכח כי הקבלה מצות כהונה היא?","ומביאים ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה: הכהן הגדול \u0003בן קטין עשה שנים עשר דד\u0004 (פיות) \u0003לכיור\u0004 הגדול במקום שנים שהיו לו קודם \u0003כדי שיהיו שנים עשר אחיו הכהנים העסוקין בתמיד, מקדשין\u0004 (רוחצין) \u0003ידיהן ורגליהן בבת אחת.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי ה\u0003שוחט\u0004 הוא גם זה ה\u0003מקבל —\u0004 אם כן \u0003תליסר הוי\u0004 \u0005[שלושה עשר הם]\u0006 כפי שנמנו במשנה! כי לשחיטה בלבד אין חייבים לרחוץ ידים ורגלים, שכן אינה עבודת קודש וכשרה גם בזר, אולם אם השוחט הוא גם המקבל, ודאי שצריך הוא לרחוץ לפני הקבלה שהיא עבודת קודש! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ה\u0003זורק\u0004 הוא ה\u0003מקבל\u0004 את הדם. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אף אנן נמי תנינא\u0004 \u0005[אנו שנינו גם כן]\u0006 במשנתנו ראיה לדבר, שנאמר בסדר עבודת התמיד: \u0003שחט השוחט, וקבל המקבל ובא לו לזרוק\u0004 משמע שהמקבל הוא זה שזורק. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","במשנה הובא ש\u0003אמר בן עזאי לפני ר' עקיבא\u0004 בשם ר' יהושע שהיו מעלים את התמיד כדרך הילוכו, שחלקו הקדמי עולה תחילה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003כיצד דרך הלוכו?\u0004 — באופן זה: \u0003הראש והרגל\u0004 תחילה, ולאחריהם כסדר הזה \u0003החזה והגרה, ושתי ידים, ושתי דפנות, העוקץ\u0004 (הזנב) \u0003והרגל. ר' יוסי אומר: דרך הפשטו היה קרב, כיצד דרך הפשטו?\u0004 — מפשיטין אותו \u0003הראש והרגל\u0004 יחד, \u0003העוקץ והרגל\u0004 יחד, ואחר כך \u0003שתי דפנות, ושתי ידים, החזה והגרה.\u0004","ו\u0003ר' עקיבא אומר: דרך ניתוחו\u0004 לאיברים לאחר ההפשטה \u0003היה קרב.\u0004 ו\u0003כיצד דרך ניתוחו? — הראש והרגל, ושתי ידים, החזה, והגרה, ושתי דפנות, והעוקץ והרגל. ר' יוסי הגלילי אומר: דרך עילויו\u0004 (טיבו) \u0003היה קרב\u0004 שהחלקים המובחרים הם היו עולים ראשונה. \u0003כיצד דרך עילויו? — הראש והרגל, החזה והגרה, ושתי הדפנות, העוקץ והרגל\u0004 ולבסוף \u0003שתי הידים.\u0004","על דברי ר' יוסי הגלילי מקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"כל נתח טוב ירך וכתף\"\u0004 (יחזקאל כד, ד) משמע שאלה הם החלקים המובחרים, ומדוע אין ר' יוסי מקדימם (ר\"ח)? ומשיבים: \u0003ההיא\u0004 \u0005[יחזקאל כד, ד]\u0006 מדובר בצאן \u0003כחושה,\u0004 שבה אכן הירך והכתף הן המובחרות, אבל בכבש התמיד שהיו נוהגים להביאו מן המובחר, החלקים האחרים טובים יותר.","\u0003אמר רבא: בין\u0004 לשיטת \u0003תנא דידן\u0004 \u0005[התנא שלנו,\u0006 במשנתנו\u0005]\u0006 \u0003ובין\u0004 לשיטת \u0003ר' יוסי בתר עילויא דבישרא אזלינן\u0004 \u0005[אחר עילויו\u0006 וטיבו \u0005של הבשר הולכים]\u0006 וטעם ההבדל בדעותיהם הוא, כי \u0003מר אזיל בתר איברא דבישרא\u0004 \u0005[חכם זה\u0006, התנא שלנו, \u0005הולך אחר אבריו,\u0006 גודלו, \u0005של הבשר]\u0006 \u0003ומר\u0004 \u0005[חכם זה],\u0006 ר' יוסי, \u0003אזיל בתר שמנא דבישרא\u0004 \u0005[הולך אחר שומנו של הבשר].\u0006","ושואלים: לפי כל הדעות \u0003מאי טעמא סלקא\u0004 ה\u0003רגל\u0004 \u0005[מה הטעם עולה]\u0006 \u0003בהדי רישא\u0004 \u0005[יחד עם הראש],\u0006 ומה הקשר ביניהם? ומסבירים: \u0003משום דרישא נפישי ביה עצמות\u0004 \u0005[שבראש מרובות בו עצמות],\u0006 לכך \u0003קרבא\u0004 \u0005[קריבה]\u0006 גם ה\u0003רגל בהדיה\u0004 \u0005[עמו]\u0006 כדי להשלים למנה יפה.","ועוד שואלים: זה \u0003דכולי עלמא מיהת\u0004 \u0005[שלדעת הכל]\u0006 ה\u0003ראש קרב ברישא\u0004 \u0005[בתחילה],\u0006 \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 דבר זה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מניין לראש ופדר שקודמין לכל האברים\u0004 בהקרבה — \u0003תלמוד לומר:\u0004 \"וניתח אתו לנתחיו ו\u0003את ראשו ואת פדרו וערך\u0004 הכהן אותם על העצים אשר על האש אשר על המזבח\" (ויקרא א, יב). ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ה\u0003פדר אחרינא\u0004 \u0005[האחר]\u0006 שנאמר לאחר מכן: \"את הנתחים את הראש ואת הפדר\""]]};
